TURATH_CHUNK(75,[{"num":15000,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَاذَا يُبَاعِدُنِي مِنْ غَضَبِ اللَّهِ عَزَّ وَجَلَّ؟ قَالَ: لَا تَغْضَبْ."],"takhrij":"حسن: رواه أحمد (6635) عن حسن (هو ابن موسى)، حدثنا ابن لهيعة، حدثنا دراج، عن عبد الرحمن بن جبير، عن عبد الله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب الحذر من الغضب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (6635).","chapter_en":"Guarding against Anger","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":33,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ asked the Messenger of Allah ﷺ: “What will keep me far from the anger of Allah, Mighty and Majestic?” He replied: “Do not become angry.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6635)."},{"num":15001,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَا تَعُدُّونَ الرَّقُوبَ فِيكُمْ؟ قَالَ: قُلْنَا: الَّذِي لَا يُولَدُ لَهُ، قَالَ: لَيْسَ ذَاكَ بِالرَّقُوبِ، وَلَكِنَّهُ الرَّجُلُ الَّذِي لَمْ يُقَدِّمْ مِنْ وَلَدِهِ شَيْئًا قَالَ: فَمَا تَعُدُّونَ الصُّرَعَةَ فِيكُمْ؟ قَالَ: قُلْنَا: الَّذِي لَا يَصْرَعُهُ الرِّجَالُ، قَالَ: لَيْسَ بِذَلِكَ، وَلَكِنَّهُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2608: 106) من طرق عن الأعمش، عن إبراهيم التيمي، عن الحارث بن سويد، عن عبد الله بن مسعود، قال: فذكره.","grade":"صحيح","chapter_ar":"باب فضل من يملك نفسه عند الغضب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2608:106).","chapter_en":"The Virtue of One Who Controls Himself When Angry","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":34,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Whom do you consider to be the bereaved person among you?” We replied: “The one to whom no children are born.” He said: “That is not the truly bereaved person. Rather, it is the man who has not sent any of his children ahead of him in death.” Then he said: “Whom do you consider to be the strong wrestler among you?” We replied: “The one whom other men cannot throw down.” He said: “That is not the truly strong one. Rather, it is the one who controls himself when angry.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2608: 106)."},{"num":15002,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ."],"takhrij":"متفق عليه: رواه مالك في حسن الخلق (12) عن ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة فذكره. ورواه البخاري في الأدب (6114)، ومسلم في البر والصلة (2609: 107) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب فضل من يملك نفسه عند الغضب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in Ḥusn al-Khuluq (12), al-Bukhārī (6114), and Muslim (2609:107).","chapter_en":"The Virtue of One Who Controls Himself When Angry","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":34,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The strong man is not the one who defeats others in wrestling. The truly strong man is the one who controls himself when angry.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (12)، والبخاري (6114)، ومسلم (2609: 107)."},{"num":15003,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مرَّ بِقَوْمٍ يربعون حَجَرًا فَقَالَ: مَا يَصْنَعُ هَؤُلَاءِ؟ قَالُوا: يربعون حَجَرًا يُرِيدُونَ الشِّدَّةَ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَفَلَا أَدُلُّكُمْ عَلَى مَنْ هُوَ أشدّ مِنْهُ، أَوْ كَلِمَةٌ نَحْوَهَا - أملكُكم لِنَفْسِهِ عِنْدَ الْغَضَبِ.","وفي رواية عنه: أنّ النبي صلى الله عليه وسلم مرَّ بقومٍ يصطرعون فقال: ما هذا ؟ قالوا: يا رسول الله صلى الله عليه وسلم هذا فلان الصريع، ما يصارعُ أحدًا إلاَّ صرعَه، فقال رسول الله صلى الله عليه وسلم: ألا أدلّكم على من هو أشدّ منه: رجلٌ ظلمه رجلٌ فكظم غيظَه، فغلبَه، وغلبَ شيطانَه، وغلبَ شيطانَ صاحبه."],"takhrij":"حسن: رواهما البزار في مسنده (7270، 7272) عن إبراهيم بن المستمر العروقي، حدثنا شعيب بن بيان، حدثنا عمران (هو القطان)، عن قتادة، عن أنس قال: فذكره.","grade":"حسن","chapter_ar":"باب فضل من يملك نفسه عند الغضب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Both narrations were reported by al-Bazzār in his Musnad (7270, 7272).","chapter_en":"The Virtue of One Who Controls Himself When Angry","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":34,"content":{"translation":{"en":["Anas narrated: The Prophet ﷺ passed by some people who were lifting a heavy stone. He asked: “What are these people doing?” They replied: “They are lifting a stone to demonstrate their strength.” The Prophet ﷺ said: “Shall I not tell you who is stronger than him—or words to that effect? The strongest among you is the one who has the greatest control over himself when angry.” In another narration, the Prophet ﷺ passed by some people wrestling and asked: “What is this?” They replied: “O Messenger of Allah, this man is an unbeatable wrestler. He wrestles no one except that he throws him down.” The Messenger of Allah ﷺ said: “Shall I not tell you who is stronger than him? A man whom another person wrongs, yet he suppresses his anger. In doing so, he overcomes him, overcomes his own devil, and overcomes the devil of his companion.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواهما البزار في مسنده (7270، 7272)."},{"num":15004,"demo":false,"sanad":"","matn":["عن سُلَيْمَانَ بن صرد، قَالَ: اسْتَبَّ رَجُلاَنِ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ عِنْدَهُ جُلُوسٌ، وَأَحَدُهُمَا يَسُبُّ صَاحِبَهُ، مُغْضَبًا قَدِ احْمَرَّ وَجْهُهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي لأَعْلَمُ كَلِمَةً، لَوْ قَالَهَا لَذَهَبَ عَنْهُ مَا يَجِدُ، لَوْ قَالَ: أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ. فَقَالُوا لِلرَّجُلِ: أَلاَ تَسْمَعُ مَا يَقُولُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: إِنِّي لَسْتُ بِمَجْنُونٍ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6115)، ومسلم في البر والصلة (2610) كلاهما من طرق عن الأعمش، عن عدي بن ثابت، حدثنا سليمان بن صرد، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يقال وما يفعل عند الغضب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6115) and Muslim (2610).","chapter_en":"What Should Be Said and Done When Angry","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":35,"content":{"translation":{"en":["Sulaymān ibn Ṣurad narrated: Two men insulted one another in the presence of the Prophet ﷺ while we were sitting with him. One of them was angrily insulting the other, and his face had become red. The Prophet ﷺ said: “I know a statement which, if he were to say it, what he is experiencing would leave him. If he said: ‘I seek refuge in Allah from Satan, the accursed.’” The people said to the man: “Do you not hear what the Prophet ﷺ is saying?” He replied: “I am not insane.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6115)، ومسلم (2610)."},{"num":15005,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ: كَانَ يَسْقِي عَلَى حَوْضٍ لَهُ، فَجَاءَ قَوْمٌ فَقَالَ: أَيُّكُمْ يُورِدُ عَلَى أَبِي ذَرٍّ وَيَحْتَسِبُ شَعَرَاتٍ مِنْ رَأْسِهِ؟ فَقَالَ رَجُلٌ: أَنَا، فَجَاءَ الرَّجُلُ فَأَوْرَدَ عَلَيْهِ الْحَوْضَ فَدَقَّهُ، وَكَانَ أَبُو ذَرٍّ قَائِمًا فَجَلَسَ، ثُمَّ اضْطَجَعَ، فَقِيلَ لَهُ: يَا أَبَا ذَرٍّ، لِمَ جَلَسْتَ، ثُمَّ اضْطَجَعْتَ؟ قَالَ: فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَنَا: إِذَا غَضِبَ أَحَدُكُمْ وَهُوَ قَائِمٌ فَلْيَجْلِسْ، فَإِنْ ذَهَبَ عَنْهُ الْغَضَبُ، وَإِلَّا فَلْيَضْطَجِعْ."],"takhrij":"صحيح: رواه أحمد (21348) عن أبي معاوية، حدثنا داود بن أبي هند، عن أبي حرب بن أبي الأسود، عن أبي الأسود، عن أبي ذر فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يقال وما يفعل عند الغضب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (21348).","chapter_en":"What Should Be Said and Done When Angry","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":35,"content":{"translation":{"en":["Abū Dharr narrated: He was drawing water at a trough belonging to him when some people came. He said: “Which of you will draw water for Abū Dharr and earn a reward, even if it costs him a few hairs from his head?” A man said: “I will.” The man came to draw water at the trough and broke it. Abū Dharr had been standing, so he sat down and then lay down. He was asked: “O Abū Dharr, why did you sit down and then lie down?” He replied: The Messenger of Allah ﷺ said to us: “If one of you becomes angry while standing, let him sit down. If his anger leaves him, then so be it; otherwise, let him lie down.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (21348)."},{"num":15006,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَخَلَ عَلَىَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِي الْبَيْتِ قِرَامٌ فِيهِ صُوَرٌ، فَتَلَوَّنَ وَجْهُهُ، ثُمَّ تَنَاوَلَ السِّتْرَ فَهَتَكَهُ، وَقَالَتْ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مِنْ أَشَدِّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ الَّذِينَ يُصَوِّرُونَ هَذِهِ الصُّوَرَ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6109)، ومسلم في اللباس والزينة (2107: 91) كلاهما من طريق الزهري، عن القاسم، عن عائشة فذكرته. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب متى يجوز الغضب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6109) and Muslim (2107:91).","chapter_en":"When Anger Is Permissible","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":36,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Prophet ﷺ entered upon me while there was a curtain in the house containing images. His facial expression changed, then he seized the curtain and tore it down. ʿĀ’ishah said that the Prophet ﷺ said: “Among the people who will receive the severest punishment on the Day of Resurrection are those who make these images.”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ﴾ [التوبة: ٧٣]."],"en":["Allah, the Exalted, says:","“O Prophet, strive against the disbelievers and the hypocrites and be firm with them. Their refuge is Hell, and what an evil destination.”","[Sūrat al-Tawbah 9:73]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6109)، ومسلم (2107: 91)."},{"num":15007,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَى رَجُلٌ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي لأَتَأَخَّرُ عَنْ صَلاَةِ الْغَدَاةِ، مِنْ أَجْلِ فُلاَنٍ مِمَّا يُطِيلُ بِنَا، قَالَ: فَمَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَطُّ أَشَدَّ غَضَبًا فِي مَوْعِظَةٍ مِنْهُ يَوْمَئِذٍ، قَالَ: فَقَالَ: يَا أَيُّهَا النَّاسُ، إِنَّ مِنْكُمْ مُنَفِّرِينَ، فَأَيُّكُمْ مَا صَلَّى بِالنَّاسِ فَلْيَتَجَوَّزْ، فَإِنَّ فِيهِمُ الْمَرِيضَ وَالْكَبِيرَ وَذَا الْحَاجَةِ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6110)، ومسلم في الصلاة (466) كلاهما من طريق إسماعيل بن أبي خالد، حدثنا قيس بن أبي حازم، عن أبي مسعود فذكره.","grade":"متفق عليه","chapter_ar":"باب متى يجوز الغضب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6110) and Muslim (466).","chapter_en":"When Anger Is Permissible","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":36,"content":{"translation":{"en":["Abū Masʿūd narrated: A man came to the Prophet ﷺ and said: “I sometimes delay attending the morning prayer because so-and-so prolongs the prayer for us.” Abū Masʿūd said: I never saw the Messenger of Allah ﷺ more intensely angry while delivering an admonition than he was that day. He said: “O people, some of you drive people away. Whoever among you leads the people in prayer should keep it reasonably brief, for among them are the sick, the elderly, and those who have needs.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6110)، ومسلم (466)."},{"num":15008,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، رَأَى فِي قِبْلَةِ الْمَسْجِدِ نُخَامَةً، فَحَكَّهَا بِيَدِهِ، فَتَغَيَّظَ، ثُمَّ قَالَ: إِنَّ أَحَدَكُمْ إِذَا كَانَ فِي الصَّلاَةِ، فَإِنَّ اللَّهَ حِيَالَ وَجْهِهِ، فَلاَ يَتَنَخَّمَنَّ حِيَالَ وَجْهِهِ فِي الصَّلاَةِ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6111) عن موسى بن إسماعيل، حدثنا جويرية، عن نافع، عن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب متى يجوز الغضب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6111) and Muslim (547).","chapter_en":"When Anger Is Permissible","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":36,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated: While the Prophet ﷺ was praying, he saw some phlegm on the qiblah wall of the mosque. He scraped it away with his hand and became angry. Then he said: “When one of you is in prayer, Allah is before his face, so he must not spit phlegm in front of himself while praying.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6111)، ومسلم (547)."},{"num":15009,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، أَنَّ رَجُلاً، سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ اللُّقَطَةِ، فَقَالَ: عَرِّفْهَا سَنَةً، ثُمَّ اعْرِفْ وِكَاءَهَا وَعِفَاصَهَا، ثُمَّ اسْتَنْفِقْ بِهَا، فَإِنْ جَاءَ رَبُّهَا فَأَدِّهَا إِلَيْهِ. قَالَ: يَا رَسُولَ اللَّهِ، فَضَالَّةُ الْغَنَمِ؟ قَالَ: خُذْهَا، فَإِنَّمَا هِيَ لَكَ، أَوْ لأَخِيكَ، أَوْ لِلذِّئْبِ. قَالَ: يَا رَسُولَ اللَّهِ، فَضَالَّةُ الإِبِلِ؟ قَالَ: فَغَضِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى احْمَرَّتْ وَجْنَتَاهُ ـ أَوِ احْمَرَّ وَجْهُهُ ـ ثُمَّ قَالَ: مَالَكَ وَلَهَا، مَعَهَا حِذَاؤُهَا وَسِقَاؤُهَا، حَتَّى يَلْقَاهَا رَبُّهَا."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6112)، ومسلم في اللقطة (1722: 2) كلاهما من طريق إسماعيل بن جعفر، أخبرنا ربيعة بن أبي عبد الرحمن، عن يزيد مولى المنبعث، عن زيد بن خالد الجهني فذكره.","grade":"متفق عليه","chapter_ar":"باب متى يجوز الغضب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6112) and Muslim (1722:2).","chapter_en":"When Anger Is Permissible","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":36,"content":{"translation":{"en":["Zayd ibn Khālid al-Juhanī narrated: A man asked the Messenger of Allah ﷺ about lost property. He said: “Announce it for a year. Then remember the tying-string of its container and its covering, and afterward make use of it. If its owner comes, return it to him.” The man asked: “O Messenger of Allah, what about a stray sheep?” He replied: “Take it, for it belongs either to you, to your brother, or to the wolf.” The man then asked: “O Messenger of Allah, what about a stray camel?” The Messenger of Allah ﷺ became angry until his cheeks—or his face—turned red. Then he said: “What concern is it of yours? It has its own feet and its own water supply, and it can survive until its owner finds it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6112)، ومسلم (1722: 2)."},{"num":15010,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا قَاتَلَ أَحَدُكُمْ أَخَاهُ فَلْيَجْتَنِبِ الْوَجْهَ وَفِي لفظ: إِذَا قَاتَلَ أَحَدُكُمْ أَخَاهُ، فَلْيَجْتَنِبِ الْوَجْهَ، فَإِنَّ اللَّهَ خَلَقَ آدَمَ عَلَى صُورَتِهِ."],"takhrij":"متفق عليه: رواه البخاري في العتق (2559) من طريق أبي سعيد المقبري وهمام، ورواه مسلم في البر والصلة (2612) من طريق الأعرج وأبي سهيل وأبي أيوب، كلهم عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن ضرب الوجه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2559) and Muslim (2612).","chapter_en":"The Prohibition of Striking the Face","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":37,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When one of you fights his brother, let him avoid the face.” In another wording: “When one of you fights his brother, let him avoid the face, for Allah created Ādam in his image.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2559)، ومسلم (2612)."},{"num":15011,"demo":false,"sanad":"","matn":["عَنْ هِشَامِ بن حَكِيمٍ بْنِ حِزَامٍ، قَالَ: أَمَا إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ يُعَذِّبُ الَّذِينَ يُعَذِّبُونَ فِي الدُّنْيَا."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2613: 117) عن أبي بكر بن أبي شيبة، حدثنا حفص بن غياث، عن هشام بن عروة، عن أبيه، عن هشام بن حكيم بن حزام، قال: مرَّ بالشام على أناس، وقد أقيموا في الشمس، وصب على رؤوسهم الزيت، فقال: ما هذا؟ قيل: يعذبون في الخراج، فقال: أما إني سمعت رسول الله صلى الله عليه وسلم يقول: فذكره.","grade":"صحيح","chapter_ar":"باب الوعيد الشديد لمن عذب الناس بغير حق","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2613:117).","chapter_en":"The Severe Warning against Those Who Torture People without Right","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":38,"content":{"translation":{"en":["Hishām ibn Ḥakīm ibn Ḥizām said: Indeed, I heard the Messenger of Allah ﷺ say: “Allah will punish those who torture people in this world.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2613: 117)."},{"num":15012,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، ـ رَضِيَ اللَّهُ عَنْهَا أَنَّ يَهُودَ، أَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: السَّامُ عَلَيْكُمْ. فَقَالَتْ عَائِشَةُ: عَلَيْكُمْ، وَلَعَنَكُمُ اللَّهُ، وَغَضِبَ اللَّهُ عَلَيْكُمْ. قَالَ: مَهْلاً يَا عَائِشَةُ، عَلَيْكِ بِالرِّفْقِ، وَإِيَّاكِ وَالْعُنْفَ وَالْفُحْشَ. قَالَتْ: أَوَلَمْ تَسْمَعْ مَا قَالُوا؟ قَالَ: أَوَلَمْ تَسْمَعِي مَا قُلْتُ؟ رَدَدْتُ عَلَيْهِمْ، فَيُسْتَجَابُ لِي فِيهِمْ، وَلاَ يُسْتَجَابُ لَهُمْ فِيَّ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6030) عن محمد بن سلام، أخبرنا عبدالوهاب، عن أيوب، عن عبد الله بن أبي مليكة، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب النهي عن الفحش","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6030) and Muslim (2165).","chapter_en":"The Prohibition of Obscene and Abusive Speech","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":39,"content":{"translation":{"en":["ʿĀ’ishah narrated: Some Jews came to the Prophet ﷺ and said: “Death be upon you.” ʿĀ’ishah replied: “And upon you, and may Allah curse you and be angry with you.” The Prophet ﷺ said: “Easy, O ʿĀ’ishah. You must be gentle, and beware of harshness and obscene speech.” She said: “Did you not hear what they said?” He replied: “Did you not hear what I said? I answered them, so my supplication concerning them will be answered, while theirs concerning me will not be answered.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6030)، ومسلم (2165)."},{"num":15013,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:  مَنْ خَرَجَ مِنَ الطَّاعَةِ، وَفَارَقَ الْجَمَاعَةَ فَمَاتَ، مَاتَ مِيتَةً جَاهِلِيَّةً، وَمَنْ قَاتَلَ تَحْتَ رَايَةٍ عُِمِّيَّةٍ، يَغْضَبُ لِعَصَبَةٍ، أَوْ يَدْعُو إِلَى عَصَبَةٍ، أَوْ يَنْصُرُ عَصَبَةً، فَقُتِلَ، فَقِتْلَةٌ جَاهِلِيَّةٌ، وَمَنْ خَرَجَ عَلَى أُمَّتِي، يَضْرِبُ بَرَّهَا وَفَاجِرَهَا، وَلَا يَتَحَاشَ مِنْ مُؤْمِنِهَا، وَلَا يَفِي لِذِي عَهْدٍ عَهْدَهُ، فَلَيْسَ مِنِّي وَلَسْتُ مِنْهُ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1848) عن شيبان بن فروخ، حدثنا جرير يعني ابن حازم، حدثنا غيلان بن جرير، عن أبي قيس بن رياح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ذم العصبية","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1848).","chapter_en":"What Has Been Narrated Concerning the Condemnation of Partisanship and Tribal Fanaticism","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":40,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Whoever withdraws from obedience, separates from the community, and then dies, dies a death of jāhiliyyah. Whoever fights beneath a blind banner, becoming angry for tribal partisanship, calling to tribal partisanship, or supporting tribal partisanship, and is killed, his death is a death of jāhiliyyah. And whoever rises against my Ummah, striking both its righteous and its wicked, showing no restraint toward its believers, and not fulfilling the covenant of those who have a covenant, is not from me and I am not from him.”"]}},"tuhfa":{},"full":1,"rep":[7664],"tks":"صحيح: رواه مسلم (1848)."},{"num":15014,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ قَالَ: كُنَّا فِي غَزَاةٍ فَكَسَعَ رَجُلٌ مِنَ الْمُهَاجِرِينَ رَجُلاً مِنَ الأَنْصَارِ، فَقَالَ الأَنْصَارِيُّ: يَا لَلأَنْصَارِ، وَقَالَ الْمُهَاجِرِيُّ: يَا لَلْمُهَاجِرِينَ، فَسَمِعَ ذَلِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَا بَالُ دَعْوَى الْجَاهِلِيَّةِ قَالُوا: يَا رَسُولَ اللَّهِ، كَسَعَ رَجُلٌ مِنَ الْمُهَاجِرِينَ رَجُلاً مِنَ الأَنْصَارِ، فَقَالَ: دَعُوهَا فَإِنَّهَا مُنْتِنَةٌ فَسَمِعَ بِذَلِكَ عَبْدُ اللَّهِ بْنُ أَبِي، فَقَالَ: فَعَلُوهَا، أَمَا وَاللَّهِ لَئِنْ رَجَعْنَا إِلَى الْمَدِينَةِ لَيُخْرِجَنَّ الأَعَزُّ مِنْهَا الأَذَلَّ، فَبَلَغَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَامَ عُمَرُ فَقَالَ: يَا رَسُولَ اللَّهِ: دَعْنِي أَضْرِبْ عُنُقَ هَذَا الْمُنَافِقِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: دَعْهُ، لاَ يَتَحَدَّثُ النَّاسُ أَنَّ مُحَمَّدًا يَقْتُلُ أَصْحَابَهُ وَكَانَتِ الأَنْصَارُ أَكْثَرَ مِنَ الْمُهَاجِرِينَ حِينَ قَدِمُوا الْمَدِينَةَ، ثُمَّ إِنَّ الْمُهَاجِرِينَ كَثُرُوا بَعْدُ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4095، 4907)، ومسلم في البر والصلة (2584: 63) كلاهما من طرق عن سفيان بن عيينة، عن عمرو بن دينار قال: سمعت جابر بن عبد الله فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في ذم العصبية","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4095, 4907) and Muslim (2584:63). The wording is that of al-Bukhārī.","chapter_en":"What Has Been Narrated Concerning the Condemnation of Partisanship and Tribal Fanaticism","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":40,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: We were on a military expedition when a man from the Muhājirūn struck a man from the Anṣār on the backside. The Anṣārī called out: “O Anṣār!” And the Muhājir called out: “O Muhājirūn!” The Messenger of Allah ﷺ heard this and said: “What is this call of jāhiliyyah?” They said: “O Messenger of Allah, a man from the Muhājirūn struck a man from the Anṣār.” He said: “Leave it, for it is foul.” When ʿAbdullāh ibn Ubayy heard about this, he said: “They have done it! By Allah, when we return to Madinah, the mightier will surely expel the more humiliated from it.” This reached the Prophet ﷺ. ʿUmar stood up and said: “O Messenger of Allah, allow me to strike the neck of this hypocrite.” The Prophet ﷺ replied: “Leave him, lest people say that Muḥammad kills his own companions.” The Anṣār were more numerous than the Muhājirūn when they first came to Madinah, but later the Muhājirūn increased in number."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4095، 4907)، ومسلم (2584: 63)، واللفظ للبخاري."},{"num":15015,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ:  اقْتَتَلَ غُلَامَانِ غُلَامٌ مِنَ الْمُهَاجِرِينَ، وَغُلَامٌ مِنَ الْأَنْصَارِ، فَنَادَى الْمُهَاجِرُ أَوِ الْمُهَاجِرُونَ: يَا لَلْمُهَاجِرِينَ، وَنَادَى الْأَنْصَارِيُّ: يَا لَلْأَنْصَارِ. فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَا هَذَا دَعْوَى أَهْلِ الْجَاهِلِيَّةِ؟ قَالُوا: لَا يَا رَسُولَ اللَّهِ إِلَّا أَنَّ غُلَامَيْنِ اقْتَتَلَا فَكَسَعَ أَحَدُهُمَا الْآخَرَ، قَالَ: فَلَا بَأْسَ وَلْيَنْصُرِ الرَّجُلُ أَخَاهُ ظَالِمًا أَوْ مَظْلُومًا، إِنْ كَانَ ظَالِمًا فَلْيَنْهَهُ، فَإِنَّهُ لَهُ نَصْرٌ، وَإِنْ كَانَ مَظْلُومًا فَلْيَنْصُرْهُ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2584: 62) عن أحمد بن عبد الله بن يونس، حدثنا زهير، حدثنا أبو الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ذم العصبية","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2584:62).","chapter_en":"What Has Been Narrated Concerning the Condemnation of Partisanship and Tribal Fanaticism","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":40,"content":{"translation":{"en":["Jābir narrated: Two young men fought, one from the Muhājirūn and one from the Anṣār. The Muhājir—or the Muhājirūn—called: “O Muhājirūn!” And the Anṣārī called: “O Anṣār!” The Messenger of Allah ﷺ came out and said: “What is this? The call of the people of jāhiliyyah?” They replied: “No, O Messenger of Allah. It is only that two young men fought and one struck the other.” He said: “Then there is no harm. Let a man support his brother whether he is an oppressor or oppressed. If he is an oppressor, let him restrain him, for that is supporting him. And if he is oppressed, then let him help him.”"]}},"tuhfa":{},"full":1,"rep":[5930],"tks":"صحيح: رواه مسلم (2584: 62)."},{"num":15016,"demo":false,"sanad":"","matn":["عَنْ وَاثِلَةَ بْنِ الأسقع قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، مَا الْعَصَبِيَّةُ؟ قَالَ: أَنْ تُعِينَ قَوْمَكَ عَلَى الظُّلْمِ."],"takhrij":"حسن: رواه أبو داود (5119) عن محمود بن خالد الدمشقي، حدثنا الفريابي، حدثنا سلمة بن بشر الدمشقي، عن بنت واثلة بن الأسقع، أنها سمعت أباها، يقول: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ذم العصبية","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (5119).","chapter_en":"What Has Been Narrated Concerning the Condemnation of Partisanship and Tribal Fanaticism","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":40,"content":{"translation":{"en":["Wāthilah ibn al-Asqaʿ narrated: I asked: “O Messenger of Allah, what is tribal partisanship?” He replied: “That you support your people in wrongdoing.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (5119)."},{"num":15017,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَذْهَبَ عَنْكُمْ عُبِّيَّةَ الْجَاهِلِيَّةِ وَفَخْرَهَا بِالآبَاءِ مُؤْمِنٌ تَقِيٌّ وَفَاجِرٌ شَقِيٌّ، أَنْتُمْ بَنُو آدَمَ وَآدَمُ مِنْ تُرَابٍ، لَيَدَعَنَّ رِجَالٌ فَخْرَهُمْ بِأَقْوَامٍ إِنَّمَا هُمْ فَحْمٌ مِنْ فَحْمِ جَهَنَّمَ، أَوْ لَيَكُونُنَّ أَهْوَنَ عَلَى اللَّهِ مِنَ الْجِعْلاَنِ الَّتِي تَدْفَعُ بِأَنْفِهَا النَّتْنَ."],"takhrij":"حسن: رواه أبو داود (5116) واللفظ له، والترمذي (3956) كلاهما من حديث هشام بن سعد، عن سعيد بن أبي سعيد، عن أبيه، عن أبي هريرة، قال: فذكره.","grade":"حسن","chapter_ar":"باب ذم التفاخر بالأحساب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (5116), and this is his wording, and al-Tirmidhī (3956).","chapter_en":"Condemnation of Boasting about Lineage","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":41,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Allah, Mighty and Majestic, has removed from you the arrogance of jāhiliyyah and its boasting about forefathers. A person is either a God-fearing believer or a wretched sinner. You are all children of Ādam, and Ādam was created from dust. People must stop boasting about peoples who are merely pieces of coal from the coal of Hell, or else they will become more insignificant before Allah than dung beetles that push filth with their noses.”"]},"buhuth":{"en":["The word “al-ʿubiyyah” means arrogance and pride. Its root derives from al-ʿibʾ, meaning a heavy burden. It may be pronounced with either a ḍammah or kasrah on the ʿayn.","The words “a God-fearing believer and a wretched sinner” mean that people fall into two categories:","A God-fearing believer is the good and virtuous person even if he has no noble lineage among his people, while the wicked sinner is lowly even if he is regarded as noble and elevated among his family.","Al-Khaṭṭābī explained it this way.","The word “al-juʿlān” is the plural of juʿal, a type of beetle that rolls filth with its nose."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (5116) واللفظ له، والترمذي (3956)."},{"num":15018,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَفْتَخِرُوا بِآبَائِكُمُ الَّذِينَ مُوِّتُوا فِي الْجَاهِلِيَّةِ، فَوَالَّذِي نَفْسِي بِيَدِهِ، لَمَا يُدَهْدِهُ الْجُعَلُ بِمَنْخِرَيْهِ خَيْرٌ مِنْ آبَائِكُمُ الَّذِينَ مَاتُوا فِي الْجَاهِلِيَّةِ."],"takhrij":"صحيح: رواه أبو داود الطيالسي (2804)، ومن طريقه أحمد (2739)، وابن حبان (5775) عن هشام الدستوائي، عن أيوب السختياني، عن عكرمة،عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ذم التفاخر بالأحساب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd al-Ṭayālisī (2804), and through him Aḥmad (2739), and Ibn Ḥibbān (5775).","chapter_en":"Condemnation of Boasting about Lineage","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":41,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated that the Messenger of Allah ﷺ said: “Do not boast about your forefathers who died in jāhiliyyah. By the One in whose Hand is my soul, what a dung beetle rolls away with its nostrils is better than your forefathers who died in jāhiliyyah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود الطيالسي (2804)، ومن طريقه أحمد (2739)، وابن حبان (5775)."},{"num":15019,"demo":false,"sanad":"","matn":["عَنْ أُبَيِّ بْنِ كَعْبٍ قَالَ: انْتَسَبَ رَجُلَانِ عَلَى عَهْدِ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَحَدُهُمَا: أَنَا فُلَانُ بْنُ فُلَانٍ فَمَنْ أَنْتَ؟ لَا أُمَّ لَكَ، فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : انْتَسَبَ رَجُلَانِ عَلَى عَهْدِ مُوسَى عَلَيْهِ السَّلَام، فَقَالَ أَحَدُهُمَا: أَنَا فُلَانُ بْنُ فُلَانٍ حَتَّى عَدَّ تِسْعَةً، فَمَنْ أَنْتَ؟ لَا أُمَّ لَكَ، قَالَ: أَنَا فُلَانُ بْنُ فُلَانٍ ابْنُ الْإِسْلَامِ، قَالَ: فَأَوْحَى الله إِلَى مُوسَى عَلَيْهِ السَّلَام: أَنَّ هَذَيْنِ المُنْتَسِبَيْنِ: أَمَّا أَنْتَ أَيُّهَا المُنْتَمِي أَوْ المُنْتَسِبُ إِلَى تِسْعَةٍ فِي النَّارِ فَأَنْتَ عَاشِرُهُمْ، وَأَمَّا أَنْتَ يَا هَذَا المُنْتَسِبُ إِلَى اثْنَيْنِ فِي الجَنَّةِ فَأَنْتَ ثَالِثُهُمَا فِي الجَنَّةِ."],"takhrij":"حسن: رواه عبد الله بن أحمد في زوائد المسند (21178)، وعبد بن حميد (179) كلاهما عن أبي بكر بن أبي شيبة، حدثنا عبد الله بن نمير، حدثنا يزيد بن زياد بن أبي الجعد، عن عبد الملك بن عمير، عن عبد الرحمن بن أبي ليلى، عن أبي بن كعب فذكره.","grade":"حسن","chapter_ar":"باب ذم التفاخر بالأحساب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by ʿAbdullāh ibn Aḥmad in Zawāʾid al-Musnad (21178) and ʿAbd ibn Ḥumayd (179).","chapter_en":"Condemnation of Boasting about Lineage","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":41,"content":{"translation":{"en":["Ubayy ibn Kaʿb narrated: Two men boasted of their lineage during the time of the Messenger of Allah ﷺ. One of them said: “I am so-and-so, son of so-and-so,” and continued naming his lineage, then said: “Who are you? May you have no mother!” The Messenger of Allah ﷺ said: “Two men boasted of their lineage during the time of Mūsā, peace be upon him. One of them said: ‘I am so-and-so son of so-and-so,’ until he counted nine ancestors, then said: ‘Who are you? May you have no mother!’ The other said: ‘I am so-and-so son of so-and-so, a son of Islam.’ Allah then revealed to Mūsā, peace be upon him, concerning the two men: ʿAs for you who affiliated yourself with nine men in the Fire, you are their tenth. And as for you who affiliated yourself with two men in Paradise, you are their third in Paradise.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عبد الله بن أحمد في زوائد المسند (21178)، وعبد بن حميد (179)."},{"num":15020,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ، يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: كُلُّ أُمَّتِي مُعَافًى إِلاَّ الْمُجَاهِرِينَ، وَإِنَّ مِنَ الْمَجَانَةِ أَنْ يَعْمَلَ الرَّجُلُ بِاللَّيْلِ عَمَلاً، ثُمَّ يُصْبِحَ وَقَدْ سَتَرَهُ اللَّهُ، فَيَقُولَ: يَا فُلاَنُ، عَمِلْتُ الْبَارِحَةَ كَذَا وَكَذَا، وَقَدْ بَاتَ يَسْتُرُهُ رَبُّهُ، وَيُصْبِحُ يَكْشِفُ سِتْرَ اللَّهِ عَنْهُ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6069)، ومسلم في الزهد (2990) كلاهما من طريق ابن أخي ابن شهاب، عن ابن شهاب، عن سالم بن عبد الله، قال: سمعت أبا هريرة، يقول: فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب التحذير من المجاهرة بالفسق","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6069) and Muslim (2990). The wording is that of al-Bukhārī.","chapter_en":"Warning against Openly Publicizing Sin","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":42,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Messenger of Allah ﷺ say: “All of my Ummah may be pardoned except those who openly publicize their sins. Part of openly publicizing sin is that a man commits a deed at night, then wakes in the morning after Allah has concealed it for him, and says: ‘O so-and-so, last night I did such-and-such.’ His Lord had concealed him throughout the night, yet in the morning he removes Allah’s covering from himself.”"]}},"tuhfa":{},"full":1,"rep":[13956],"tks":"متفق عليه: رواه البخاري (6069)، ومسلم (2990)، واللفظ للبخاري."},{"num":15021,"demo":false,"sanad":"","matn":["عن عبد الله بن زمعة، قال: خطب رسول الله صلى الله عليه وسلم ثم وعظهم في ضحكهم من الضرطة فقال: إلام يضحك أحدكم مما يفعل؟."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4942)، ومسلم في الجنة (2855) كلاهما من طريق هشام بن عروة، عن أبيه، عن عبد الله بن زمعة، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن الضحك عند الضرطة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4942) and Muslim (2855).","chapter_en":"The Prohibition of Laughing When Someone Passes Wind","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":43,"content":{"translation":{"en":["ʿAbdullāh ibn Zamʿah narrated: The Messenger of Allah ﷺ delivered a sermon and admonished the people concerning their laughter when someone passed wind. He said: “Why does one of you laugh at something that he himself does?”"]},"buhuth":{"en":["The word “al-ḍarṭ” refers to passing wind with a sound.","The hadith prohibits laughing when one hears another person pass wind. Rather, one should overlook it, continue with his conversation and whatever he was occupied with, pay no attention to it, and behave as though he had not heard it.","The hadith therefore directs toward good manners and proper social conduct."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4942)، ومسلم (2855)."},{"num":15022,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تُكْثِرُوا الضَّحِكَ، فَإِنَّ كَثْرَةَ الضَّحِكِ تُمِيتُ الْقَلْبَ."],"takhrij":"حسن: رواه ابن ماجه (4193)، والبخاري في الأدب المفرد (253) كلاهما من طريق أبي بكر الحنفي (واسمه عبد الكبير بن عبد المجيد البصري)، حدثنا عبدالحميد بن جعفر، عن إبراهيم بن عبد الله بن حنين، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب النهي عن كثرة الضحك","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (4193) and al-Bukhārī in al-Adab al-Mufrad (253).","chapter_en":"The Prohibition of Excessive Laughter","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":44,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Do not laugh excessively, for excessive laughter deadens the heart.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15114],"tks":"حسن: رواه ابن ماجه (4193)، والبخاري في الأدب المفرد (253)."},{"num":15023,"demo":false,"sanad":"","matn":["عن سَعْدِ بن أَبِي وَقَّاصٍ، عَنْ أَبِيهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَعْظَمَ الْمُسْلِمِينَ جُرْمًا، مَنْ سَأَلَ عَنْ شَىْءٍ لَمْ يُحَرَّمْ، فَحُرِّمَ مِنْ أَجْلِ مَسْأَلَتِهِ."],"takhrij":"متفق عليه: رواه البخاري في الاعتصام (7289)، ومسلم في الفضائل (2358: 132) كلاهما من طريق ابن شهاب، عن عامر بن سعد بن أبي وقاص، عن أبيه، فذكره.","grade":"متفق عليه","chapter_ar":"باب التحذير من كثرة السؤال والتنطع والغلو في الدين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7289) and Muslim (2358:132).","chapter_en":"Warning against Excessive Questioning, Over-Scrupulousness, and Extremism in Religion","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":45,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ narrated that the Prophet ﷺ said: “The Muslim who commits the gravest offense against the Muslims is the one who asks about something that had not been prohibited, and it then becomes prohibited because of his questioning.”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ﴾ [سورة المائدة: ١٠١].","وقال تعالى:","﴿يَا أَهْلَ الْكِتَابِ لَا تَغْلُوا فِي دِينِكُمْ وَلَا تَقُولُوا عَلَى اللّٰهِ إِلَّا الْحَقَّ﴾ [النساء: ١٧١]."],"en":["Allah, the Exalted, says:","“O you who believe, do not ask about matters which, if made known to you, would distress you.”","[Sūrat al-Māʾidah 5:101]","And He, the Exalted, says:","“O People of the Book, do not go to extremes in your religion, and do not say about Allah except the truth.”","[Sūrat al-Nisāʾ 4:171]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7289)، ومسلم (2358: 132)."},{"num":15024,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ يَقُولُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَنْ يَبْرَحَ النَّاسُ يَتَسَاءَلُونَ حَتَّى يَقُولُوا: هَذَا اللَّهُ خَالِقُ كُلِّ شَىْءٍ، فَمَنْ خَلَقَ اللَّهَ.","وفي لفظ عنه: عَنْ رَسُولِ اللهِ صلى الله عليه وسلم قَالَ: قَالَ اللهُ عز وجل: إِنَّ أُمَّتَكَ لَا يَزَالُونَ يَقُولُونَ: مَا كَذَا؟ مَا كَذَا؟ حَتَّى يَقُولُوا: هَذَا اللهُ خَلَقَ الْخَلْقَ فَمَنْ خَلَقَ اللهَ."],"takhrij":"متفق عليه: رواه البخاري في الاعتصام (7296) عن الحسن بن صباح، حدثنا شبابة، حدثنا ورقاء، عن عبد الله بن عبد الرحمن، سمعت أنس بن مالك، يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب التحذير من كثرة السؤال والتنطع والغلو في الدين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7296) and Muslim (136).","chapter_en":"Warning against Excessive Questioning, Over-Scrupulousness, and Extremism in Religion","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":45,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “People will continue asking one another questions until they say: ‘Allah created everything, so who created Allah?’” In another wording, the Messenger of Allah ﷺ said: “Allah, Mighty and Majestic, said: ‘Your Ummah will continue saying: What about this? What about that? Until they say: Allah created creation, so who created Allah?’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7296)، ومسلم (136)."},{"num":15025,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأَشْعَرِيِّ، قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَشْيَاءَ كَرِهَهَا، فَلَمَّا أَكْثَرُوا عَلَيْهِ الْمَسْأَلَةَ غَضِبَ وَقَالَ: سَلُونِي. فَقَامَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، مَنْ أَبِي؟ قَالَ: أَبُوكَ حُذَافَةُ. ثُمَّ قَامَ آخَرُ فَقَالَ: يَا رَسُولَ اللَّهِ، مَنْ أَبِي؟ فَقَالَ: أَبُوكَ سَالِمٌ مَوْلَى شَيْبَةَ. فَلَمَّا رَأَى عُمَرُ مَا بِوَجْهِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْغَضَبِ قَالَ: إِنَّا نَتُوبُ إِلَى اللَّهِ عَزَّ وَجَلَّ."],"takhrij":"متفق عليه: رواه البخاري في الاعتصام (7291)، ومسلم في الفضائل (2360) كلاهما من طريق أبي أسامة، عن بريد بن أبي بردة، عن أبي بردة، عن أبي موسى الأشعري، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب التحذير من كثرة السؤال والتنطع والغلو في الدين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7291) and Muslim (2360).","chapter_en":"Warning against Excessive Questioning, Over-Scrupulousness, and Extremism in Religion","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":45,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated: The Messenger of Allah ﷺ was asked about matters that he disliked being asked about. When they persisted in questioning him, he became angry and said: “Ask me.” A man stood and said: “O Messenger of Allah, who is my father?” He replied: “Your father is Ḥudhāfah.” Another man stood and asked: “O Messenger of Allah, who is my father?” He replied: “Your father is Sālim, the freedman of Shaybah.” When ʿUmar saw the anger on the face of the Messenger of Allah ﷺ, he said: “We repent to Allah, Mighty and Majestic.”"]}},"tuhfa":{},"full":1,"rep":[1285],"tks":"متفق عليه: رواه البخاري (7291)، ومسلم (2360)."},{"num":15026,"demo":false,"sanad":"","matn":["عَنْ وَرَّادٍ، كَاتِبِ الْمُغِيرَةِ، قَالَ: كَتَبَ مُعَاوِيَةُ إِلَى الْمُغِيرَةِ: اكْتُبْ إِلَىَّ مَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَكَتَبَ إِلَيْهِ: إِنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي دُبُرِ كُلِّ صَلاَةٍ: لاَ إِلَهَ إِلاَّ اللَّهُ، وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهْوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ، اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ. وَكَتَبَ إِلَيْهِ إِنَّهُ كَانَ يَنْهَى عَنْ قِيلَ وَقَالَ، وَكَثْرَةِ السُّؤَالِ، وَإِضَاعَةِ الْمَالِ، وَكَانَ يَنْهَى عَنْ عُقُوقِ الأُمَّهَاتِ، وَوَأْدِ الْبَنَاتِ، وَمَنْعٍ وَهَاتِ."],"takhrij":"متفق عليه: رواه البخاري في الاعتصام (7292) عن موسى، حدثنا أبو عوانة، حدثنا عبد الملك، عن ورّاد، كاتب المغيرة، قال: فذكره. ورواه مسلم في المساجد (593) وفي الأقضية (593) عقب (1715) من طرق عن ورّاد مفرقا.","grade":"متفق عليه","chapter_ar":"باب التحذير من كثرة السؤال والتنطع والغلو في الدين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7292) and Muslim (593).","chapter_en":"Warning against Excessive Questioning, Over-Scrupulousness, and Extremism in Religion","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":45,"content":{"translation":{"en":["Warrād, the secretary of al-Mughīrah, narrated: Muʿāwiyah wrote to al-Mughīrah: “Write to me what you heard from the Messenger of Allah ﷺ.” Al-Mughīrah wrote back that the Prophet of Allah ﷺ used to say after every prayer: “There is no deity worthy of worship except Allah alone, without partner. To Him belongs the dominion and to Him belongs all praise, and He has power over all things. O Allah, none can withhold what You give, and none can give what You withhold, and the wealth or status of the fortunate cannot benefit him against You.” He also wrote that the Prophet ﷺ used to prohibit idle hearsay, excessive questioning, and wasting wealth, and that he prohibited disobedience to mothers, burying daughters alive, withholding what one owes, and constantly demanding from others."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7292)، ومسلم (593)."},{"num":15027,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: كُنَّا عِنْدَ عُمَرَ فَقَالَ: نُهِينَا عَنِ التَّكَلُّفِ."],"takhrij":"صحيح: رواه البخاري في الاعتصام (7293) عن سليمان بن حرب، حدثنا حماد بن زيد، عن ثابت، عن أنس، قال: فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من كثرة السؤال والتنطع والغلو في الدين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (7293).","chapter_en":"Warning against Excessive Questioning, Over-Scrupulousness, and Extremism in Religion","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":45,"content":{"translation":{"en":["Anas narrated: We were with ʿUmar when he said: “We were prohibited from affectation and unnecessary burdening of ourselves.”"]}},"tuhfa":{},"full":1,"rep":[1293,14453],"tks":"صحيح: رواه البخاري (7293)."},{"num":15028,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  هَلَكَ الْمُتَنَطِّعُونَ قَالَهَا ثَلَاثًا."],"takhrij":"صحيح: رواه مسلم في العلم (2670) من طريق ابن جريج، عن سليمان بن عتيق، عن طلق بن حبيب، عن الأحنف بن قيس، عن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من كثرة السؤال والتنطع والغلو في الدين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2670).","chapter_en":"Warning against Excessive Questioning, Over-Scrupulousness, and Extremism in Religion","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":45,"content":{"translation":{"en":["Ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “The extremists who go beyond proper bounds are ruined.” He said it three times."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2670)."},{"num":15029,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ السَّائِبِ بْنِ يَزِيدَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لاَ يَأْخُذَنَّ أَحَدُكُمْ مَتَاعَ أَخِيهِ لاَعِبًا وَلاَ جَادًّا، وَمَنْ أَخَذَ عَصَا أَخِيهِ فَلْيَرُدَّهَا."],"takhrij":"صحيح: رواه أبو داود (5003)، والترمذي (2160)، وأحمد (17940)، والحاكم (6686) كلهم من حديث ابن أبي ذئب، عن عبد الله بن السائب بن يزيد، عن أبيه، عن جده فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن أخذ متاع أخيه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (5003), al-Tirmidhī (2160), Aḥmad (17940), and al-Ḥākim (3/637).","chapter_en":"The Prohibition of Taking One’s Brother’s Property","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":46,"content":{"translation":{"en":["ʿAbdullāh ibn al-Sā’ib ibn Yazīd narrated from his father, from his grandfather, that he heard the Messenger of Allah ﷺ say: “Let none of you take his brother’s belongings, whether jokingly or seriously. Whoever takes his brother’s stick must return it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (5003)، والترمذي (2160)، وأحمد (17940)، والحاكم (6686)."},{"num":15030,"demo":false,"sanad":"","matn":["أَنَّ أَبَا سَعِيدٍ الْخُدْرِيَّ أَخْبَرَهُ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِيَّاكُمْ وَالْقُسَامَةَ. قَالَ: فَقُلْنَا: وَمَا الْقُسَامَةُ؟ قَالَ: الشَّىْءُ يَكُونُ بَيْنَ النَّاسِ فَيَجِيءُ فَيَنْتَقِصُ مِنْهُ."],"takhrij":"حسن: رواه أبو داود (2783) –ومن طريقه البيهقي (13024)- عن جعفر بن مسافر التنيسي، حدثنا ابن أبي فديك، حدثنا الزمعي، عن الزبير بن عثمان بن عبد الله بن سراقة، أن محمد بن عبد الرحمن بن ثوبان أخبره، أن أبا سعيد الخدري أخبره فذكره.","grade":"حسن","chapter_ar":"باب لا ينبغي أخذ الأجرة على قسمة الأشياء المشاعة بين الناس","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2783), and through him al-Bayhaqī (6/356).","chapter_en":"One Should Not Take a Share for Oneself When Dividing Common Property among People","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":47,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “Beware of al-qasāmah.” They asked: “What is al-qasāmah?” He replied: “It is something shared among people, and a person comes and takes a portion away from it.”"]},"buhuth":{"en":["Al-Khaṭṭābī said:","The word al-qasāmah, with a ḍammah on the qāf, refers to what the distributor takes for himself during division, similar to other Arabic nouns indicating what results from an action.","This does not prohibit the distributor from taking a legitimate wage when those whose property is being divided give permission.","Rather, it refers to a person appointed over a group as their representative or supervisor, who, when distributing their shares, withholds some of it for himself and gives himself preference over them.","He said that this meaning is clarified by another hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2783)، ومن طريقه البيهقي (13024)."},{"num":15031,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ سَعْدٍ قَالَ: لَوْ لاَ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الْمَكْرُ وَالْخَدِيعَةُ فِي النَّارِ، لَكُنْتُ مِنْ أَمْكَرَ النَّاسِ."],"takhrij":"حسن: رواه ابنُ عدي في الكامل (351) –ومن طريقه البيهقي في الشعب (10595)- عن أبي العلاء الكوفي، ثنا هشام بن عمار، ثنا جراح بن مليح، ثنا أبو رافع، عن قيس بن سعد قال: فذكره.","grade":"حسن","chapter_ar":"باب النهي عن المكر والخديعة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn ʿAdī in al-Kāmil (2/584), and through him by al-Bayhaqī in Shuʿab al-Īmān (10595).","chapter_en":"The Prohibition of Scheming and Deception","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":48,"content":{"translation":{"en":["Qays ibn Saʿd said: Were it not that I heard the Messenger of Allah ﷺ say: “Scheming and deception are in the Fire,” I would have been among the most cunning of people."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن عدي في الكامل (351)، ومن طريقه البيهقي في الشعب (10595)."},{"num":15032,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِمُخَنَّثٍ قَدْ خَضَبَ يَدَيْهِ، وَرِجْلَيْهِ بِالْحِنَّاءِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا بَالُ هَذَا. فَقِيلَ: يَا رَسُولَ اللَّهِ يَتَشَبَّهُ بِالنِّسَاءِ. فَأُمِرَ بِهِ فَنُفِيَ إِلَى النَّقِيعِ. فَقَالُوا يَا رَسُولَ اللَّهِ أَلاَ نَقْتُلُهُ. فَقَالَ إِنِّي نُهِيتُ عَنْ قَتْلِ الْمُصَلِّينَ."],"takhrij":"حسن: رواه أبو داود (4928) وأبو يعلى (6126) والبيهقي (16987) كلهم من حديث أبي أسامة أخبرهم، عن مفضل بن يونس، عن الأوزاعي، عن أبي يسار القرشي، عن أبي هاشم، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في المخنثين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4928), Abū Yaʿlā (6126), and al-Bayhaqī (8/222).","chapter_en":"What Has Been Narrated Concerning Effeminate Men","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":49,"content":{"translation":{"en":["Abū Hurayrah narrated: An effeminate man was brought to the Prophet ﷺ who had dyed his hands and feet with henna. The Messenger of Allah ﷺ asked: “What is the matter with this man?” They said: “O Messenger of Allah, he imitates women.” So the Prophet ﷺ ordered that he be exiled to al-Naqīʿ. They asked: “O Messenger of Allah, should we not kill him?” He replied: “I have been prohibited from killing those who pray.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[6786],"tks":"حسن: رواه أبو داود (4928)، وأبو يعلى (6126)، والبيهقي (16987)."},{"num":15033,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ:  أَنَّ مُخَنَّثًا كَانَ عِنْدَهَا، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْبَيْتِ، فَقَالَ لِأَخِي أُمِّ سَلَمَةَ: يَا عَبْدَ اللَّهِ بْنَ أَبِي أُمَيَّةَ، إِنْ فَتَحَ اللَّهُ عَلَيْكُمُ الطَّائِفَ غَدًا، فَإِنِّي أَدُلُّكَ عَلَى بِنْتِ غَيْلَانَ، فَإِنَّهَا تُقْبِلُ بِأَرْبَعٍ وَتُدْبِرُ بِثَمَانٍ. قَالَ: فَسَمِعَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: لَا يَدْخُلْ هَؤُلَاءِ عَلَيْكُمْ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4324)، ومسلم في السلام (2180) كلاهما من طريق هشام بن عروة، عن أبيه، عن زينب بنت أم سلمة، عن أم سلمة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في المخنثين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4324) and Muslim (2180).","chapter_en":"What Has Been Narrated Concerning Effeminate Men","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":49,"content":{"translation":{"en":["Umm Salamah narrated: An effeminate man was in her home while the Messenger of Allah ﷺ was also in the house. The man said to Umm Salamah’s brother: “O ʿAbdullāh ibn Abī Umayyah, if Allah grants you victory over al-Ṭā’if tomorrow, I will direct you to the daughter of Ghaylān. She approaches with four and turns away with eight.” The Messenger of Allah ﷺ heard him and said: “Do not allow such people to enter upon you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12874],"tks":"متفق عليه: رواه البخاري (4324)، ومسلم (2180)."},{"num":15034,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: لَعَنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُخَنَّثِينَ مِنَ الرِّجَالِ، وَالْمُتَرَجِّلاَتِ مِنَ النِّسَاءِ. وَقَالَ: أَخْرِجُوهُمْ مِنْ بُيُوتِكُمْ. قَالَ: فَأَخْرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فُلاَنًا، وَأَخْرَجَ عُمَرُ فُلاَنًا."],"takhrij":"صحيح: رواه البخاري في اللباس (5886) عن معاذ بن فضالة، حدثنا هشام، عن يحيى، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في المخنثين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5886).","chapter_en":"What Has Been Narrated Concerning Effeminate Men","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في مساوئ الأخلاق","group_en":"Collection of What Has Been Narrated Concerning Evil Character Traits","part_no":61,"group_no":19,"chapter_no":49,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ cursed effeminate men and women who adopted the mannerisms of men, and said: “Expel them from your homes.” Ibn ʿAbbās said: The Prophet ﷺ expelled one such person, and ʿUmar expelled another."]},"buhuth":{"en":["In another narration in al-Bukhārī (5885):","“Men who imitate women, and women who imitate men.”","Jurisprudential Discussion of the Hadith","An intersex person (al-khunthā) is one who is born with both male and female sexual characteristics.","The author divides such a person into four possible situations:","If the person is capable of sexual relations with a woman and does not menstruate, then the rulings applicable to a man apply regarding purification, acts of worship, inheritance, and other matters.","If the person menstruates and is not capable of sexual relations with a woman, then the rulings applicable to a woman apply regarding purification, worship, inheritance, and similar matters.","If the person menstruates and is also capable of sexual relations with a woman, then the author states that the rulings of a woman should apply in purification, worship, and inheritance, as this is the more cautious approach.","If the person neither menstruates nor is capable of sexual relations with a woman, then consideration is given to the manner in which the person urinates. If urination occurs in the manner of a male, the rulings of a male apply; if in the manner of a female, the rulings of a female apply.","If urine exits through both organs, this is what the jurists call al-khunthā al-mushkil, an indeterminate intersex case.","Its ruling is left to the judgment of the jurist, who examines the predominant indicators and applies what is most cautious and appropriate. Each individual condition has its own specific ruling and should not automatically be analogized to another.","The author states that in all such cases it is permissible to undergo surgery to correct the physical abnormality, while remaining content with Allah’s decree and predestination, being patient through hardship, and seeking one’s reward from Allah, the Exalted.","An effeminate man (al-mukhannath) is a man who displays feminine traits.","If a person was naturally created in this manner and does not deliberately imitate women, then there is no sin, blame, guilt, or punishment upon him.","The author states that such a person may enter upon women.","Some scholars cited the statement of Allah, the Exalted:","“Or male attendants who have no sexual desire.”","[Sūrat al-Nūr 24:31]","Ibn ʿAbbās said that “those who have no sexual desire” refers to the effeminate man.","Mujāhid and Qatādah said it means the man who has no sexual interest in women—that is, no desire for them.","The testimony of such a person is accepted, and it is permissible to pray behind him.","However, al-Zuhrī said:","“We do not consider it appropriate to pray behind an effeminate man except in a case of unavoidable necessity.”","Al-Bukhārī mentioned this (695).","The author explains this as referring to a situation in which such a person possesses authority and power.","As for a man who deliberately imitates women in speech, behavior, dress, and other matters, or a woman who deliberately imitates men in speech, behavior, dress, and other matters, this is blameworthy.","This deliberate imitation is what the authentic hadiths address with condemnation, cursing, expulsion from homes, and banishment."]}},"tuhfa":{},"full":1,"dr":1,"rep":[6437],"tks":"صحيح: رواه البخاري (5886)."},{"num":15035,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: آيَةُ الْمُنَافِقِ ثَلاَثٌ، إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا اؤْتُمِنَ خَانَ."],"takhrij":"متفق عليه: رواه البخاريّ في الإيمان (33)، ومسلم في الإيمان (59) كلاهما من حديث إسماعيل بن جعفر، قال: حدثنا نافع بن مالك بن أبي عامر أبو سُهيل، عن أبيه، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في علامات النفاق","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (33) and Muslim (59).","chapter_en":"What Has Been Narrated Concerning the Signs of Hypocrisy","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The signs of a hypocrite are three: when he speaks, he lies; when he promises, he breaks his promise; and when he is entrusted, he betrays the trust.”"]},"buhuth":{"en":["Muslim narrated it through another route with the addition:","“Even if he fasts, prays, and claims that he is a Muslim.”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللّٰهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلَاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلَا يَذْكُرُونَ اللّٰهَ إِلَّا قَلِيلًا﴾ [سورة النساء: ١٤٢].","وقال تعالى:","﴿مُذَبْذَبِينَ بَيْنَ ذَٰلِكَ لَا إِلَى هَٰؤُلَاءِ وَلَا إِلَى هَٰؤُلَاءِ وَمَنْ يُضْلِلِ اللّٰهُ فَلَنْ تَجِدَ لَهُ سَبِيلًا﴾ [سورة النساء: ١٤٣].","أي مترددين، لا إلى المسلمين، ولا إلى الكافرين."],"en":["Allah, the Exalted, says:","“Indeed, the hypocrites seek to deceive Allah, but He is the One who deceives them. When they stand for prayer, they stand lazily, showing off before people, and they remember Allah only a little.”","[Sūrat al-Nisāʾ 4:142]","And He, the Exalted, says:","“Wavering between the two, belonging neither to these nor to those. Whoever Allah leaves astray, you will never find for him a way.”","[Sūrat al-Nisāʾ 4:143]","Meaning: wavering, belonging neither to the Muslims nor to the disbelievers."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12629],"tks":"متفق عليه: رواه البخاري (33)، ومسلم (59)."},{"num":15036,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عمرو، أنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَرْبَعٌ مَنْ كنَّ فِيهِ كَانَ مُنَافِقًا خَالِصًا، وَمَنْ كَانَتْ فِيهِ خَصْلة مِنْهُنَّ كَانَتْ فِيهِ خَصْلَةٌ مِنَ النِّفَاقِ حَتَّى يَدَعَهَا: إِذَا اؤْتُمِنَ خَانَ، وَإِذَا حدّث كَذَبَ، وَإِذَا عَاهَدَ غَدَرَ، وَإِذَا خَاصَمَ فَجَرَ."],"takhrij":"متفق عليه: رواه البخاريّ في الإيمان (34)، ومسلم في الإيمان (58) كلاهما من حديث سفيان، عن الأعمش، عن عبدالله بن مُرّة، عن مسروق، عن عبدالله ابن عمرو، فذكره. وفي رواية عند مسلم من غير سفيان، بلفظ: ومن كانت فيه خلّة منهن كانت فيه خلّة من نفاق.","grade":"متفق عليه","chapter_ar":"باب ما جاء في علامات النفاق","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (34) and Muslim (58).","chapter_en":"What Has Been Narrated Concerning the Signs of Hypocrisy","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Prophet ﷺ said: “There are four traits which, if all are found in a person, make him a pure hypocrite. Whoever has one of them has a trait of hypocrisy until he abandons it: when entrusted, he betrays; when he speaks, he lies; when he makes a covenant, he acts treacherously; and when he disputes, he behaves wickedly.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13545],"tks":"متفق عليه: رواه البخاري (34)، ومسلم (58)."},{"num":15037,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ثَلاثٌ مَنْ كُنَّ فِيهِ فَهُوَ مُنَافِقٌ، وَإِنْ كَانَ فِيهِ خَصْلَةٌ فَفِيهِ خَصْلَةٌ مِنَ النِّفَاقِ، إِذَا حَدَّثَ كَذَبَ، وَإِذَا اؤْتُمِنَ خَانَ، وَإِذَا وَعَدَ أَخْلَفَ."],"takhrij":"صحيح: رواه البزار (1662) عن عمرو بن علي، قال: نا أبو داود، قال: نا شعبة، عن منصور، عن أبي وائل، عن عبد الله فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في علامات النفاق","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzār (1662).","chapter_en":"What Has Been Narrated Concerning the Signs of Hypocrisy","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Prophet ﷺ said: “Whoever possesses three traits is a hypocrite, and whoever possesses one of them has a trait of hypocrisy: when he speaks, he lies; when entrusted, he betrays; and when he promises, he breaks his promise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار (1662)."},{"num":15038,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: مَا خَطَبَنَا نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَّا قَالَ: لَا إِيمَانَ لِمَنْ لَا أَمَانَةَ لَهُ، وَلَا دِينَ لِمَنْ لَا عَهْدَ لَهُ."],"takhrij":"حسن: رواه أحمد (12383)، وأبو يعلى (12863)، والبزار - كشف الأستار (100) -، والبغويّ في شرح السنة (38) كلّهم من طريق أبي هلال، عن قتادة، عن أنس، فذكره. قال البغويّ: هذا حديث حسن.","grade":"حسن","chapter_ar":"باب ما جاء في علامات النفاق","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (12383), Abū Yaʿlā (2863), al-Bazzār as cited in Kashf al-Astār (100), and al-Ṭabarānī in al-Muʿjam al-Awsaṭ (2627).","chapter_en":"What Has Been Narrated Concerning the Signs of Hypocrisy","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["Anas narrated: Rarely would the Messenger of Allah ﷺ deliver a sermon to us without saying: “There is no complete faith for the one who is not trustworthy, and there is no true religion for the one who does not honor his covenant.”"]},"buhuth":{"en":["The chain is good despite the discussion concerning Abū Hilāl, Muḥammad ibn Sulaym al-Rāsibī; his hadith is acceptable, and al-Baghawī graded it good in Sharḥ al-Sunnah (38).","He was not alone in narrating it. Abū Yaʿlā also narrated it (3445), and through him Ibn Ḥibbān included it in his Ṣaḥīḥ (194), through Muʾammal ibn Ismāʿīl, from Ḥammād ibn Salamah, from Thābit, from Anas, with similar wording.","Muʾammal ibn Ismāʿīl was criticized concerning his memory, but there is no harm in using his narration for corroboration.","There are also reports on this subject from Ibn ʿUmar, Ibn ʿAbbās, Abū Umāmah, and Ibn Masʿūd. None of them is independently authentic, though some may be used as supporting evidence."]}},"tuhfa":{},"full":1,"dr":1,"rep":[43],"tks":"حسن: رواه أحمد (12383)، وأبو يعلى (12863)، والبزار في كشف الأستار (100)، والطبراني في الأوسط (2627)."},{"num":15039,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ هُدَيَّةَ، عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَكْثَرُ مُنَافِقِي أُمَّتِي قُرَّاؤُهَا."],"takhrij":"حسن: رواه أحمد (6637)، والبخاريّ في التاريخ الكبير (1/257)، والبغويّ في شرح السنة (39) كلهم من طريق عبدالله بن المبارك، عن عبدالرحمن ابن شريح المعافريّ، قال: حدثني شراحيل بن يزيد، عن محمد بن هديّة، عن عبدالله بن عمرو بن العاص، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في علامات النفاق","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (6637), al-Bukhārī in al-Tārīkh al-Kabīr (1/257), and al-Baghawī in Sharḥ al-Sunnah (39).","chapter_en":"What Has Been Narrated Concerning the Signs of Hypocrisy","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that the Messenger of Allah ﷺ said: “Most of the hypocrites of my Ummah will be among its reciters.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6637)، والبخاري في التاريخ الكبير (1/257)، والبغوي في شرح السنة (39)."},{"num":15040,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَكْثَرَ مُنَافِقِي هَذِهِ الْأُمَّةِ قرّاؤها."],"takhrij":"حسن: رواه الإمام أحمد (17410) عن أبي عبدالرحمن، حدثنا ابن لهيعة، حدثني أبو المصعب، قال: سمعت عقبة، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في علامات النفاق","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (17410).","chapter_en":"What Has Been Narrated Concerning the Signs of Hypocrisy","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":1,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir narrated that the Prophet ﷺ said: “Most of the hypocrites of this Ummah will be among its reciters.”"]},"buhuth":{"en":["Al-Baghawī explained in Sharḥ al-Sunnah (1/77) that the meaning of:","“Most of the hypocrites of this Ummah will be among its reciters”","is that they may habitually lack sincerity in their deeds.","He compared this to the statement:","“The merchant is a sinner,”","meaning a merchant who habitually lies in buying and selling, not that trade itself is sinful. Trade itself is permitted and lawful in Islamic law.","Al-Baghawī’s words “the merchant is a sinner” may refer to the hadith of ʿAbd al-Raḥmān ibn Shibl, who narrated that the Messenger of Allah ﷺ said:","“Indeed, merchants are the sinners.”","It was asked:","“O Messenger of Allah, has Allah not made trade lawful?”","He replied:","“Yes, but they speak and lie, and they swear oaths and fall into sin.”","Narrated by Aḥmad (15530), and its chain is authentic."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11856],"tks":"حسن: رواه الإمام أحمد (17410)."},{"num":15041,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مِنْ شَرِّ النَّاسِ ذُو الْوَجْهَيْنِ الَّذِي يَأْتِي هَؤُلاَءِ بِوَجْهٍ، وَهَؤُلاَءِ بِوَجْهٍ.","وفي لفظ: تَجِدُ مِنْ شَرِّ النَّاسِ يَوْمَ الْقِيَامَةِ عِنْدَ اللَّهِ ذَا الْوَجْهَيْنِ، الَّذِي يَأْتِي هَؤُلاَءِ بِوَجْهٍ، وَهَؤُلاَءِ بِوَجْهٍ."],"takhrij":"متفق عليه: رواه مالك في الكلام (21) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه مسلم في البر والصلة (2526: 98) عقب(2604) من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب ذم ذي الوجهين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Kalām (21), Muslim (2526:98), following Hadith 2604, and al-Bukhārī (7179).","chapter_en":"Condemnation of the Two-Faced Person","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Among the worst of people is the two-faced person, who comes to these people with one face and to those people with another face.” In another wording: “You will find among the worst people before Allah on the Day of Resurrection the two-faced person, who comes to these people with one face and to those people with another.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (21)، ومسلم (2526: 98) عقب الحديث (2604)، والبخاري (7179)."},{"num":15042,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا يَنْبَغِي لِذِي الْوَجْهَيْنِ أَنْ يَكُونَ أَمِينًا."],"takhrij":"حسن: رواه أحمد (8781)، والخرائطي في مساوئ الأخلاق (291)، والبيهقي في السنن (154) كلهم من طريق أبي سلمة الخزاعي، قال: أخبرنا سليمان بن بلال، عن محمد بن عجلان، عن عبيد الله بن سلمان الأغر، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ذم ذي الوجهين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8781), al-Kharāʾiṭī in Masāwiʾ al-Akhlāq (291), and al-Bayhaqī in al-Sunan (10/246).","chapter_en":"Condemnation of the Two-Faced Person","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “It is not fitting for a two-faced person to be trustworthy.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8781)، والخرائطي في مساوئ الأخلاق (291)، والبيهقي في السنن (154)."},{"num":15043,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ تَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ يَنْبَغِي لِذِي الْوَجْهَيْنِ أَنْ يَكُونَ وَجِيهًا يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه الخرائطي في مساوئ الأخلاق (294) عن أبي يوسف القلوسي، ثنا محمد بن عباد المكي، ثنا محمد بن سليمان، ثنا عبد الجبار بن الورد، عن ابن أبي ملكية قال: سمعت عائشة تقول: فذكرتْه.","grade":"حسن","chapter_ar":"باب ذم ذي الوجهين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Kharāʾiṭī in Masāwiʾ al-Akhlāq (294).","chapter_en":"Condemnation of the Two-Faced Person","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":2,"content":{"translation":{"en":["The Mother of the Believers, ʿĀ’ishah, narrated that the Messenger of Allah ﷺ said: “It is not fitting for a two-faced person to be honored or distinguished on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الخرائطي في مساوئ الأخلاق (294)."},{"num":15044,"demo":false,"sanad":"","matn":["عَنْ عَمَّارٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ كَانَ لَهُ وَجْهَانِ فِي الدُّنْيَا، كَانَ لَهُ يَوْمَ الْقِيَامَةِ لِسَانَانِ مِنْ نَارٍ."],"takhrij":"حسن: رواه أبو داود (4873)، والبخاري في الأدب المفرد (1310)، وأبو يعلى (1620)، وصحّحه ابن حبان (5756) كلهم من طريق شريك، عن الركين بن الربيع، عن نعيم بن حنظلة، عن عمار فذكره.","grade":"حسن","chapter_ar":"باب ذم ذي الوجهين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4873), al-Bukhārī in al-Adab al-Mufrad (1310), and Abū Yaʿlā (1620).","chapter_en":"Condemnation of the Two-Faced Person","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":2,"content":{"translation":{"en":["ʿAmmār narrated that the Messenger of Allah ﷺ said: “Whoever has two faces in this world will have two tongues of fire on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4873)، والبخاري في الأدب المفرد (1310)، وأبو يعلى (1620)."},{"num":15045,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: لَمَّا تُوُفِّيَ عَبْدُ اللَّهِ، جَاءَ ابْنُهُ عَبْدُ اللَّهِ بْنُ عبدالله إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ أَنْ يُعْطِيَهُ قَمِيصَهُ يُكَفِّنُ فِيهِ أَبَاهُ، فَأَعْطَاهُ، ثُمَّ سَأَلَهُ أَنْ يُصَلِّيَ عَلَيْهِ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُصَلِّيَ، فَقَامَ عُمَرُ، فَأَخَذَ بِثَوْبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَ: يَا رَسُولَ اللَّهِ! تُصَلِّي عَلَيْهِ وَقَدْ نَهَاكَ رَبُّكَ أَنْ تُصَلِّيَ عَلَيْهِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا خَيَّرَنِي اللَّهُ، فَقَالَ: ﴿اسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِنْ تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَنْ يَغْفِرَ اللَّهُ لَهُمْ ذَلِكَ بِأَنَّهُمْ كَفَرُوا بِاللَّهِ وَرَسُولِهِ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ﴾ [سورة التوبة: 80] وَسَأَزِيدُهُ عَلَى السَّبْعِينَ. قَالَ: إِنَّهُ مُنَافِقٌ. قَالَ: فَصَلَّى عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَنْزَلَ اللَّهُ ﴿وَلَا تُصَلِّ عَلَى أَحَدٍ مِنْهُمْ مَاتَ أَبَدًا وَلَا تَقُمْ عَلَى قَبْرِهِ﴾ [سورة التَّوْبَةِ: ٨٤]."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4670)، ومسلم في فضائل الصحابة (2400) كلاهما من طريق أبي أسامة، حدثنا عبيد الله، عن نافع، عن ابن عمر، قال: فذكره. واللفظ للبخاري ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب في أخبار رأس المنافقين عبد اللّٰه بن أبي ابن سلول","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4670) and Muslim (2400).","chapter_en":"Reports Concerning the Leader of the Hypocrites, ʿAbdullāh ibn Ubayy ibn Salūl","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿUmar narrated: When ʿAbdullāh ibn Ubayy died, his son ʿAbdullāh ibn ʿAbdullāh came to the Messenger of Allah ﷺ and asked him to give him his shirt so that his father could be shrouded in it. The Prophet ﷺ gave it to him. Then he asked the Prophet ﷺ to perform the funeral prayer over his father. The Messenger of Allah ﷺ stood up to pray over him. ʿUmar stood and took hold of the garment of the Messenger of Allah ﷺ and said: “O Messenger of Allah, will you pray over him when your Lord has forbidden you from doing so?” The Messenger of Allah ﷺ replied: “Allah has only given me a choice. He said: ‘Ask forgiveness for them or do not ask forgiveness for them. Even if you ask forgiveness for them seventy times, Allah will never forgive them. That is because they disbelieved in Allah and His Messenger, and Allah does not guide the defiantly disobedient people.’ I will ask more than seventy times.” ʿUmar said: “But he is a hypocrite.” Nevertheless, the Messenger of Allah ﷺ prayed over him. Then Allah revealed: “And never pray over any of them who dies, nor stand at his grave.” [Sūrat al-Tawbah 9:84]"]}},"tuhfa":{},"full":1,"rep":[12501],"tks":"متفق عليه: رواه البخاري (4670)، ومسلم (2400)."},{"num":15046,"demo":false,"sanad":"","matn":["عَنْ جابر قَالَ: أَتَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبْرَ عَبْدِ اللَّهِ بْنِ أُبَيٍّ، فَأَخْرَجَهُ مِنْ قَبْرِهِ فَوَضَعَهُ عَلَى رُكْبَتَيْهِ، وَنَفَثَ عَلَيْهِ مِنْ رِيقِهِ، وَأَلْبَسَهُ قَمِيصَهُ، فَاللهُ أَعْلَمُ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1270)، ومسلم في صفات المنافقين (2773) كلاهما من طريق سفيان بن عيينة، عن عمرو أنه سمع جابرا قال: فذكره. واللفظ لمسلم، ولفظ البخاري نحوه.","grade":"متفق عليه","chapter_ar":"باب في أخبار رأس المنافقين عبد اللّٰه بن أبي ابن سلول","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1270) and Muslim (2773).","chapter_en":"Reports Concerning the Leader of the Hypocrites, ʿAbdullāh ibn Ubayy ibn Salūl","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":3,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The Prophet ﷺ came to the grave of ʿAbdullāh ibn Ubayy. He had him taken out of his grave, placed him upon his knees, blew some of his saliva upon him, and clothed him in his shirt. And Allah knows best."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1270)، ومسلم (2773)."},{"num":15047,"demo":false,"sanad":"","matn":["عَنْ قَيْسٍ قَالَ:  قُلْتُ لِعَمَّارٍ: أَرَأَيْتُمْ صَنِيعَكُمْ هَذَا الَّذِي صَنَعْتُمْ فِي أَمْرِ عَلِيٍّ، أَرَأْيًا رَأَيْتُمُوهُ، أَوْ شَيْئًا عَهِدَهُ إِلَيْكُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: مَا عَهِدَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا لَمْ يَعْهَدْهُ إِلَى النَّاسِ كَافَّةً، وَلَكِنْ حُذَيْفَةُ أَخْبَرَنِي عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فِي أَصْحَابِي اثْنَا عَشَرَ مُنَافِقًا، فِيهِمْ ثَمَانِيَةٌ لَا يَدْخُلُونَ الْجَنَّةَ حَتَّى يَلِجَ الْجَمَلُ فِي سَمِّ الْخِيَاطِ، ثَمَانِيَةٌ مِنْهُمْ تَكْفِيكَهُمُ الدُّبَيْلَةُ، وَأَرْبَعَةٌ لَمْ أَحْفَظْ مَا قَالَ شُعْبَةُ فِيهِمْ.","وفي رواية عنه: قَالَ: قُلْنَا لِعَمَّارٍ: أَرَأَيْتَ قِتَالَكُمْ، أَرَأْيًا رَأَيْتُمُوهُ؟ فَإِنَّ الرَّأْيَ يُخْطِئُ وَيُصِيبُ، أَوْ عَهْدًا عَهِدَهُ إِلَيْكُمْ رَسُولُ اللهِ صلى الله عليه وسلم ؟ فَقَالَ: مَا عَهِدَ إِلَيْنَا رَسُولُ اللهِ صلى الله عليه وسلم شَيْئًا لَمْ يَعْهَدْهُ إِلَى النَّاسِ كَافَّةً، وَقَالَ: إِنَّ رَسُولَ اللهِ صلى الله عليه وسلم قَالَ: إِنَّ فِي أُمَّتِي.","قال شعبة: وأحسبه قال: حدثني حذيفة.","وقال غندر: أُراه قال: في أمتي اثنا عشر منافقا لا يدخلون الجنة، ولا يجدون ريحها، حتى يلج الجمل في سم الخياط ثمانية منهم تكفيكهم الدبيلة، سراج من النار يظهر في أكتافهم، حتى ينجم من صدورهم."],"takhrij":"صحيح: رواه مسلم في صفات المنافقين (2779: 9) عن أبي بكر بن أبي شيبة، حدثنا أسود بن عامر، حدثنا شعبة بن الحجاج، عن قتادة، عن أبي نضرة، عن قيس بن عباد فذكره باللفظ الأول.","grade":"صحيح","chapter_ar":"باب حديث حذيفة في ذكر المنافقين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2779:9).","chapter_en":"The Hadith of Ḥudhayfah Concerning the Hypocrites","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":4,"content":{"translation":{"en":["Qays ibn ʿUbād narrated: I said to ʿAmmār: “Regarding what you have done in the matter of ʿAlī, was it an opinion you formed yourselves, or was it something the Messenger of Allah ﷺ specifically entrusted to you?” He replied: “The Messenger of Allah ﷺ did not entrust us with anything that he did not also convey to the people generally. However, Ḥudhayfah informed me from the Prophet ﷺ that the Prophet ﷺ said: ‘Among my companions are twelve hypocrites. Eight of them will not enter Paradise until a camel passes through the eye of a needle. As for eight of them, al-dubaylah will suffice against them.’” Regarding the remaining four, Aswad ibn ʿĀmir said: “I did not retain what Shuʿbah said concerning them.” In another narration, they said to ʿAmmār: “Regarding your fighting, was it merely an opinion you formed? Opinions can be right or wrong. Or was it something the Messenger of Allah ﷺ specifically entrusted to you?” He replied: “The Messenger of Allah ﷺ did not entrust us with anything that he did not also entrust to all the people.” Then he said that the Messenger of Allah ﷺ said: “Indeed, among my Ummah…” Shuʿbah said: “I think he said: ‘Ḥudhayfah narrated to me.’”","Ghundar said: “I think he said: ‘Among my Ummah are twelve hypocrites who will neither enter Paradise nor smell its fragrance until a camel enters through the eye of a needle. Eight of them will be dealt with by al-dubaylah: a lamp of fire that will appear in their shoulders until it emerges from their chests.’”"]},"buhuth":{"en":["The second mention of the eight is an explanatory substitute for the first eight, as clarified by the second narration in Muslim.","If these are indeed the individuals intended, Ibn Abī Ḥātim listed their names in his Tafsīr (6/1880) as:","Wadīʿah ibn Thābit, Judhām ibn Khālid, Thaʿlabah ibn Ḥāṭib, Jāriyah ibn ʿĀmir and his two sons Mujammaʿ and Zayd, Muʿattib ibn Qushayr, ʿAbbād ibn Ḥunayf—the brother of Sahl ibn Ḥunayf—Abū Ḥabībah ibn al-Azʿar, Nabtal ibn al-Ḥārith, Bijād ibn ʿUthmān, and a man called Baḥzaj."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2779: 9)."},{"num":15048,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ يَصْعَدُ الثَّنِيَّةَ، ثَنِيَّةَ الْمُرَارِ، فَإِنَّهُ يُحَطُّ عَنْهُ مَا حُطَّ عَنْ بَنِي إِسْرَائِيلَ. قَالَ: فَكَانَ أَوَّلَ مَنْ صَعِدَهَا خَيْلُنَا، خَيْلُ بَنِي الْخَزْرَجِ، ثُمَّ تَتَامَّ النَّاسُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَكُلُّكُمْ مَغْفُورٌ لَهُ، إِلَّا صَاحِبَ الْجَمَلِ الْأَحْمَرِ. فَأَتَيْنَاهُ فَقُلْنَا لَهُ: تَعَالَ، يَسْتَغْفِرْ لَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ: وَاللهِ لَأَنْ أَجِدَ ضَالَّتِي أَحَبُّ إِلَيَّ مِنْ أَنْ يَسْتَغْفِرَ لِي صَاحِبُكُمْ. قَالَ: وَكَانَ رَجُلٌ يَنْشُدُ ضَالَّةً لَهُ."],"takhrij":"صحيح: رواه مسلم في صفات المنافقين (2780) عن عبيد الله بن معاذ العنبري، حدثنا أبي، حدثنا قرة بن خالد، عن أبي الزبير، عن جابر بن عبد الله، قال: فذكره.","grade":"صحيح","chapter_ar":"باب صاحب الجمل الأحمر كان من المنافقين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2780).","chapter_en":"The Owner of the Red Camel Was among the Hypocrites","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":5,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The Messenger of Allah ﷺ said: “Whoever ascends this mountain pass—the pass of al-Murār—will have his sins removed just as they were removed from the Children of Israel.” Jābir said: The first to ascend it were our horses, the horses of Banū al-Khazraj, and then the rest of the people followed one after another. The Messenger of Allah ﷺ then said: “All of you have been forgiven except the owner of the red camel.” We went to him and said: “Come, so that the Messenger of Allah ﷺ may seek forgiveness for you.” He replied: “By Allah, finding my lost property is more beloved to me than having your companion seek forgiveness for me.” Jābir said: The man was searching for something he had lost."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2780)."},{"num":15049,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ:  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدِمَ مِنْ سَفَرٍ، فَلَمَّا كَانَ قُرْبَ الْمَدِينَةِ هَاجَتْ رِيحٌ شَدِيدَةٌ تَكَادُ أَنْ تَدْفِنَ الرَّاكِبَ، فَزَعَمَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بُعِثَتْ هَذِهِ الرِّيحُ لِمَوْتِ مُنَافِقٍ. فَلَمَّا قَدِمَ الْمَدِينَةَ، فَإِذَا مُنَافِقٌ عَظِيمٌ مِنَ الْمُنَافِقِينَ قَدْ مَاتَ."],"takhrij":"صحيح: رواه مسلم في صفات المنافقين (2782) عن أبي كريب محمد بن العلاء، حدثنا حفص يعني ابن غياث، عن الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب بعث اللّٰه الريح لموت منافق في عهد النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2782).","chapter_en":"Allah Sending a Wind upon the Death of a Hypocrite during the Prophet’s ﷺ Lifetime","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":6,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The Messenger of Allah ﷺ returned from a journey. When he came near Madinah, a fierce wind began to blow, so strong that it nearly overturned a rider. It was narrated that the Messenger of Allah ﷺ said: “This wind has been sent because of the death of a hypocrite.” When he arrived in Madinah, it was found that one of the prominent hypocrites had died."]}},"tuhfa":{},"full":1,"rep":[9740],"tks":"صحيح: رواه مسلم (2782)."},{"num":15050,"demo":false,"sanad":"","matn":["عن سَلَمَةَ بن الأكوع قَالَ: عُدْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا مَوْعُوكًا، قَالَ: فَوَضَعْتُ يَدِي عَلَيْهِ، فَقُلْتُ: وَاللهِ مَا رَأَيْتُ كَالْيَوْمِ رَجُلًا أَشَدَّ حَرًّا. فَقَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَا أُخْبِرُكُمْ بِأَشَدَّ حَرًّا مِنْهُ يَوْمَ الْقِيَامَةِ، هَذَيْنِكَ الرَّجُلَيْنِ الرَّاكِبَيْنِ الْمُقَفِّيَيْنِ."],"takhrij":"صحيح: رواه مسلم في صفات المنافقين (2783) عن عباس بن عبد العظيم العنبري، حدثنا أبو محمد النضر بن محمد بن موسى اليمامي، حدثنا عكرمة، حدثنا إياس، حدثني أبي، قال: فذكره.","grade":"صحيح","chapter_ar":"باب تسمية النبي ﷺ بعض المنافقين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2783).","chapter_en":"The Prophet ﷺ Identifying Some of the Hypocrites","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":7,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ narrated: We visited a man suffering from fever together with the Messenger of Allah ﷺ. I placed my hand upon him and said: “By Allah, I have never seen a man as intensely hot with fever as this man today.” The Prophet of Allah ﷺ said: “Shall I tell you of two men who will be even hotter than him on the Day of Resurrection? Those two riders who are turning away.” He was referring to two men who were then among his companions."]},"buhuth":{"en":["The word “al-muqaffiyayn” means the two men who were departing, with the backs of their heads turned away.","The narrator’s description of them as “two of his companions” means that outwardly they displayed Islam, while inwardly they concealed hypocrisy."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2783)."},{"num":15051,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَجُلٌ نَصْرَانِيًّا فَأَسْلَمَ، وَقَرَأَ الْبَقَرَةَ وَآلَ عِمْرَانَ، فَكَانَ يَكْتُبُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَعَادَ نَصْرَانِيًّا، فَكَانَ يَقُولُ: مَا يَدْرِي مُحَمَّدٌ إِلاَّ مَا كَتَبْتُ لَهُ، فَأَمَاتَهُ اللَّهُ فَدَفَنُوهُ، فَأَصْبَحَ وَقَدْ لَفَظَتْهُ الأَرْضُ فَقَالُوا: هَذَا فِعْلُ مُحَمَّدٍ وَأَصْحَابِهِ، لَمَّا هَرَبَ مِنْهُمْ نَبَشُوا عَنْ صَاحِبِنَا. فَأَلْقُوهُ، فَحَفَرُوا لَهُ فَأَعْمَقُوا، فَأَصْبَحَ وَقَدْ لَفَظَتْهُ الأَرْضُ، فَقَالُوا: هَذَا فِعْلُ مُحَمَّدٍ وَأَصْحَابِهِ نَبَشُوا عَنْ صَاحِبِنَا لَمَّا هَرَبَ مِنْهُمْ. فَأَلْقَوْهُ، فَحَفَرُوا لَهُ، وَأَعْمَقُوا لَهُ فِي الأَرْضِ مَا اسْتَطَاعُوا، فَأَصْبَحَ قَدْ لَفَظَتْهُ الأَرْضُ، فَعَلِمُوا أَنَّهُ لَيْسَ مِنَ النَّاسِ فَأَلْقَوْهُ."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3617) -واللفظ له- عن أبي معمر، حدثنا عبد الوارث، حدثنا عبد العزيز، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب المنافق الذي لفظته الأرض","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3617), and this is his wording, and Muslim (2781).","chapter_en":"The Hypocrite Whom the Earth Cast Out","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":8,"content":{"translation":{"en":["Anas narrated: There was a Christian man who accepted Islam and learned Sūrat al-Baqarah and Āl ʿImrān. He used to write for the Prophet ﷺ. Then he returned to Christianity and began saying: “Muḥammad knows nothing except what I wrote for him.” Allah caused him to die, and they buried him. By morning, the earth had cast his body out. They said: “This is the doing of Muḥammad and his companions. Because our companion fled from them, they dug him up and threw him out.” So they dug another grave for him and made it deeper. By morning, the earth had again cast him out. They said: “This is the doing of Muḥammad and his companions. They dug our companion up because he fled from them and threw him out.” So they dug as deeply into the earth as they possibly could and buried him again. By morning, the earth had cast him out once more. Then they realized that this was not the work of people, so they left him exposed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3617) - واللفظ له -، ومسلم (2781)."},{"num":15052,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ:  أَنَّ رِجَالًا مِنَ الْمُنَافِقِينَ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كَانُوا إِذَا خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْغَزْوِ تَخَلَّفُوا عَنْهُ، وَفَرِحُوا بِمَقْعَدِهِمْ خِلَافَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَإِذَا قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اعْتَذَرُوا إِلَيْهِ، وَحَلَفُوا، وَأَحَبُّوا أَنْ يُحْمَدُوا بِمَا لَمْ يَفْعَلُوا، فَنَزَلَتْ: ﴿لَا تَحْسَبَنَّ الَّذِينَ يَفْرَحُونَ بِمَا أَتَوْا وَيُحِبُّونَ أَنْ يُحْمَدُوا بِمَا لَمْ يَفْعَلُوا فَلا تَحْسَبَنَّهُمْ بِمَفَازَةٍ مِنَ الْعَذَابِ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4567) ومسلم في صفات المنافقين (2777) كلاهما من طريق سعيد بن أبي مريم، أخبرنا محمد بن جعفر، قال: حدثني زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد الخدري، فذكره.","grade":"متفق عليه","chapter_ar":"باب من صفات المنافقين أنهم يحبون أن يحمدوا بما لم يفعلوا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4567) and Muslim (2777).","chapter_en":"Among the Traits of the Hypocrites Is That They Love to Be Praised for What They Did Not Do","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":9,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: During the time of the Messenger of Allah ﷺ, some men from among the hypocrites would remain behind whenever the Prophet ﷺ went out on a military expedition. They rejoiced in remaining behind in opposition to the Messenger of Allah ﷺ. When the Prophet ﷺ returned, they would make excuses to him, swear oaths, and love to be praised for things they had not done. Then the following verse was revealed: “Do not think that those who rejoice in what they have done and love to be praised for what they have not done—do not think that they are safe from the punishment.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4567)، ومسلم (2777)."},{"num":15053,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا قالَ الرَّجُلُ لِلْمُنَافِقِ: يَا سيدي، فَقَدْ أَغْضَبَ ربَّه تَعَالَى."],"takhrij":"حسن: رواه الحاكم (7865) –وعنه البيهقي في الشعب (4854)- عن محمد بن عبد الله بن عمرويه البزّاز، حدثنا محمد بن إسحاق الصغاني، حدثنا الحسن بن موسى الأشيب، حدثنا عقبة بن عبد الله الأصم، حدثنا عبدالله بن بريدة، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب لا يجوز أن يقال للمنافق: يا سيدي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ḥākim (7865), and through him by al-Bayhaqī in Shuʿab al-Īmān (4854).","chapter_en":"It Is Not Permissible to Say to a Hypocrite: “My Master”","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":10,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb narrated that the Messenger of Allah ﷺ said: “If a man says to a hypocrite, ‘My master,’ he has angered his Lord, the Exalted.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (7865)، وعنه البيهقي في الشعب (4854)."},{"num":15054,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مَثَلُ الْمُنَافِقِ كَمَثَلِ الشَّاةِ الْعَائِرَةِ بَيْنَ الْغَنَمَيْنِ، تَعِيرُ إِلَى هَذِهِ مَرَّةً وَإِلَى هَذِهِ مَرَّةً.","وفي لفظ: تكر في هذه مرة وفي هذه مرة."],"takhrij":"صحيح: رواه مسلم في صفات المنافقين (2784) من طرق عن عبيد الله، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في مثل المنافق","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2784).","chapter_en":"What Has Been Narrated Concerning the Parable of the Hypocrite","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Prophet ﷺ said: “The example of the hypocrite is like a wandering sheep between two flocks, going to this one at one time and to that one at another.” In another wording: “It turns toward this flock once and toward that flock once.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2784)."},{"num":15055,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَثَلُ الْمُؤْمِنِ كَمَثَلِ الزَّرْعِ، لَا تَزَالُ الرِّيحُ تُمِيلُهُ، وَلَا يَزَالُ الْمُؤْمِنُ يُصِيبُهُ الْبَلَاءُ، وَمَثَلُ الْمُنَافِقِ كَمَثَلِ شَجَرَةِ الْأَرْزِ، لَا تَهْتَزُّ حَتَّى تَسْتَحْصِدَ."],"takhrij":"متفق عليه: رواه مسلم في صفة القيامة (2809) عن أبي بكر بن أبي شيبة، حدثنا عبد الأعلى، عن معمر، عن الزهري، عن سعيد، عن أبي هريرة، قال: فذكره. ورواه البخاري في المرضى (5644) من وجه آخر عن أبي هريرة نحوه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مثل المنافق","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2809) and al-Bukhārī (5644).","chapter_en":"What Has Been Narrated Concerning the Parable of the Hypocrite","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The example of the believer is like a crop that the wind continually bends, and the believer continually experiences trials. The example of the hypocrite is like the cedar tree: it does not move until it is finally cut down all at once.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مسلم (2809)، والبخاري (5644)."},{"num":15056,"demo":false,"sanad":"","matn":["عَنْ كَعْبِ بن مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَثَلُ الْمُؤْمِنِ كَالْخَامَةِ مِنَ الزَّرْعِ، تُفَيِّئُهَا الرِّيحُ مَرَّةً، وَتَعْدِلُهَا مَرَّةً، وَمَثَلُ الْمُنَافِقِ كَالأَرْزَةِ، لاَ تَزَالُ حَتَّى يَكُونَ انْجِعَافُهَا مَرَّةً وَاحِدَةً."],"takhrij":"متفق عليه: رواه البخاري في المرضى (5643)، من طريق يحيى (هو القطان)، عن سفيان، عن سعد بن إبراهيم، عن عبد الله بن كعب، عن أبيه فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مثل المنافق","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5643) and Muslim (2810:62). The wording is that of al-Bukhārī.","chapter_en":"What Has Been Narrated Concerning the Parable of the Hypocrite","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":11,"content":{"translation":{"en":["Kaʿb ibn Mālik narrated that the Prophet ﷺ said: “The example of the believer is like a tender stalk of crop: the wind bends it at one time and straightens it at another. The example of the hypocrite is like the cedar tree, which remains rigid until it is uprooted all at once.”"]},"buhuth":{"en":["In Muslim, one wording says:","“The example of the disbeliever is like the cedar tree.”","In another narration through a different route, it says:","“The example of the hypocrite is like the cedar tree.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5643)، ومسلم (2810: 62)، واللفظ للبخاري."},{"num":15057,"demo":false,"sanad":"","matn":["عن أَبِي الطُّفَيْلِ قَالَ: كَانَ بَيْنَ رَجُلٍ مِنْ أَهْلِ الْعَقَبَةِ وَبَيْنَ حُذَيْفَةَ بَعْضُ مَا يَكُونُ بَيْنَ النَّاسِ، فَقَالَ: أَنْشُدُكَ بِاللهِ، كَمْ كَانَ أَصْحَابُ الْعَقَبَةِ؟ قَالَ: فَقَالَ لَهُ الْقَوْمُ: أَخْبِرْهُ إِذْ سَأَلَكَ. قَالَ: كُنَّا نُخْبَرُ أَنَّهُمْ أَرْبَعَةَ عَشَرَ، فَإِنْ كُنْتَ مِنْهُمْ فَقَدْ كَانَ الْقَوْمُ خَمْسَةَ عَشَرَ، وَأَشْهَدُ بِاللهِ أَنَّ اثْنَيْ عَشَرَ مِنْهُمْ حَرْبٌ لِلهِ وَلِرَسُولِهِ فِي الْحَيَاةِ الدُّنْيَا وَيَوْمَ يَقُومُ الْأَشْهَادُ، وَعَذَرَ ثَلَاثَةً. قَالُوا: مَا سَمِعْنَا مُنَادِيَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَا عَلِمْنَا بِمَا أَرَادَ الْقَوْمُ، وَقَدْ كَانَ فِي حَرَّةٍ فَمَشَى فَقَالَ: إِنَّ الْمَاءَ قَلِيلٌ، فَلَا يَسْبِقُْنِي إِلَيْهِ أَحَدٌ. فَوَجَدَ قَوْمًا قَدْ سَبَقُوهُ، فَلَعَنَهُمْ يَوْمَئِذٍ."],"takhrij":"صحيح: رواه مسلم في صفات المنافقين (11:2997) عن زهير بن حرب حدثنا أبو أحمد الكوفي حدثنا الوليد بن جميع، حدثنا أبو الطفيل فذكره.","grade":"صحيح","chapter_ar":"باب اجتماع المنافقين في عقبة للغدر برسول اللّٰه ﷺ","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2997:11).","chapter_en":"The Hypocrites Gathering at the Mountain Pass to Betray the Messenger of Allah ﷺ","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":12,"content":{"translation":{"en":["Abū al-Ṭufayl narrated: There was some disagreement of the kind that occurs between people between a man from among the people of the mountain pass and Ḥudhayfah. The man said: “I adjure you by Allah, how many were the men of the mountain pass?” The people said to Ḥudhayfah: “Tell him, since he has asked you.” Ḥudhayfah said: “We were informed that they were fourteen. If you were one of them, then they were fifteen. I testify by Allah that twelve of them were at war with Allah and His Messenger in the life of this world and on the Day when the witnesses will stand.” Three were excused because they said: “We did not hear the caller of the Messenger of Allah ﷺ, nor did we know what the people intended.” The Prophet ﷺ had been traveling through a stony plain and said: “The water is scarce, so let no one reach it before me.” But he found that some people had already reached it before him, so he cursed them that day."]},"buhuth":{"en":["Al-Nawawī said:","This ʿAqabah is not the famous mountain pass at which the Anṣār, may Allah be pleased with them, gave their pledge of allegiance.","Rather, this was a mountain pass on the road to Tabūk, where the hypocrites gathered during the expedition of Tabūk in order to betray the Messenger of Allah ﷺ, but Allah protected him from them.","The author says:","The following narration makes this even clearer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9265,15762],"tks":"صحيح: رواه مسلم (11:2997)."},{"num":15058,"demo":false,"sanad":"","matn":["عَنْ أَبِي الطُّفَيْلِ، قَالَ: لَمَّا أَقْبَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ غَزْوَةِ تَبُوكَ أَمَرَ مُنَادِيًا فَنَادَى: إِنَّ رَسُولَ اللَّهِ أَخَذَ الْعَقَبَةَ، فَلَا يَأْخُذْهَا أَحَدٌ، فَبَيْنَمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُودُهُ حُذَيْفَةُ، وَيَسُوقُ بِهِ عَمَّارٌ إِذْ أَقْبَلَ رَهْطٌ مُتَلَثِّمُونَ عَلَى الرَّوَاحِلِ، غَشَوْا عَمَّارًا وَهُوَ يَسُوقُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَقْبَلَ عَمَّارٌ يَضْرِبُ وُجُوهَ الرَّوَاحِلِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِحُذَيْفَةَ: قَدْ، قَدْ حَتَّى هَبَطَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا هَبَطَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَزَلَ وَرَجَعَ عَمَّارٌ، فَقَالَ: يَا عَمَّارُ، هَلْ عَرَفْتَ الْقَوْمَ؟ فَقَالَ: قَدْ عَرَفْتُ عَامَّةَ الرَّوَاحِلِ وَالْقَوْمُ مُتَلَثِّمُونَ، قَالَ: هَلْ تَدْرِي مَا أَرَادُوا؟ قَالَ: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: أَرَادُوا أَنْ يَنْفِرُوا بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيَطْرَحُوهُ قَالَ: فَسَأَلَ عَمَّارٌ رَجُلًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: نَشَدْتُكَ بِاللهِ، كَمْ تَعْلَمُ كَانَ أَصْحَابُ الْعَقَبَةِ؟ فَقَالَ: أَرْبَعَةَ عَشَرَ، فَقَالَ: إِنْ كُنْتَ فِيهِمْ فَقَدْ كَانُوا خَمْسَةَ عَشَرَ، فَعَذَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهُمْ ثَلَاثَةً، قَالُوا: وَاللهِ مَا سَمِعْنَا مُنَادِيَ رَسُولِ اللَّهِ، وَمَا عَلِمْنَا مَا أَرَادَ الْقَوْمُ، فَقَالَ عَمَّارٌ: أَشْهَدُ أَنَّ الِاثْنَيْ عَشَرَ الْبَاقِينَ حَرْبٌ لِلَّهِ وَلِرَسُولِهِ فِي الْحَيَاةِ الدُّنْيَا، وَيَوْمَ يَقُومُ الْأَشْهَادُ.","قَالَ أَبُو الْوَلِيدِ: وَذَكَرَ أَبُو الطُّفَيْلِ فِي تِلْكَ الْغَزْوَةِ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ لِلنَّاسِ وَذُكِرَ لَهُ أَنَّ فِي الْمَاءِ قِلَّةً، فَأَمَرَ رَسُولُ اللَّهِ صلى الله عليه وسلم مُنَادِيًا فَنَادَى: أن لَا يَرِدُ الْمَاءَ أَحَدٌ قَبْلَ رَسُولِ اللَّهِ صلى الله عليه وسلم، فَوَرَدَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم فَوَجَدَ رَهْطًا وَرَدُوهُ قَبْلَهُ، فَلَعَنَهُمْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَوْمَئِذٍ."],"takhrij":"حسن: رواه أحمد (23792) عن يزيد، أخبرنا الوليد –يعني ابن عبد الله بن جميع، عن أبي الطفيل، قال: فذكره.","grade":"حسن","chapter_ar":"باب اجتماع المنافقين في عقبة للغدر برسول اللّٰه ﷺ","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (23792).","chapter_en":"The Hypocrites Gathering at the Mountain Pass to Betray the Messenger of Allah ﷺ","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":12,"content":{"translation":{"en":["Abū al-Ṭufayl narrated: When the Messenger of Allah ﷺ was returning from the expedition of Tabūk, he ordered a caller to announce: “The Messenger of Allah ﷺ will take the mountain pass, so no one else is to take it.” Ḥudhayfah was leading the mount of the Messenger of Allah ﷺ, while ʿAmmār was driving it from behind. A group of masked men then approached on their mounts and crowded around ʿAmmār while he was driving the mount of the Prophet ﷺ. ʿAmmār began striking the faces of their mounts to drive them away. The Messenger of Allah ﷺ said to Ḥudhayfah: “Enough, enough.” They continued until the Messenger of Allah ﷺ descended from the pass. When he had descended, he dismounted, and ʿAmmār returned. The Prophet ﷺ asked: “O ʿAmmār, did you recognize the people?” He replied: “I recognized most of the mounts, but the men had covered their faces.” The Prophet ﷺ asked: “Do you know what they intended?” ʿAmmār replied: “Allah and His Messenger know best.” He said: “They intended to startle the mount of the Messenger of Allah ﷺ so that they could throw him down.” ʿAmmār, may Allah be pleased with him, then asked one of the Companions of the Messenger of Allah ﷺ: “I adjure you by Allah, how many do you know the people of the mountain pass to have been?” He replied: “Fourteen.” ʿAmmār said: “If you were among them, then they were fifteen.” The Messenger of Allah ﷺ excused three of them, because they said: “By Allah, we did not hear the caller of the Messenger of Allah ﷺ, nor did we know what the people intended.” ʿAmmār then said: “I testify that the remaining twelve are at war with Allah and His Messenger in the life of this world and on the Day when the witnesses will stand.” Abū al-Walīd said: Abū al-Ṭufayl also mentioned concerning that expedition that the Messenger of Allah ﷺ was told that the water was scarce. So the Messenger of Allah ﷺ ordered a caller to announce: “No one is to reach the water before the Messenger of Allah ﷺ.” When the Messenger of Allah ﷺ reached it, he found that a group had arrived there before him, so the Messenger of Allah ﷺ cursed them that day."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9266],"tks":"حسن: رواه أحمد (23792)."},{"num":15059,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ غَزْوَةِ تَبُوكَ، قَالَ: فَبَلَغَهُ أَنَّ فِي الْمَاءِ قِلَّةً. الَّذِي يَرِدُهُ، فَأَمَرَ مُنَادِيًا فَنَادَى فِي النَّاسِ: أَنْ لَا يَسْبِقَنِي إِلَى الْمَاءِ أَحَدٌ، فَأَتَى الْمَاءَ، وَقَدْ سَبَقَهُ قَوْمٌ فَلَعَنَهُمْ."],"takhrij":"حسن: رواه أحمد (23395) عن أبي نعيم، حدثنا الوليد –يعني ابن جميع، حدثنا أبو الطفيل، عن حذيفة، فذكره.","grade":"حسن","chapter_ar":"باب اجتماع المنافقين في عقبة للغدر برسول اللّٰه ﷺ","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (23395).","chapter_en":"The Hypocrites Gathering at the Mountain Pass to Betray the Messenger of Allah ﷺ","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":12,"content":{"translation":{"en":["Ḥudhayfah narrated: The Messenger of Allah ﷺ set out during the expedition of Tabūk. He was informed that the water was scarce, so he ordered a caller to announce among the people: “Let no one reach the water before me.” When he reached the water, he found that some people had preceded him to it, so he cursed them."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9267],"tks":"حسن: رواه أحمد (23395)."},{"num":15060,"demo":false,"sanad":"","matn":["عَنْ مَحْمُودِ بْنِ لَبِيَدٍ، عَنْ رِجَالٍ مِنْ بَنِي عَبْدِ الْأَشْهَلِ، قَالَ: قُلْتُ لِمَحْمُودِ: هَلْ كَانَ النَّاسُ يَعْرِفُونَ النِّفَاقَ فِيهِمْ؟ قَالَ: نعم وللَّه، إنْ كَانَ الرَّجُلُ لَيَعْرِفُهُ مِنْ أَخِيهِ وَمِنْ أَبِيهِ وَمِنْ عَمِّهِ وَفِي عَشِيرَتِهِ، ثُمَّ يَلْبَسُ بَعْضُهُمْ بَعْضًا عَلَى ذَلِكَ. ثُمَّ قَالَ مَحْمُودٌ: لَقَدْ أَخْبَرَنِي رِجَالٌ مِنْ قَوْمِي عَنْ رَجُلٍ مِنْ الْمُنَافِقِينَ مَعْرُوفٌ نِفَاقُهُ، كَانَ يَسِيرُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  حَيْثُ سَارَ، فَلَمَّا كَانَ مِنْ أَمْرِ النَّاسِ [٣] بِالْحِجْرِ مَا كَانَ، وَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  حِينَ دَعَا، فَأَرْسَلَ اللَّهُ السَّحَابَةَ، فَأَمْطَرَتْ حَتَّى ارْتَوَى النَّاسُ، قَالُوا: أَقْبَلْنَا عَلَيْهِ نَقُولُ: وَيْحَكَ، هَلْ بَعْدَ هَذَا شَيْءٌ! قَالَ: سَحَابَةٌ مَارَّةٌ.","قَالَ ابْنُ إسْحَاقَ: ثُمَّ إنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَارَ حَتَّى إذَا كَانَ بِبَعْضِ الطَّرِيقِ ضَلَّتْ نَاقَتُهُ، فَخَرَجَ أَصْحَابُهُ فِي طَلَبِهَا، وَعِنْدَ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ مِنْ أَصْحَابِهِ يُقَالُ لَهُ عُمَارَةُ بْنُ حَزْمٍ، وَكَانَ عَقَبِيًّا بدريّا، وَهُوَ عم بَنِي عَمْرِو بْنِ حَزْمٍ، وَكَانَ فِي رَحْلِهِ زَيْدُ بْنُ اللُّصَيْتِ الْقَيْنُقَاعِيُّ وَكَانَ مُنَافِقًا.","قَالَ ابْنُ إسْحَاقَ: فَحَدَّثَنِي عَاصِمُ بْنُ عُمَرَ بْنِ قَتَادَةَ، عَنْ مَحْمُودِ بْنِ لَبِيَدٍ، عَنْ رِجَالٍ مِنْ بَنِي عَبْدِ الْأَشْهَلِ قَالُوا: فَقَالَ زَيْدُ بْنُ اللُّصَيْتِ وَهُوَ فِي رَحْلِ عُمَارَةَ وَعُمَارَةُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَلَيْسَ مُحَمَّدٌ يَزْعُمُ أَنَّهُ نَبِيٌّ، وَيُخْبِرُكُمْ عَنْ خَبَرِ السَّمَاءِ وَهُوَ لَا يَدْرِي أَيْنَ نَاقَتُهُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ -وَعُمَارَةُ عِنْدَهُ-: إنَّ رَجُلًا قَالَ: هَذَا مُحَمَّدٌ يُخْبِرُكُمْ أَنَّهُ نَبِيٌّ، وَيَزْعُمُ أَنَّهُ يُخْبِرُكُمْ بِأَمْرِ السَّمَاءِ وَهُوَ لَا يَدْرِي أَيْنَ نَاقَتُهُ، وَإِنِّي وَاَللَّهِ مَا أَعْلَمُ إلَّا مَا عَلَّمَنِي اللَّهُ وَقَدْ دَلَّنِي اللَّهُ عَلَيْهَا، وَهِيَ فِي هَذَا الْوَادِي، فِي شِعْبِ كَذَا وَكَذَا، قَدْ حَبَسَتْهَا شَجَرَةٌ بِزِمَامِهَا، فَانْطَلِقُوا حَتَّى تَأْتُونِي بِهَا، فَذَهَبُوا، فَجَاءُوا بِهَا. فَرَجَعَ عُمَارَةُ بْنُ حَزْمٍ إلَى رَحْلِهِ، فَقَالَ: وَاَللَّهِ لَعَجَبٌ مِنْ شَيْءٍ حَدَّثَنَاهُ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ آنِفًا عَنْ مَقَالَةِ قَائِلٍ أَخْبَرَهُ اللَّهُ عَنْهُ بِكَذَا وَكَذَا لِلَّذِي قَالَ زَيْدُ بْنُ لُصَيْتٍ، فَقَالَ رَجُلٌ مِمَّنْ كَانَ فِي رَحْلِ عُمَارَةَ وَلَمْ يَحْضُرْ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: زَيْدٌ وَاَللَّهِ قَالَ هَذِهِ الْمَقَالَةَ قَبْلَ أَنْ تَأْتِيَ. فَأَقْبَلَ عُمَارَةُ عَلَى زَيْدٍ يَجَأُ فِي عُنُقِهِ، وَيَقُولُ: إلَيَّ عِبَادَ اللَّهِ، إنَّ فِي رَحْلِي لَدَاهِيَةً وَمَا أَشْعُرُ، اُخْرُجْ أَيْ عَدُوَّ اللَّهِ مِنْ رَحْلِي، فَلَا تَصْحَبْنِي."],"takhrij":"حسن: رواه محمد بن إسحاق فقال: حدثني عاصم بن عمر بن قتادة، عن محمود بن لبيد، بإسناده، فذكره. سيرة ابن هشام (2125).","grade":"حسن","chapter_ar":"باب مقال المنافقين لإيذاء النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Muḥammad ibn Isḥāq and al-Bayhaqī in Dalā’il al-Nubuwwah (5/231–232).","chapter_en":"Statements of the Hypocrites Intended to Harm the Prophet ﷺ","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":13,"content":{"translation":{"en":["Maḥmūd ibn Labīd narrated from some men of Banū ʿAbd al-Ashhal. He was asked: “Did the people know who the hypocrites among them were?” He replied: “Yes, by Allah. A man might know hypocrisy in his own brother, father, paternal uncle, or within his own clan, yet they continued interacting with one another despite that.” Maḥmūd then said: Some men from my people informed me about a man whose hypocrisy was well known. He would travel with the Messenger of Allah ﷺ wherever he went. When the incident at al-Ḥijr occurred and the Messenger of Allah ﷺ supplicated, Allah sent a cloud which rained until the people had enough water. They went to the hypocrite and said: “Woe to you! Is there anything left to say after this?” He replied: “It was merely a passing cloud.” Ibn Isḥāq said: The Messenger of Allah ﷺ then continued traveling until, at one point on the road, his she-camel became lost. His Companions went out searching for it.","With the Messenger of Allah ﷺ at that time was a Companion named ʿUmārah ibn Ḥazm, who had attended the pledge at al-ʿAqabah and the Battle of Badr and was the paternal uncle of Banū ʿAmr ibn Ḥazm. Staying in ʿUmārah’s camp was Zayd ibn al-Luṣayt al-Qaynuqāʿī, who was a hypocrite. Ibn Isḥāq said: ʿĀṣim ibn ʿUmar ibn Qatādah narrated to me from Maḥmūd ibn Labīd, from some men of Banū ʿAbd al-Ashhal, that Zayd ibn al-Luṣayt said while he was in ʿUmārah’s camp and ʿUmārah was with the Messenger of Allah ﷺ: “Does Muḥammad not claim that he is a Prophet and that he informs you of news from heaven, yet he does not even know where his camel is?”","The Messenger of Allah ﷺ, while ʿUmārah was with him, then said: “A man has said: ‘This Muḥammad tells you that he is a Prophet and claims that he informs you about matters of heaven, yet he does not know where his camel is.’ By Allah, I know nothing except what Allah teaches me. Allah has now shown me where it is. It is in this valley, in such-and-such a ravine, where a tree has caught its reins. Go and bring it to me.” They went and brought the she-camel back. ʿUmārah ibn Ḥazm returned to his camp and said: “By Allah, how astonishing is something the Messenger of Allah ﷺ just told us! He told us that Allah had informed him of a statement made by someone, namely such-and-such.” It was exactly what Zayd ibn al-Luṣayt had said. A man who had been in ʿUmārah’s camp but had not been present with the Messenger of Allah ﷺ said: “By Allah, Zayd said those very words before you came.” ʿUmārah turned upon Zayd and began striking him in the neck, saying: “Come here, servants of Allah! There was a calamity in my own camp and I did not even realize it. Get out, O enemy of Allah, from my camp. Do not accompany me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه محمد بن إسحاق، والبيهقي في الدلائل (1722)."},{"num":15061,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ، قَالَ: إِنَّ الْمُنَافِقِينَ الْيَوْمَ شَرٌّ مِنْهُمْ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانُوا يَوْمَئِذٍ يُسِرُّونَ وَالْيَوْمَ يَجْهَرُونَ."],"takhrij":"صحيح: رواه البخاري في الفتن (7113) عن آدم بن أبي إياس، حدثنا شعبة، عن واصل الأحدب، عن أبي وائل، عن حذيفة بن اليمان، قال: فذكره.","grade":"صحيح","chapter_ar":"باب النفاق بعد عهد النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (7113).","chapter_en":"Hypocrisy after the Time of the Prophet ﷺ","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":14,"content":{"translation":{"en":["Ḥudhayfah ibn al-Yamān said: “The hypocrites today are worse than they were during the time of the Prophet ﷺ. At that time they concealed their hypocrisy, whereas today they openly display it.”"]}},"tuhfa":{},"full":1,"rep":[15764],"tks":"صحيح: رواه البخاري (7113)."},{"num":15062,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ، قَالَ: إِنَّمَا كَانَ النِّفَاقُ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَّا الْيَوْمَ فَإِنَّمَا هُوَ الْكُفْرُ بَعْدَ الإِيمَانِ."],"takhrij":"صحيح: رواه البخاري في الفتن (7114) عن خلاد، حدثنا مسعر، عن حبيب بن أبي ثابت، عن أبي الشعثاء، عن حذيفة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب النفاق بعد عهد النبي ﷺ","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (7114).","chapter_en":"Hypocrisy after the Time of the Prophet ﷺ","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في النفاق والمنافقين","group_en":"Collection of What Has Been Narrated Concerning Hypocrisy and the Hypocrites","part_no":61,"group_no":20,"chapter_no":14,"content":{"translation":{"en":["Ḥudhayfah said: “Hypocrisy was during the time of the Prophet ﷺ. As for today, it is disbelief after faith.”"]}},"tuhfa":{},"full":1,"rep":[15763],"tks":"صحيح: رواه البخاري (7114)."},{"num":15063,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ يَا رَسُولَ اللَّهِ أَىُّ النَّاسِ خَيْرٌ قَالَ رَجُلٌ جَاهَدَ بِنَفْسِهِ وَمَالِهِ، وَرَجُلٌ فِي شِعْبٍ مِنَ الشِّعَابِ يَعْبُدُ رَبَّهُ، وَيَدَعُ النَّاسَ مِنْ شَرِّهِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6494)، ومسلم في الإمارة (1888) كلاهما من حديث الأوزاعي، عن الزهري، عن عطاء بن يزيد الليثي، عن أبي سعيد الخدري فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل العزلة","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6494) and Muslim (1888).","chapter_en":"The Virtue of Seclusion","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: A Bedouin came to the Prophet ﷺ and asked: “O Messenger of Allah, which people are best?” He replied: “A man who strives with his life and his wealth, and a man who remains secluded, worshiping his Lord and keeping people safe from his harm.”"]},"buhuth":{"en":["The expression “in one of the mountain passes” is not intended literally as a valley between two mountains. Rather, what is intended is solitude and withdrawal from people."]},"intro_majmu":{"ar":["الزهد هو: الكسب الحلال الذي يكفي له ولأولاده ولمن يعوله، ثم صرف القلب عن الدنيا ومتاعها إلى اللّٰه تعالى، لأن الدنيا مليئة بالشهوات والرغبات، قال اللّٰه تعالى:","﴿زُيِّنَ لِلنَّاسِ حُبُّ الشَّهَوَاتِ مِنَ النِّسَاءِ وَالْبَنِينَ وَالْقَنَاطِيرِ الْمُقَنْطَرَةِ مِنَ الذَّهَبِ وَالْفِضَّةِ وَالْخَيْلِ الْمُسَوَّمَةِ وَالْأَنْعَامِ وَالْحَرْثِ ذَٰلِكَ مَتَاعُ الْحَيَاةِ الدُّنْيَا وَاللّٰهُ عِنْدَهُ حُسْنُ الْمَآبِ﴾ [سورة آل عمران: ١٤].","وأما ترك السعي للحصول على الرزق، والجلوس في البيت، وانتظار الصدقات والخيرات بحجة التوكل على اللّٰه فهو ليس بزهد، وإنما هو أكل أموال الناس بالباطل باسم الزهد، وكذلك ترك الدنيا وزينتها ليس بزهد، وإنما هو الرهبانية التي أحدثها أهل الكتاب، قال تعالى:","﴿وَرَهْبَانِيَّةً ابْتَدَعُوهَا﴾ [الحديد: ٢٧].","فالفرق بين الزهد المشروع والرهبانية الممنوعة واضح، ولكن لا يدركها إلا أهل العلم والمعرفة، فالزهد بمعنى تزكية النفس عن حب الدنيا وجاهها مطلوب دائمًا وأبدًا لقوله تعالى:","﴿قَدْ أَفْلَحَ مَنْ زَكَّاهَا﴾ [الشمس: ٩].","وقد تكون كثرة المال تفيد الأمة في رقيها، وتنمية اقتصادها بما يناسب في عصرها لمقابلة الكفار، فإذا كان المسلم يؤدي حقوقه الواجبة تجاه أمته ودينه، ونفسه لا تغتر بمتاع الدنيا وزخرفها، فالإكثار من المال ليس بمكروه، والأمة الإسلامية منذ عهد النبي ﷺ إلى يومنا هذا قائمة على هذا الأساس.","فإن اللّٰه عز وجل وسع على المسلمين بعد غزو خيبر، فكان النبي ﷺ يدخر لأزواجه قوت سنة كاملة."],"en":["Asceticism means earning lawful provision sufficient for oneself, one’s children, and those one supports, while turning the heart away from this world and its enjoyments toward Allah, the Exalted. This is because the world is filled with desires and attractions.","Allah, the Exalted, says:","“Beautified for people is the love of desires: women, children, heaped-up treasures of gold and silver, fine horses, livestock, and cultivated land. These are the enjoyments of the worldly life, but with Allah is the best return.”","[Sūrat Āl ʿImrān 3:14]","As for abandoning the effort to earn one’s livelihood, sitting at home, and waiting for charity and donations under the claim of relying upon Allah, this is not asceticism. Rather, it is consuming people’s wealth wrongfully in the name of asceticism.","Likewise, completely abandoning the world and its adornments is not asceticism. Rather, that is the monasticism innovated by the People of the Book.","Allah, the Exalted, says:","“And monasticism which they innovated…”","[Sūrat al-Ḥadīd 57:27]","The distinction between legislated asceticism and prohibited monasticism is clear, although it is properly understood only by people of knowledge and understanding.","Asceticism, in the sense of purifying the soul from attachment to the world and its status, is always sought, as Allah, the Exalted, says:","“Successful indeed is the one who purifies it.”","[Sūrat al-Shams 91:9]","Possessing abundant wealth may benefit the Ummah by advancing it and strengthening its economy in ways suitable to its time so that it may stand against its enemies.","If a Muslim fulfills the obligatory rights he owes toward his religion and Ummah, while his soul is not deceived by the pleasures and adornments of this world, then possessing much wealth is not disliked.","The Muslim Ummah, from the time of the Prophet ﷺ until today, has operated on this principle.","Indeed, Allah, Mighty and Majestic, expanded provision for the Muslims after the conquest of Khaybar, and the Prophet ﷺ would store a full year’s provision for his wives."]}},"tuhfa":{},"full":1,"dr":1,"rep":[15712],"tks":"متفق عليه: رواه البخاري (6494)، ومسلم (1888)."},{"num":15064,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ قَالَ: أَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَنْكِبِي، فَقَالَ: كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ. وَكَانَ ابْنُ عُمَرَ يَقُولُ: \"إِذَا أَمْسَيْتَ فَلاَ تَنْتَظِرِ الصَّبَاحَ، وَإِذَا أَصْبَحْتَ فَلاَ تَنْتَظِرِ الْمَسَاءَ، وَخُذْ مِنْ صِحَّتِكَ لسقمك وَمِنْ حَيَاتِكَ لِمَوْتِكَ\"."],"takhrij":"صحيح: رواه البخاري في الرقاق (6416) عن علي بن عبد الله، حدثنا محمد بن عبد الرحمن أبو المنذر الطفاوي، عن سليمان الأعمش قال: حدثني مجاهد، عن عبدالله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب كن في الدنيا كأنك غريب أو عابر سبيل","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6416).","chapter_en":"Be in This World as Though You Were a Stranger or a Traveler Passing Through","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿUmar narrated: The Messenger of Allah ﷺ took hold of my shoulder and said: “Be in this world as though you were a stranger or a traveler passing through.” Ibn ʿUmar used to say: “When evening comes, do not expect to reach the morning; and when morning comes, do not expect to reach the evening. Take advantage of your health before your sickness, and your life before your death.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6416)."},{"num":15065,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن مَسْعُودٍ قَالَ: نَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى حَصِيرٍ فَقَامَ وَقَدْ أثَّر فِي جَنْبِهِ، فَقُلْنَا: يَا رَسُولَ اللَّهِ لَوِ اتَّخَذْنَا لَكَ وِطَاءً، فَقَالَ: مَالِي وللدنيا، مَا أَنَا فِي الدُّنْيَا إِلاَّ كَرَاكِبٍ اسْتَظَلَّ تَحْتَ شَجَرَةٍ ثُمَّ رَاحَ وَتَرَكَهَا."],"takhrij":"حسن: رواه الترمذي (2377)، وابن ماجه (4109)، وأحمد (4208)، وصحّحه الحاكم (4/310) كلهم من طرق عن المسعودي (هو عبد الرحمن بن عبد الله بن عتبة)، عن عمرو بن مرة، عن إبراهيم النخعي، عن علقمة، عن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب كن في الدنيا كأنك غريب أو عابر سبيل","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2377), Ibn Mājah (4109), and Aḥmad (4208), and authenticated by al-Ḥākim (4/310).","chapter_en":"Be in This World as Though You Were a Stranger or a Traveler Passing Through","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: The Messenger of Allah ﷺ slept upon a woven mat. When he stood up, the mat had left marks on his side. We said: “O Messenger of Allah, if only we could prepare some bedding for you.” He replied: “What do I have to do with this world? I am in this world only like a rider who seeks shade beneath a tree for a while, then continues on his journey and leaves it behind.”"]},"buhuth":{"en":["The word “wiṭāʾ” means bedding or a mattress."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13710],"tks":"حسن: رواه الترمذي (2377)، وابن ماجه (4109)، وأحمد (4208)، وصححه الحاكم (4/310)."},{"num":15066,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهِ عُمَرُ، وَهُوَ عَلَى حَصِيرٍ قَدْ أَثَّرَ فِي جَنْبِهِ، فَقَالَ: يَا نَبِيَّ اللَّهِ، لَوِ اتَّخَذْتَ فِرَاشًا أَوْثَرَ مِنْ هَذَا؟ فَقَالَ: مَا لِي وَلِلدُّنْيَا؟ مَا مَثَلِي وَمَثَلُ الدُّنْيَا، إِلا كَرَاكِبٍ سَارَ فِي يَوْمٍ صَائِفٍ، فَاسْتَظَلَّ تَحْتَ شَجَرَةٍ سَاعَةً مِنْ نَهَارٍ، ثُمَّ رَاحَ وَتَرَكَهَا."],"takhrij":"حسن: رواه أحمد (2744)، وصحّحه ابن حبان (6352)، والحاكم (7858) كلهم من طريق ثابت بن يزيد، عن هلال بن خباب، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب كن في الدنيا كأنك غريب أو عابر سبيل","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (2744), authenticated by Ibn Ḥibbān (6352), and al-Ḥākim (7858).","chapter_en":"Be in This World as Though You Were a Stranger or a Traveler Passing Through","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbās narrated: ʿUmar entered upon the Messenger of Allah ﷺ while he was lying on a woven mat that had left marks on his side. He said: “O Prophet of Allah, if only you would use bedding softer than this.” The Prophet ﷺ replied: “What do I have to do with this world? My example in relation to this world is only like that of a rider traveling on a hot summer day who rests in the shade of a tree for part of the day, then continues on and leaves it behind.”"]},"buhuth":{"en":["The words “softer than this” mean more comfortable and gentle."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (2744)، وصححه ابن حبان (6352)، والحاكم (7858)."},{"num":15067,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ اشْتَكَى سَلْمَانُ فَعَادَهُ سَعْدٌ فَرَآهُ يَبْكِي فَقَالَ لَهُ سَعْدٌ مَا يُبْكِيكَ يَا أَخِي أَلَيْسَ قَدْ صَحِبْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَلَيْسَ أَلَيْسَ قَالَ سَلْمَانُ مَا أَبْكِي وَاحِدَةً مِنَ اثْنَتَيْنِ مَا أَبْكِي صَبًّا لِلدُّنْيَا وَلاَ كَرَاهِيَةً لِلآخِرَةِ وَلَكِنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَهِدَ إِلَىَّ عَهْدًا فَمَا أُرَانِي إِلاَّ قَدْ تَعَدَّيْتُ. قَالَ وَمَا عَهِدَ إِلَيْكَ قَالَ عَهِدَ إِلَىَّ أَنَّهُ يَكْفِي أَحَدَكُمْ مِثْلُ زَادِ الرَّاكِبِ وَلاَ أُرَانِي إِلاَّ قَدْ تَعَدَّيْتُ وَأَمَّا أَنْتَ يَا سَعْدُ فَاتَّقِ اللَّهَ عِنْدَ حُكْمِكَ إِذَا حَكَمْتَ وَعِنْدَ قَسْمِكَ إِذَا قَسَمْتَ وَعِنْدَ هَمِّكَ إِذَا هَمَمْتَ. قَالَ ثَابِتٌ فَبَلَغَنِي أَنَّهُ مَا تَرَكَ إِلاَّ بِضْعَةً وَعِشْرِينَ دِرْهَمًا مِنْ نَفَقَةٍ كَانَتْ عِنْدَهُ."],"takhrij":"حسن: رواه ابن ماجه (4104)، والطبراني في الكبير (6/279)، وأبو نعيم في الحلية (1/197) كلهم من طريق الحسن بن أبي الربيع، حدثنا عبد الرزاق، حدثنا جعفر بن سليمان، عن ثابت، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب كن في الدنيا كأنك غريب أو عابر سبيل","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (4104), al-Ṭabarānī in al-Muʿjam al-Kabīr (6/279), and Abū Nuʿaym in al-Ḥilyah (1/197).","chapter_en":"Be in This World as Though You Were a Stranger or a Traveler Passing Through","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik reported: Salmān became ill, so Saʿd visited him and found him weeping. Saʿd asked him: “Why are you crying, my brother? Did you not accompany the Messenger of Allah ﷺ? Did you not…?” Salmān replied: “I am not crying for either of two reasons. I am not crying out of love for this world, nor out of dislike for the Hereafter. Rather, the Messenger of Allah ﷺ entrusted us with an instruction, and I think that I have exceeded it.” He asked: “What instruction did he give you?” Salmān replied: “He instructed me that what should suffice one of you is like the provisions of a traveler, and I think that I have exceeded that.” Then he said: “As for you, O Saʿd, fear Allah when you judge if you are called upon to judge, when you distribute if you are called upon to distribute, and when you resolve upon something if you resolve upon it.” Thābit said: “I was informed that when Salmān died, he left behind only a little over twenty dirhams from some spending money that he had.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10222],"tks":"حسن: رواه ابن ماجه (4104)، والطبراني في الكبير (6/279)، وأبو نعيم في الحلية (1/197)."},{"num":15068,"demo":false,"sanad":"","matn":["عَنْ يَحْيَى بْنِ جَعْدَةَ، قَالَ: عَادَ نَاسٌ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَبَّابًا، فَقَالُوا: أَبْشِرْ أَبَا عَبْدِ اللَّهِ تَرِدُ عَلَى مُحَمَّدٍ عَلَيْهِ الصلاة والسلام الْحَوْضَ، فَقَالَ: كَيْفَ بِهَذَا وَهَذِهِ أَسْفَلُ الْبَيْتِ وَأَعْلَاهُ وَقَدْ قَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا يَكْفِي أَحَدَكُمْ مِنَ الدُّنْيَا كَقَدْرِ زَادِ الرَّاكِبِ."],"takhrij":"صحيح: رواه ابن أبي شيبة (35450)، وأبو يعلى (7214)، والطبراني في الكبير (4/78) كلهم من طريق سفيان بن عيينة، عن عمرو –هو ابن دينار-، عن يحيى بن جعدة قال: فذكره.","grade":"صحيح","chapter_ar":"باب كن في الدنيا كأنك غريب أو عابر سبيل","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Abī Shaybah (35450), Abū Yaʿlā (7214), and al-Ṭabarānī in al-Muʿjam al-Kabīr (4/78).","chapter_en":"Be in This World as Though You Were a Stranger or a Traveler Passing Through","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Yaḥyā ibn Jaʿdah narrated: Some of the Companions of the Messenger of Allah ﷺ visited Khabbāb while he was ill. They said: “Rejoice, O Abū ʿAbdullāh! You will meet Muḥammad ﷺ at the Ḥawḍ.” He replied: “But what about all of this—what is at the bottom of the house and what is at the top of it? The Messenger of Allah ﷺ said to us: ‘The amount of this world sufficient for one of you is only like the provisions of a traveler.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن أبي شيبة (35450)، وأبو يعلى (7214)، والطبراني في الكبير (4/78)."},{"num":15069,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَيْسَ الْغِنَى عَنْ كَثْرَةِ الْعَرَضِ، وَلَكِنَّ الْغِنَى غِنَى النَّفْسِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6446)، ومسلم في الزكاة (1051) كلاهما من طرق عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب الغنى غنى النفس","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6446) and Muslim (1051).","chapter_en":"True Wealth Is the Wealth of the Soul","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Wealth is not having an abundance of possessions. Rather, true wealth is the wealth of the soul.”"]},"buhuth":{"en":["The meaning of “the wealth of the soul” is that the soul does not greedily desire or incline toward what other people possess."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6446)، ومسلم (1051)."},{"num":15070,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ الْغِنَى عَنْ كَثْرَةِ الْعَرَضِ، إِنَّمَا الْغِنَى غِنَى النَّفْسِ."],"takhrij":"صحيح: رواه البزار –كشف الأستار (3617)، وأبو الشيخ في الأمثال (75)، والطبراني في الأوسط –مجمع البحرين (4973)، وابن عبد البر في جامع بيان العلم (15) كلهم من طرق عن أنس قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الغنى غنى النفس","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzār, as cited in Kashf al-Astār (3617), Abū al-Shaykh in al-Amthāl (75), al-Ṭabarānī in al-Muʿjam al-Awsaṭ (4973, as cited in Majmaʿ al-Baḥrayn), and Ibn ʿAbd al-Barr in Jāmiʿ Bayān al-ʿIlm (2/20).","chapter_en":"True Wealth Is the Wealth of the Soul","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Wealth is not having an abundance of possessions. True wealth is the wealth of the soul.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار في كشف الأستار (3617)، وأبو الشيخ في الأمثال (75)، والطبراني في الأوسط في مجمع البحرين (4973)، وابن عبد البر في جامع بيان العلم (15)."},{"num":15071,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا أَبَا ذَرٍّ، أَتَرَى كَثْرَةَ الْمَالِ هُوَ الْغِنَى؟ قُلْتُ: نَعَمْ يَا رَسُولَ اللَّهِ، قَالَ: فَتَرَى قِلَّةَ الْمَالِ هُوَ الْفَقْرُ؟ قُلْتُ: نَعَمْ يَا رَسُولَ اللَّهِ، قَالَ: إِنَّمَا الْغِنَى غِنًى الْقَلْبِ وَالْفَقْرُ فَقْرُ الْقَلْبِ ثُمَّ سَأَلَنِي عَنْ رَجُلٍ مِنْ قُرَيْشٍ، فَقَالَ: هَلْ تَعْرِفُ فُلَانًا؟ ، قُلْتُ: نَعَمْ يَا رَسُولَ اللَّهِ، قَالَ: فَكَيْفَ تَرَاهُ أَوْ تَرَاهُ؟ قُلْتُ: إِذَا سَأَلَ أُعْطِيَ، وَإِذَا حَضَرَ أُدْخَلَ، ثُمَّ سَأَلَنِي عَنْ رَجُلٍ مِنْ أَهْلِ الصُّفَّةِ، فَقَالَ: هَلْ تَعْرِفُ فُلَانًا؟ قُلْتُ: لَا وَاللهِ، مَا أَعْرِفُهُ يَا رَسُولَ اللَّهِ، قَالَ: فَمَا زَالَ يُحَلِّيهُ، وَيَنْعَتُهُ حَتَّى عَرَفْتُهُ، فَقُلْتُ: قَدْ عَرَفْتُهُ يَا رَسُولَ اللَّهِ، قَالَ: فَكَيْفَ تَرَاهُ أَوْ تَرَاهُ؟ قُلْتُ: رَجُلٌ مِسْكِينٌ مِنْ أَهْلِ الصُّفَّةِ، فَقَالَ: هُوَ خَيْرٌ مِنْ طِلَاعِ الْأَرْضِ مِنْ الْآخَرِ قُلْتُ: يَا رَسُولًَ اللَّهِ أَفَلَا يُعْطَى مِن بَعْضِ مَا يُعْطَى الْآخَرُ؟ فَقَالَ: إِذَا أَعْطِيَ خَيْرًا فَهُوَ أَهْلُهُ، وَإِنْ صُرِفَ عَنْهُ فَقَدْ أُعْطِيَ حَسَنَةً."],"takhrij":"صحيح: رواه النسائي في الكبرى (11785)، وصحّحه ابن حبان (685)، والحاكم (7929) كلهم من طريق معاوية بن صالح، عن عبد الرحمن بن جبير بن نفير، عن أبيه، عن أبي ذر قال: فذكره.","grade":"صحيح","chapter_ar":"باب الغنى غنى النفس","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī in al-Sunan al-Kubrā (11785), authenticated by Ibn Ḥibbān (685), and al-Ḥākim (7929).","chapter_en":"True Wealth Is the Wealth of the Soul","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Abū Dharr narrated: The Messenger of Allah ﷺ said to me: “O Abū Dharr, do you think having much wealth is true richness?” I replied: “Yes, O Messenger of Allah.” He asked: “And do you think having little wealth is poverty?” I replied: “Yes, O Messenger of Allah.” He said: “True richness is the richness of the heart, and true poverty is the poverty of the heart.” Then he asked me about a man from Quraysh: “Do you know so-and-so?” I replied: “Yes, O Messenger of Allah.” He asked: “How do you regard him, and how is he regarded by people?” I replied: “If he asks, he is given; and when he comes, he is admitted.” Then he asked me about a man from Ahl al-Ṣuffah: “Do you know so-and-so?” I replied: “By Allah, I do not know him, O Messenger of Allah.” The Prophet ﷺ continued describing him to me until I recognized him. I said: “Now I know him, O Messenger of Allah.” He asked: “How do you regard him?” I replied: “He is a poor man from Ahl al-Ṣuffah.” The Prophet ﷺ said: “He is better than an earthful of the other man.” I asked: “O Messenger of Allah, should he not then be given some of what the other man is given?” He replied: “If he is given something good, he deserves it; and if it is withheld from him, then a good deed has still been given to him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي في الكبرى (11785)، وصححه ابن حبان (685)، والحاكم (7929)."},{"num":15072,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6508)، ومسلم في الذكر والدعاء (2686) من طرق عن أبي أسامة، عن بُريد، عن أبي بردة، عن أبي موسى فذكره.","grade":"متفق عليه","chapter_ar":"باب من أحب لقاء اللّٰه أحب اللّٰه لقاءه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6508) and Muslim (2686).","chapter_en":"Whoever Loves to Meet Allah, Allah Loves to Meet Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abū Mūsā narrated that the Prophet ﷺ said: “Whoever loves to meet Allah, Allah loves to meet him; and whoever dislikes meeting Allah, Allah dislikes meeting him.”"]}},"tuhfa":{},"full":1,"rep":[3507],"tks":"متفق عليه: رواه البخاري (6508)، ومسلم (2686)."},{"num":15073,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6507)، ومسلم في الذكر والدعاء (2683) كلاهما من طريق همام، عن قتادة، عن أنس بن مالك، عن عبادة بن الصامت فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب من أحب لقاء اللّٰه أحب اللّٰه لقاءه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6507) and Muslim (2683).","chapter_en":"Whoever Loves to Meet Allah, Allah Loves to Meet Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["ʿUbādah ibn al-Ṣāmit narrated that the Prophet ﷺ said: “Whoever loves to meet Allah, Allah loves to meet him; and whoever dislikes meeting Allah, Allah dislikes meeting him.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6507)، ومسلم (2683)."},{"num":15074,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ فَقُلْتُ: يَا نَبِيَّ اللَّهِ أَكَرَاهِيَةُ الْمَوْتِ؟ فَكُلُّنَا نَكْرَهُ الْمَوْتَ فَقَالَ: لَيْسَ كَذَلِكِ وَلَكِنَّ الْمُؤْمِنَ إِذَا بُشِّرَ بِرَحْمَةِ اللهِ وَرِضْوَانِهِ وَجَنَّتِهِ أَحَبَّ لِقَاءَ اللَّهِ، فَأَحَبَّ اللهُ لِقَاءَهُ، وَإِنَّ الْكَافِرَ إِذَا بُشِّرَ بِعَذَابِ اللهِ وَسَخَطِهِ كَرِهَ لِقَاءَ اللَّهِ، وَكَرِهَ اللهُ لِقَاءَهُ."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (15:2684) عن محمد بن عبد الله الرزي، حدثنا خالد بن الحارث الهجيمي، حدثنا سعيد، عن قتادة، عن زرارة، عن سعد بن هشام، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب من أحب لقاء اللّٰه أحب اللّٰه لقاءه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2684:15).","chapter_en":"Whoever Loves to Meet Allah, Allah Loves to Meet Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ said: “Whoever loves to meet Allah, Allah loves to meet him; and whoever dislikes meeting Allah, Allah dislikes meeting him.” I said: “O Prophet of Allah, do you mean disliking death? All of us dislike death.” He replied: “It is not like that. Rather, when the believer is given glad tidings of Allah’s mercy, His pleasure, and His Paradise, he loves to meet Allah, so Allah loves to meet him. And when the disbeliever is given tidings of Allah’s punishment and wrath, he dislikes meeting Allah, so Allah dislikes meeting him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3510,13496],"tks":"صحيح: رواه مسلم (15:2684)."},{"num":15075,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ، وَالْمَوْتُ قَبْلَ لِقَاءِ اللَّهِ."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (16:2684) عن أبي بكر بن أبي شيبة، حدثنا علي بن مسهر، عن زكريا، عن الشعبي، عن شريح بن هانئ، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب من أحب لقاء اللّٰه أحب اللّٰه لقاءه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2684:16).","chapter_en":"Whoever Loves to Meet Allah, Allah Loves to Meet Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ said: “Whoever loves to meet Allah, Allah loves to meet him; and whoever dislikes meeting Allah, Allah dislikes meeting him. Death comes before meeting Allah.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (16:2684)."},{"num":15076,"demo":false,"sanad":"","matn":["عَنْ شُرَيْحِ بْنِ هَانِئٍ، عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ قَالَ: فَأَتَيْتُ عَائِشَةَ فَقُلْتُ: يَا أُمَّ الْمُؤْمِنِينَ سَمِعْتُ أَبَا هُرَيْرَةَ يَذْكُرُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا، إِنْ كَانَ كَذَلِكَ فَقَدْ هَلَكْنَا فَقَالَتْ: إِنَّ الْهَالِكَ مَنْ هَلَكَ بِقَوْلِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَا ذَاكَ؟ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ وَلَيْسَ مِنَّا أَحَدٌ إِلَّا وَهُوَ يَكْرَهُ الْمَوْتَ فَقَالَتْ: قَدْ قَالَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَيْسَ بِالَّذِي تَذْهَبُ إِلَيْهِ، وَلَكِنْ إِذَا شَخَصَ الْبَصَرُ، وَحَشْرَجَ الصَّدْرُ، وَاقْشَعَرَّ الْجِلْدُ، وَتَشَنَّجَتِ الْأَصَابِعُ فَعِنْدَ ذَلِكَ مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2685) عن سعيد بن عمرو الأشعثي، أخبرنا عبثر، عن مطرف، عن عامر، عن شريح بن هانئ فذكره.","grade":"صحيح","chapter_ar":"باب من أحب لقاء اللّٰه أحب اللّٰه لقاءه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2685).","chapter_en":"Whoever Loves to Meet Allah, Allah Loves to Meet Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Shurayḥ ibn Hāniʾ narrated from Abū Hurayrah that the Messenger of Allah ﷺ said: “Whoever loves to meet Allah, Allah loves to meet him; and whoever dislikes meeting Allah, Allah dislikes meeting him.” Shurayḥ said: I went to ʿĀ’ishah and said: “O Mother of the Believers, I heard Abū Hurayrah narrating a hadith from the Messenger of Allah ﷺ. If it means what it appears to mean, then we are ruined.” She replied: “The one who is ruined is the one whom the words of the Messenger of Allah ﷺ declare ruined. What did he say?” I replied: “The Messenger of Allah ﷺ said: ‘Whoever loves to meet Allah, Allah loves to meet him; and whoever dislikes meeting Allah, Allah dislikes meeting him.’ Yet there is none among us who does not dislike death.” She said: “The Messenger of Allah ﷺ did indeed say it, but it does not mean what you think. Rather, when the eyes become fixed, the chest rattles, the skin shudders, and the fingers contract, then at that moment, whoever loves to meet Allah, Allah loves to meet him; and whoever dislikes meeting Allah, Allah dislikes meeting him.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2685)."},{"num":15077,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَحَبَّ لِقَاءَ اللَّهِ، أَحَبَّ اللهُ لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللَّهِ، كَرِهَ اللَّهُ لِقَاءَهُ، قُلْنَا: يَا رَسُولَ اللَّهِ، كُلُّنَا نَكْرَهُ الْمَوْتَ. قَالَ: لَيْسَ ذَاكَ كَرَاهِيَةَ الْمَوْتِ، وَلَكِنَّ الْمُؤْمِنَ إِذَا حُضِرَ جَاءَهُ الْبَشِيرُ مِنَ اللَّهِ، بِمَا هُوَ صَائِرٌ إِلَيْهِ، فَلَيْسَ شَيْءٌ أَحَبَّ إِلَيْهِ مِنْ أَنْ يَكُونَ قَدْ لَقِيَ اللَّهَ، فَأَحَبَّ اللهُ لِقَاءَهُ، وَإِنَّ الْفَاجِرَ، أَوِ الْكَافِرَ، إِذَا حُضِرَ جَاءَهُ بِمَا هُوَ صَائِرٌ إِلَيْهِ مِنَ الشَّرِّ، أَوْ مَا يَلْقَاهُ مِنَ الشَّرِّ، فَكَرِهَ لِقَاءَ اللَّهِ، وَكَرِهَ اللهُ لِقَاءَهُ."],"takhrij":"صحيح: رواه أحمد (12047) عن ابن أبي عدي، عن حميد، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب من أحب لقاء اللّٰه أحب اللّٰه لقاءه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (12047).","chapter_en":"Whoever Loves to Meet Allah, Allah Loves to Meet Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “Whoever loves to meet Allah, Allah loves to meet him; and whoever dislikes meeting Allah, Allah dislikes meeting him.” We said: “O Messenger of Allah, all of us dislike death.” He replied: “That is not what is meant by disliking death. Rather, when the believer receives glad tidings from Allah of what he is going toward, nothing becomes more beloved to him than meeting Allah, so Allah loves to meet him. But when the wicked person—or the disbeliever—is at the point of death and is informed of the evil toward which he is going—or the evil he will encounter—he dislikes meeting Allah, and Allah dislikes meeting him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3511],"tks":"صحيح: رواه أحمد (12047)."},{"num":15078,"demo":false,"sanad":"","matn":["عَنْ عَطَاءِ بن السائب قال: سَمِعْتُ عَبْدَ الرَّحْمَنِ بْنَ أَبِي لَيْلَى وَهُوَ فِي جَنَازَةٍ، وَذَلِكَ أَوَّلَ يَوْمٍ عَرَفْتُهُ فِيهِ، سمعته يَقُولُ: [ثنا فُلَانٌ] رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، رضي الله عنه، أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يَقُولُ: مَنْ أَحَبَّ لقاء الله عز وجل، أَحَبَّ اللَّهُ تعالى لِقَاءَهُ، وَمَنْ كَرِهَ لِقَاءَ اللَّهِ تعالى كره الله عز وجل لِقَاءَهُ. فَبَكَى الْقَوْمُ. فقالوا: يَا رَسُولَ اللَّهِ، وَأَيُّنَا لَا يَكْرَهُ الْمَوْتَ؟ قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَسْتُ ذَلِكَ أَعْنِي، وَلَكِنَّ اللَّهَ تبارك وتعالى قَالَ: ﴿فَأَمَّا إِنْ كَانَ مِنَ الْمُقَرَّبِينَ (٨٨)، فَرَوْحٌ وَرَيْحَانٌ وَجَنَّتُ نَعِيمٍ (٨٩)﴾. فَإِذَا كَانَ عِنْدَ ذَلِكَ / أَحَبَّ لقاء الله تعالى، والله عز وجل لِلِقَائِهِ أَحَبُّ، ﴿وَأَمَّا إِنْ كَانَ مِنَ الْمُكَذِّبِينَ الظَّالِينَ (٩٢) فَنُزُلٌ مِنْ حَمِيمٍ (٩٣)﴾. فإذا كان كذلك، كَرِهَ لقاء الله تعالى، والله عز وجل لِلِقَائِهِ أَكْرَهُ."],"takhrij":"صحيح: رواه ابن أبي عمر العدني في مسنده –كما في المطالب (3211)- عن سفيان (هو ابن عيينة)، عن عطاء بن السائب قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من أحب لقاء اللّٰه أحب اللّٰه لقاءه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Abī ʿUmar al-ʿAdanī in his Musnad, as cited in al-Maṭālib (3211), and Aḥmad (18283).","chapter_en":"Whoever Loves to Meet Allah, Allah Loves to Meet Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["ʿAṭāʾ ibn al-Sā’ib said: I heard ʿAbd al-Raḥmān ibn Abī Laylā while he was attending a funeral, and that was the first day I came to know him. I heard him say: A man from among the Companions of the Prophet ﷺ narrated to us that he heard the Prophet ﷺ say: “Whoever loves to meet Allah, Mighty and Majestic, Allah, the Exalted, loves to meet him; and whoever dislikes meeting Allah, the Exalted, Allah, Mighty and Majestic, dislikes meeting him.” The people began to weep and said: “O Messenger of Allah, which of us does not dislike death?” He replied: “That is not what I mean. Rather, Allah, Blessed and Exalted, says: ‘Then if he is one of those brought near, then for him are rest, fragrant provision, and a Garden of bliss.’ [Sūrat al-Wāqiʿah 56:88–89] When that time comes, he loves to meet Allah, the Exalted, and Allah, Mighty and Majestic, loves even more to meet him. And Allah says: ‘But if he is one of the deniers who went astray, then his accommodation will be scalding water.’ [Sūrat al-Wāqiʿah 56:92–93] When that time comes, he dislikes meeting Allah, the Exalted, and Allah, Mighty and Majestic, dislikes meeting him even more.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن أبي عمر العدني في مسنده - كما في المطالب (3211) - وأحمد (18283)."},{"num":15079,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا يَرْوِي عَنْ رَبِّهِ عَزَّ وَجَلَّ قَالَ قَالَ إِنَّ اللَّهَ كَتَبَ الْحَسَنَاتِ وَالسَّيِّئَاتِ، ثُمَّ بَيَّنَ ذَلِكَ فَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ لَهُ عِنْدَهُ حَسَنَةً كَامِلَةً، فَإِنْ هُوَ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ لَهُ عِنْدَهُ عَشْرَ حَسَنَاتٍ إِلَى سَبْعِمِائَةِ ضِعْفٍ إِلَى أَضْعَافٍ كَثِيرَةٍ، وَمَنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ لَهُ عِنْدَهُ حَسَنَةً كَامِلَةً، فَإِنْ هُوَ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ لَهُ سَيِّئَةً وَاحِدَةً."],"takhrij":"متفق عليه: رواه البخاري الرقاق (6491)، ومسلم في الإيمان (131) كلاهما من حديث عبد الوارث، عن الجعد أبي عثمان، حدثنا أبو رجاء العطاردي، عن ابن عباس فذكره. وزاد مسلم: ومحاها الله، ولا يهلك عن الله إلا هالك.","grade":"متفق عليه","chapter_ar":"باب إذا هم العبد بحسنة كتبت، وإذا هم بسيئة لم تكتب","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6491) and Muslim (131).","chapter_en":"If the Servant Intends a Good Deed, It Is Written for Him; and If He Intends an Evil Deed, It Is Not Written against Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbās narrated from the Prophet ﷺ, relating from his Lord, Mighty and Majestic, that He said: “Allah has written down the good deeds and the evil deeds, then He explained them. Whoever intends a good deed but does not perform it, Allah records it for him as one complete good deed. If he intends it and then performs it, Allah records it for him as ten good deeds, up to seven hundred times as much, and up to many times beyond that. And whoever intends an evil deed but does not perform it, Allah records it for him as one complete good deed. If he intends it and then performs it, Allah records it against him as one evil deed.”"]},"buhuth":{"ar":["وزاد مسلم:","ومحاها اللّٰه، ولا يهلك على اللّٰه إلا هالك."],"en":["Muslim adds:","“And Allah erases it, and none is ruined with Allah except one who is truly ruined.”"]}},"tuhfa":{},"full":1,"rep":[12330],"tks":"متفق عليه: رواه البخاري (6491)، ومسلم (131)."},{"num":15080,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ يَقُولُ اللَّهُ إِذَا أَرَادَ عَبْدِي أَنْ يَعْمَلَ سَيِّئَةً فَلاَ تَكْتُبُوهَا عَلَيْهِ حَتَّى يَعْمَلَهَا، فَإِنْ عَمِلَهَا فَاكْتُبُوهَا بِمِثْلِهَا وَإِنْ تَرَكَهَا مِنْ أَجْلِي فَاكْتُبُوهَا لَهُ حَسَنَةً وَإِذَا أَرَادَ أَنْ يَعْمَلَ حَسَنَةً فَلَمْ يَعْمَلْهَا فَاكْتُبُوهَا لَهُ حَسَنَةً، فَإِنْ عَمِلَهَا فَاكْتُبُوهَا لَهُ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِمِائَةٍ."],"takhrij":"متفق عليه: رواه البخاري في التوحيد (7501)، ومسلم في الإيمان (203:128) كلاهما من طريق أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب إذا هم العبد بحسنة كتبت، وإذا هم بسيئة لم تكتب","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7501) and Muslim (128:203).","chapter_en":"If the Servant Intends a Good Deed, It Is Written for Him; and If He Intends an Evil Deed, It Is Not Written against Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Allah says: ʿIf My servant intends to perform an evil deed, do not write it against him until he actually does it. If he does it, record it as one evil deed. If he leaves it for My sake, record it for him as a good deed. And if he intends to perform a good deed but does not perform it, record it for him as a good deed. If he performs it, record it for him as ten times its reward, up to seven hundred times.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7501)، ومسلم (203:128)."},{"num":15081,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَحْسَنَ أَحَدُكُمْ إِسْلاَمَهُ، فَكُلُّ حَسَنَةٍ يَعْمَلُهَا تُكْتَبُ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِ مئة ضِعْفٍ، وَكُلُّ سَيِّئَةٍ يَعْمَلُهَا تُكْتَبُ بِمِثْلِهَا حَتَّى يلقى اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في الإيمان (42)، ومسلم في الإيمان (205:129) كلاهما من طريق عبدالرزاق، أخبرنا معمر، عن همام بن منبه، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب إذا هم العبد بحسنة كتبت، وإذا هم بسيئة لم تكتب","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (42) and Muslim (129:205).","chapter_en":"If the Servant Intends a Good Deed, It Is Written for Him; and If He Intends an Evil Deed, It Is Not Written against Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When one of you perfects his Islam, every good deed he performs is recorded as ten times its reward up to seven hundred times, while every evil deed he performs is recorded only as its equivalent, until he meets Allah.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (42)، ومسلم (205:129)."},{"num":15082,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَالَ اللَّهُ عَزَّ وَجَلَّ:  إِذَا هَمَّ عَبْدِي بِحَسَنَةٍ وَلَمْ يَعْمَلْهَا كَتَبْتُهَا لَهُ حَسَنَةً، فَإِنْ عَمِلَهَا كَتَبْتُهَا عَشْرَ حَسَنَاتٍ إِلَى سَبْعِمِائَةِ ضِعْفٍ، وَإِذَا هَمَّ بِسَيِّئَةٍ وَلَمْ يَعْمَلْهَا لَمْ أَكْتُبْهَا عَلَيْهِ، فَإِنْ عَمِلَهَا كَتَبْتُهَا سَيِّئَةً وَاحِدَةً."],"takhrij":"صحيح: رواه مسلم في الإيمان (204:128) من طرق عن إسماعيل بن جعفر، عن العلاء، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إذا هم العبد بحسنة كتبت، وإذا هم بسيئة لم تكتب","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (128:204).","chapter_en":"If the Servant Intends a Good Deed, It Is Written for Him; and If He Intends an Evil Deed, It Is Not Written against Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Allah, Mighty and Majestic, says: ʿIf My servant intends a good deed but does not perform it, I record it for him as one good deed. If he performs it, I record it as ten good deeds up to seven hundred times. And if he intends an evil deed but does not perform it, I do not record it against him. If he performs it, I record it as one evil deed.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (204:128)."},{"num":15083,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَالَ اللَّهُ عَزَّ وَجَلَّ: إِذَا تَحَدَّثَ عَبْدِي بِأَنْ يَعْمَلَ حَسَنَةً فَأَنَا أَكْتُبُهَا لَهُ حَسَنَةً مَا لَمْ يَعْمَلْ، فَإِذَا عَمِلَهَا فَأَنَا أَكْتُبُهَا بِعَشْرِ أَمْثَالِهَا، وَإِذَا تَحَدَّثَ بِأَنْ يَعْمَلَ سَيِّئَةً فَأَنَا أَغْفِرُهَا لَهُ مَا لَمْ يَعْمَلْهَا، فَإِذَا عَمِلَهَا فَأَنَا أَكْتُبُهَا لَهُ بِمِثْلِهَا."],"takhrij":"صحيح: رواه مسلم في الإيمان (129) عن محمد بن رافع، حدثنا عبد الرزاق، أخبرنا معمر، عن همام بن منبّه قال: هذا ما حدثنا أبو هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إذا هم العبد بحسنة كتبت، وإذا هم بسيئة لم تكتب","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (129).","chapter_en":"If the Servant Intends a Good Deed, It Is Written for Him; and If He Intends an Evil Deed, It Is Not Written against Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Allah, Mighty and Majestic, says: ʿWhen My servant speaks within himself of doing a good deed, I record it for him as a good deed even before he performs it. When he performs it, I record it for him as ten times its reward. And when he speaks within himself of doing an evil deed, I forgive it for him as long as he does not perform it. If he performs it, I record it against him only as its equivalent.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (129)."},{"num":15084,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَتِ الْمَلَائِكَةُ: رَبِّ ذَاكَ عَبْدُكَ يُرِيدُ أَنْ يَعْمَلَ سَيِّئَةً (وَهُوَ أَبْصَرُ بِهِ) فَقَالَ: ارْقُبُوهُ، فَإِنْ عَمِلَهَا فَاكْتُبُوهَا لَهُ بِمِثْلِهَا، وَإِنْ تَرَكَهَا فَاكْتُبُوهَا لَهُ حَسَنَةً، إِنَّمَا تَرَكَهَا مِنْ جَرَّايَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (129) عن محمد بن رافع، حدثنا عبد الرزاق، أخبرنا معمر، عن همام بن منبّه قال: هذا ما حدثنا أبو هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إذا هم العبد بحسنة كتبت، وإذا هم بسيئة لم تكتب","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (129).","chapter_en":"If the Servant Intends a Good Deed, It Is Written for Him; and If He Intends an Evil Deed, It Is Not Written against Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The angels say: ‘My Lord, that servant of Yours intends to commit an evil deed’—and He knows him best. Allah says: ‘Watch him. If he performs it, record it against him as one equivalent evil deed. If he leaves it, record it for him as a good deed, for he only left it for My sake.’”"]}},"tuhfa":{},"full":1,"rep":[592],"tks":"صحيح: رواه مسلم (129)."},{"num":15085,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كُتِبَتْ لَهُ حَسَنَةً، وَمَنْ هَمَّ بِحَسَنَةٍ فَعَمِلَهَا كُتِبَتْ لَهُ عَشْرًا إِلَى سَبْعِمِائَةِ ضِعْفٍ، وَمَنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا لَمْ تُكْتَبْ، وَإِنْ عَمِلَهَا كُتِبَتْ."],"takhrij":"صحيح: رواه مسلم في الإيمان (130) عن أبي كريب، حدثنا أبو خالد الأحمر، عن هشام، عن ابن سيرين، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إذا هم العبد بحسنة كتبت، وإذا هم بسيئة لم تكتب","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (130).","chapter_en":"If the Servant Intends a Good Deed, It Is Written for Him; and If He Intends an Evil Deed, It Is Not Written against Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever intends a good deed but does not perform it has one good deed recorded for him. Whoever intends a good deed and performs it has ten to seven hundred times its reward recorded for him. Whoever intends an evil deed but does not perform it, it is not recorded against him; and if he performs it, it is recorded.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (130)."},{"num":15086,"demo":false,"sanad":"","matn":["عَنْ خُرَيْمِ بْنِ فَاتِكٍ الْأَسَدِيِّ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: النَّاسُ أَرْبَعَةٌ، وَالْأَعْمَالُ سِتَّةٌ، فَالنَّاسُ مُوَسَّعٌ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَمُوَسَّعٌ لَهُ فِي الدُّنْيَا مَقْتُورٌ عَلَيْهِ فِي الْآخِرَةِ، وَمَقْتُورٌ عَلَيْهِ فِي الدُّنْيَا مُوَسَّعٌ عَلَيْهِ فِي الْآخِرَةِ، وَشَقِيٌّ فِي الدُّنْيَا وَالْآخِرَةِ. وَالْأَعْمَالُ: مُوجِبَتَانِ، وَمِثْلٌ بِمِثْلٍ، وَعَشْرَةُ أَضْعَافٍ، وَسَبْعُ مِائَةِ ضِعْفٍ. فَالموجِبَتَانِ: مَنْ مَاتَ مُسْلِمًا مُؤْمِنًا لَا يُشْرِكُ بِالله شَيْئًا فَوَجَبَتْ لَهُ الجنة، وَمَنْ مَاتَ كَافِرًا وَجَبَتْ لَهُ النَّارُ، وَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا فَعَلِمَ الله أَنَّهُ قَدْ أَشْعَرَهَا قَلْبَهُ وَحَرَصَ عَلَيْهَا كُتِبَتْ لَهُ حَسَنَةً، وَمَنْ هَمَّ بِسَيِّئَةٍ لَمْ تُكْتَبْ عَلَيْهِ، وَمَنْ عَمِلَهَا كُتِبَتْ وَاحِدَةً وَلَمْ تُضَاعَفْ عَلَيْهِ، وَمَنْ عَمِلَ حَسَنَةً كَانَتْ لَهُ بِعَشْرِ أَمْثَالِهَا، وَمَنْ أَنْفَقَ نَفَقَةً فِي سَبِيلِ الله كَانَتْ لَهُ بِسَبْعِ مِائَةِ ضِعْفٍ."],"takhrij":"حسن: رواه الإمام أحمد (19035)، وابن حبان (6171)، والطبراني في الكبير (4153) كلهم من طريق شيبان بن عبد الرحمن النحوي، عن الركين بن الربيع، عن أبيه، عن عمّه يُسير بن عَمِيلة، عن خُريم بن فاتك الأسدي قال: فذكره.","grade":"حسن","chapter_ar":"باب إذا هم العبد بحسنة كتبت، وإذا هم بسيئة لم تكتب","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (19035), Ibn Ḥibbān (6171), and al-Ṭabarānī in al-Muʿjam al-Kabīr (4/206).","chapter_en":"If the Servant Intends a Good Deed, It Is Written for Him; and If He Intends an Evil Deed, It Is Not Written against Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Khuraym ibn Fātik al-Asadī narrated that the Prophet ﷺ said: “People are of four kinds, and deeds are of six kinds. As for people: one is given abundance in this world and in the Hereafter; one is given abundance in this world but restricted in the Hereafter; one is restricted in this world but given abundance in the Hereafter; and one is wretched in both this world and the Hereafter. As for deeds: two make an outcome obligatory, one is rewarded like-for-like, one is multiplied tenfold, and one is multiplied seven hundredfold. The two that make an outcome obligatory are these: whoever dies as a believing Muslim without associating anything with Allah, Paradise becomes obligatory for him; and whoever dies as a disbeliever, the Fire becomes obligatory for him. Whoever intends a good deed but does not perform it, while Allah knows that his heart truly desired it and was eager for it, one good deed is recorded for him. Whoever intends an evil deed, it is not recorded against him. If he commits it, it is recorded as one evil deed and is not multiplied against him. Whoever performs a good deed receives ten times its reward, and whoever spends in the path of Allah receives seven hundred times its reward.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (19035)، وابن حبان (6171)، والطبراني في الكبير (4153)."},{"num":15087,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذرّ قَالَ: خَرَجْتُ لَيْلَةً مِنَ اللَّيَالِي، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْشِي وَحْدَهُ لَيْسَ مَعَهُ إِنْسَانٌ، قَالَ: فَظَنَنْتُ أَنَّهُ يَكْرَهُ أَنْ يَمْشِيَ مَعَهُ أَحَدٌ، قَالَ: فَجَعَلْتُ أَمْشِي فِي ظِلِّ الْقَمَرِ فَالْتَفَتَ فَرَآنِي، فَقَالَ: مَنْ هَذَا؟ فَقُلْتُ: أَبُو ذَرٍّ، جَعَلَنِي اللَّهُ فِدَاكَ، قَالَ: يَا أَبَا ذَرٍّ تَعَالَهْ قَالَ: فَمَشَيْتُ مَعَهُ سَاعَةً، فَقَالَ: إِنَّ الْمُكْثِرِينَ هُمُ الْمُقِلُّونَ يَوْمَ الْقِيَامَةِ، إِلاَّ مَنْ أَعْطَاهُ اللَّهُ خَيْرًا، فَنَفَحَ فِيهِ يَمِينَهُ وَشِمَالَهُ، وَبَيْنَ يَدَيْهِ وَوَرَاءَهُ، وَعَمِلَ فِيهِ خَيْرًا قَالَ: فَمَشَيْتُ مَعَهُ سَاعَةً، فَقَالَ: اجْلِسْ ههنا قَالَ: فَأَجْلَسَنِي فِي قَاعٍ حَوْلَهُ حِجَارَةٌ، فَقَالَ لِي: اجْلِسْ ههنا حَتَّى أَرْجِعَ إِلَيْكَ قَالَ: فَانْطَلَقَ فِي الْحَرَّةِ حَتَّى لاَ أَرَاهُ، فَلَبِثَ عَنِّي، فَأَطَالَ اللُّبْثَ، ثُمَّ إِنِّي سَمِعْتُهُ وَهْوَ مُقْبِلٌ وَهْوَ يَقُولُ: وَإِنْ سَرَقَ وَإِنْ زَنَى قَالَ: فَلَمَّا جَاءَ لَمْ أَصْبِرْ فَقُلْتُ: يَا نَبِيَّ اللَّهِ جَعَلَنِي اللَّهُ فِدَاكَ، مَنْ تُكَلِّمُ فِي جَانِبِ الْحَرَّةِ؟ مَا سَمِعْتُ أَحَدًا يَرْجِعُ إِلَيْكَ شَيْئًا، قَالَ: ذَاكَ جِبْرِيلُ، عَرَضَ لِي فِي جَانِبِ الْحَرَّةِ، فَقَالَ: بشّر أُمَّتَكَ أَنَّهُ مَنْ مَاتَ لاَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ، فَقُلْتُ: يَا جِبْرِيلُ وَإِنْ سَرَقَ وَإِنْ زَنَى؟ قَالَ: نَعَمْ، قَالَ قُلْتُ: وَإِنْ سَرَقَ وَإِنْ زَنَى؟ قَالَ: نَعَمْ، قَالَ قُلْتُ: وَإِنْ سَرَقَ وَإِنْ زَنَى؟ قَالَ: نَعَمْ، وَإِنْ شَرِبَ الْخَمْرَ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6443)، ومسلم في الزكاة (33:94) كلاهما عن قتيبة بن سعيد، حدثني جرير، عن عبد العزيز بن رفيع، عن زيد بن وهب، عن أبي ذرّ فذكره.","grade":"متفق عليه","chapter_ar":"باب المكثرون في الدنيا هم المقلون في الآخرة إلا من عمل فيها خيرًا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6443) and Muslim (94:33).","chapter_en":"Those Who Possess Much in This World Will Have Little in the Hereafter, Except Those Who Use It for Good","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Abū Dharr narrated: One night I went out and found the Messenger of Allah ﷺ walking alone, with no one accompanying him. I thought that perhaps he disliked anyone walking with him, so I began walking in the moonlight at a distance. He turned, saw me, and asked: “Who is this?” I replied: “Abū Dharr. May Allah make me your ransom.” He said: “O Abū Dharr, come here.” I walked with him for a while, and he said: “Those who possess much will be those who possess little on the Day of Resurrection, except one whom Allah has given wealth and who distributes it to his right, his left, in front of him, and behind him, and uses it for good.” We continued walking for a while. Then he said: “Sit here.” He seated me in a low area surrounded by stones and said: “Remain here until I return to you.” He went into the rocky plain until I could no longer see him. He remained away for quite some time. Then I heard him approaching while saying: “Even if he steals and even if he commits adultery.” When he returned, I could not restrain myself, so I asked: “O Prophet of Allah, may Allah make me your ransom, who was speaking to you on the side of the rocky plain? I did not hear anyone answering you.” He replied: “That was Jibrīl. He appeared to me at the side of the rocky plain and said: ‘Give your Ummah glad tidings that whoever dies without associating anything with Allah will enter Paradise.’ I said: ‘O Jibrīl, even if he steals and commits adultery?’ He said: ‘Yes.’ I said: ‘Even if he steals and commits adultery?’ He said: ‘Yes.’ I said: ‘Even if he steals and commits adultery?’ He said: ‘Yes, even if he drinks alcohol.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6443)، ومسلم (33:94)."},{"num":15088,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَحْنُ الآخِرُونَ الأَوَّلُونَ يَوْمَ الْقِيَامَةِ، وَإِنَّ الأَكْثَرِينَ هُمُ الأَسْفَلُونَ، إِلَاّ مَنْ قَالَ هَكَذَا وَهَكَذَا عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ وَمِنْ خَلْفِهِ وَبَيْنَ يَدَيْهِ وَيَحْثِي بِثَوْبِهِ."],"takhrij":"صحيح: رواه ابن حبان في صحيحه (3217) عن الفريابي، قال: حدثنا علي بن حجر السعدي، قال: حدثنا علي بن مسهر، عن أبي إسحاق، عن أبي الأحوص، عن عبد الله بن مسعود فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب المكثرون في الدنيا هم المقلون في الآخرة إلا من عمل فيها خيرًا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Ḥibbān in his Ṣaḥīḥ (3217).","chapter_en":"Those Who Possess Much in This World Will Have Little in the Hereafter, Except Those Who Use It for Good","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “We are the last in this world but the first on the Day of Resurrection. And those who possess the most will be the lowest, except the one who spends like this and like this—to his right and to his left, behind him and in front of him—scattering his wealth generously.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه ابن حبان في صحيحه (3217)."},{"num":15089,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: كُنْتُ أَمْشِي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَخْلٍ لِبَعْضِ أَهْلِ الْمَدِينَةِ، فَقَالَ: يَا أَبَا هُرَيْرَةَ، هَلَكَ الْمُكْثِرُونَ، إِلَّا مَنْ قَالَ هَكَذَا وَهَكَذَا وَهَكَذَا - ثَلَاثَ مَرَّاتٍ: حَثَا بِكَفَّيْهِ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ وَبَيْنَ يَدَيْهِ -، وَقَلِيلٌ مَا هُمْ ثُمَّ مَشَى سَاعَةً فَقَالَ: يَا أَبَا هُرَيْرَةَ، أَلَا أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ؟ فَقُلْتُ: بَلَى يَا رَسُولَ اللَّهِ. فَقَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ، وَلَا مَلْجَأَ مِنَ اللَّهِ إِلَّا إِلَيْهِ ثُمَّ مَشَى سَاعَةً فَقَالَ: يَا أَبَا هُرَيْرَةَ، هَلْ تَدْرِي مَا حَقُّ النَّاسِ عَلَى اللَّهِ، وَمَا حَقُّ اللَّهِ عَلَى النَّاسِ؟ قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: فَإِنَّ حَقَّ اللَّهِ عَلَى النَّاسِ أَنْ يَعْبُدُوهُ وَلَا يُشْرِكُوا بِهِ شَيْئًا، فَإِذَا فَعَلُوا ذَلِكَ فَحَقٌّ عَلَيْهِ أَنْ لَا يُعَذِّبَهُمْ."],"takhrij":"صحيح: رواه عبد الرزاق (20547) – وعنه أحمد (8085) عن معمر، عن أبي إسحاق، عن كميل بن زياد، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب المكثرون في الدنيا هم المقلون في الآخرة إلا من عمل فيها خيرًا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by ʿAbd al-Razzāq (20547), and through him by Aḥmad (8085).","chapter_en":"Those Who Possess Much in This World Will Have Little in the Hereafter, Except Those Who Use It for Good","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah narrated: I was walking with the Messenger of Allah ﷺ among date palms belonging to some people of Madinah. He said: “O Abū Hurayrah, those who possess much are ruined, except the one who gives like this, and like this, and like this.” He said it three times, scattering with both hands to his right, his left, and in front of him. Then he said: “And how few they are.” We walked for a while, then he said: “O Abū Hurayrah, shall I direct you to one of the treasures of Paradise?” I replied: “Yes, O Messenger of Allah.” He said: “There is no power and no strength except through Allah, and there is no refuge from Allah except with Him.” We walked for a while longer, then he said: “O Abū Hurayrah, do you know what right the people have upon Allah and what right Allah has upon the people?” I replied: “Allah and His Messenger know best.” He said: “Allah’s right upon the people is that they worship Him and associate nothing with Him. If they do that, then it is a right upon Him that He will not punish them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه عبد الرزاق (20547)، وعنه أحمد (8085)."},{"num":15090,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّكُمْ مَالُ وَارِثِهِ أَحَبُّ إِلَيْهِ مِنْ مَالِهِ؟ قَالُوا: يَا رَسُولَ اللَّهِ، مَا مِنَّا أَحَدٌ إِلاَّ مَالُهُ أَحَبُّ إِلَيْهِ، قَالَ: فَإِنَّ مَالَهُ مَا قدّم، وَمَالُ وَارِثِهِ مَا أخّر."],"takhrij":"صحيح: رواه البخاري في الرقاق (6442) عن عمر بن حفص، حدثني أبي، حدثنا الأعمش، حدثني إبراهيم التيمي، عن الحارث بن سويد قال: قال عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب ما قدم الإنسان من ماله فهو له، وما أخره فهو لورثته","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6442).","chapter_en":"What a Person Sends Forward from His Wealth Is Truly His, while What He Leaves Behind Belongs to His Heirs","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Prophet ﷺ said: “Which of you loves the wealth of his heir more than his own wealth?” They replied: “O Messenger of Allah, there is none among us except that his own wealth is more beloved to him.” He said: “Then his true wealth is what he sends forward, while the wealth of his heir is what he leaves behind.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6442)."},{"num":15091,"demo":false,"sanad":"","matn":["عَنْ مُطَرِّفٍ، عَنْ أَبِيهِ قَالَ:  أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَقْرَأُ: ﴿أَلْهَاكُمُ التَّكَاثُرُ﴾. قَالَ: يَقُولُ ابْنُ آدَمَ: مَالِي مَالِي. قَالَ: وَهَلْ لَكَ يَا ابْنَ آدَمَ مِنْ مَالِكَ إِلَّا مَا أَكَلْتَ فَأَفْنَيْتَ، أَوْ لَبِسْتَ فَأَبْلَيْتَ، أَوْ تَصَدَّقْتَ فَأَمْضَيْتَ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (2958) عن عداب بن خالد، حدثنا همّام، حدثنا قتادة، عن مطرف، عن أبيه قال فذكره.","grade":"صحيح","chapter_ar":"باب ما قدم الإنسان من ماله فهو له، وما أخره فهو لورثته","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2958).","chapter_en":"What a Person Sends Forward from His Wealth Is Truly His, while What He Leaves Behind Belongs to His Heirs","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Muṭarrif narrated from his father: I came to the Prophet ﷺ while he was reciting: “Competition for increase distracts you.” He said: “The son of Ādam says: ‘My wealth! My wealth!’” Then he said: “O son of Ādam, what truly belongs to you from your wealth except what you ate and consumed, what you wore and wore out, or what you gave in charity and thereby sent forward?”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2958)."},{"num":15092,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  يَقُولُ الْعَبْدُ: مَالِي مَالِي، إِنَّمَا لَهُ مِنْ مَالِهِ ثَلَاثٌ: مَا أَكَلَ فَأَفْنَى، أَوْ لَبِسَ فَأَبْلَى، أَوْ أَعْطَى فَاقْتَنَى، وَمَا سِوَى ذَلِكَ فَهُوَ ذَاهِبٌ وَتَارِكُهُ لِلنَّاسِ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (2959) من طرق عن العلاء بن عبدالرحمن، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما قدم الإنسان من ماله فهو له، وما أخره فهو لورثته","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2959).","chapter_en":"What a Person Sends Forward from His Wealth Is Truly His, while What He Leaves Behind Belongs to His Heirs","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The servant says: ‘My wealth! My wealth!’ Yet only three things from his wealth truly belong to him: what he eats and consumes, what he wears and wears out, and what he gives away and thereby stores for himself. Anything beyond that is departing from him, and he will leave it behind for other people.”"]}},"tuhfa":{},"full":1,"rep":[12314],"tks":"صحيح: رواه مسلم (2959)."},{"num":15093,"demo":false,"sanad":"","matn":["عَنْ الْمُسْتَوْرِدِ بن شَدَّادٍ أخي بَنِي فِهْرٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَاللهِ مَا الدُّنْيَا فِي الْآخِرَةِ إِلَّا مِثْلُ مَا يَجْعَلُ أَحَدُكُمْ إِصْبَعَهُ هَذِهِ فِي الْيَمِّ، فَلْيَنْظُرْ بِمَ تَرْجِعُ."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها (55:2858) من طرق عن إسماعيل بن أبي خالد، حدثنا قيس قال: سمعت مستوردا فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الترغيب عن الدنيا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2858:55).","chapter_en":"What Has Been Narrated Encouraging Detachment from This World","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Al-Mustawrid ibn Shaddād, the brother of Banū Fihr, narrated that the Messenger of Allah ﷺ said: “By Allah, this world compared with the Hereafter is only like when one of you places this finger of his into the sea; let him then see how much it brings back.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (55:2858)."},{"num":15094,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْ كَانَتِ الدُّنْيَا تَعْدِلُ عِنْدَ اللَّهِ جَنَاحُ بَعُوضَةٍ مَا سقى كَافِرًا مِنْهَا شربةً مِنْ مَاءٍ."],"takhrij":"حسن: رواه ابن أبي عاصم في الزهد (130)، والبزار (8176) كلاهما من طرق عن محمد بن عمار بن جعفر المدني، عن صالح مولى التوأمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الترغيب عن الدنيا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī ʿĀṣim in al-Zuhd (130) and al-Bazzār (8176).","chapter_en":"What Has Been Narrated Encouraging Detachment from This World","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “If this world were worth even the wing of a mosquito to Allah, He would not have given a disbeliever even a drink of water from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في الزهد (130)، والبزار (8176)."},{"num":15095,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهصلى الله عليه وسلم: مَنْ طَلَبَ الدُّنْيَا أَضَرَّ بِالْآخِرَةِ، وَمَنْ طَلَبَ الْآخِرَةَ أَضَرَّ بِالدُّنْيَا. فَسَمِعْتُهُ قَالَ: فأَضِرُّوا بِالْفَانِي لِلْبَاقِي."],"takhrij":"حسن: رواه ابنُ أبي عاصم في الزهد (161) عن هدية بن عبدالوهاب، أخبرنا الفضل بن موسى، أخبرنا محمد بن عمرو، عن أبي سلمة، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الترغيب عن الدنيا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī ʿĀṣim in al-Zuhd (161).","chapter_en":"What Has Been Narrated Encouraging Detachment from This World","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever pursues this world does so at the expense of the Hereafter, and whoever pursues the Hereafter does so at the expense of this world.” Then I heard him say: “So let the perishing one be diminished for the sake of the everlasting one.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في الزهد (161)."},{"num":15096,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ:  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِالسُّوقِ دَاخِلًا مِنْ بَعْضِ الْعَالِيَةِ وَالنَّاسُ كَنَفَتَيْهِ، فَمَرَّ بِجَدْيٍ أَسَكَّ مَيِّتٍ، فَتَنَاوَلَهُ فَأَخَذَ بِأُذُنِهِ ثُمَّ قَالَ: أَيُّكُمْ يُحِبُّ أَنَّ هَذَا لَهُ بِدِرْهَمٍ؟ فَقَالُوا: مَا نُحِبُّ أَنَّهُ لَنَا بِشَيْءٍ، وَمَا نَصْنَعُ بِهِ؟ قَالَ: أَتُحِبُّونَ أَنَّهُ لَكُمْ؟ قَالُوا: وَاللهِ لَوْ كَانَ حَيًّا كَانَ عَيْبًا فِيهِ لِأَنَّهُ أَسَكُّ، فَكَيْفَ وَهُوَ مَيِّتٌ! فَقَالَ: فَوَاللهِ، لَلدُّنْيَا أَهْوَنُ عَلَى اللَّهِ مِنْ هَذَا عَلَيْكُمْ."],"takhrij":"صحيح: رواه مسلم في الزهد (2957) عن عبدالله بن مسلمة بن قعنب، حدثنا سليمان –يعني ابن بلال-، عن جعفر، عن أبيه، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في حقارة الدنيا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2957).","chapter_en":"What Has Been Narrated Concerning the Insignificance of This World","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The Messenger of Allah ﷺ passed through the marketplace, entering from one of the elevated areas around Madinah, while the people were on both sides of him. He passed by a dead young goat with very small ears. He took hold of it by the ear and said: “Which of you would like this to belong to him for one dirham?” They replied: “We would not want it for anything. What would we do with it?” He asked: “Would you like it to be yours?” They replied: “By Allah, even if it were alive, its tiny ears would be a defect; so how about when it is dead?” He said: “By Allah, this world is more insignificant to Allah than this is to you.”"]},"buhuth":{"en":["The word “kanafatayhi” means on his two sides.","The word “jady” means a young goat.","The word “asakk” means having very small ears."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12468,12581],"tks":"صحيح: رواه مسلم (2957)."},{"num":15097,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، قَالَ كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذِي الْحُلَيْفَةِ فَإِذَا هُوَ بِشَاةٍ مَيِّتَةٍ شَائِلَةٍ بِرِجْلِهَا فَقَالَ أَتُرَوْنَ هَذِهِ هَيِّنَةً عَلَى صَاحِبِهَا فَوَالَّذِي نَفْسِي بِيَدِهِ لَلدُّنْيَا أَهْوَنُ عَلَى اللَّهِ مِنْ هَذِهِ عَلَى صَاحِبِهَا وَلَوْ كَانَتِ الدُّنْيَا تَزِنُ عِنْدَ اللَّهِ جَنَاحَ بَعُوضَةٍ مَا سَقَى كَافِرًا مِنْهَا قَطْرَةً أَبَدًا."],"takhrij":"حسن: رواه ابن ماجه (4110)، والحاكم (7847) كلاهما من طرق عن أبي يحيى زكريا بن منظور، قال: حدثنا أبو حازم، عن سهل بن سعد فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في حقارة الدنيا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (4110), al-Ḥākim (7847), and al-Tirmidhī (2320).","chapter_en":"What Has Been Narrated Concerning the Insignificance of This World","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Sahl ibn Saʿd narrated: We were with the Messenger of Allah ﷺ at Dhū al-Ḥulayfah when he came across a dead sheep with its leg raised. He said: “Do you think this is worthless to its owner? By the One in whose Hand is my soul, this world is more worthless to Allah than this is to its owner. If this world weighed as much as the wing of a mosquito with Allah, He would never give a disbeliever even a drop of it to drink.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13243],"tks":"حسن: رواه ابن ماجه (4110)، والحاكم (7847)، والترمذي (2320)."},{"num":15098,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، قَالَ: مَرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِدِمْنَةِ قَوْمٍ، فِيهَا سَخْلَةٌ مَيْتَةٌ، فَقَالَ: مَا لأَهْلِهَا فِيهَا حَاجَةٌ؟ قَالُوا: يَا رَسُولَ اللَّهِ، لَوْ كَانَ لأَهْلِهَا فِيهَا حَاجَةٌ مَا نَبَذُوهَا، فَقَالَ: وَاللَّهِ لَلدُّنْيَا أَهْوَنُ عَلَى اللَّهِ مِنْ هَذِهِ السَّخْلَةِ عَلَى أَهْلِهَا، فَلا أَلْفَيَنَّهَا أَهْلَكَتْ أَحَدًا مِنْكُمْ."],"takhrij":"صحيح: رواه البزار (4113) عن محمد بن عامر (هو الأنطاكي)، قال: نا الربيع (هو ابن نافع أبو توبة الحلبي)، حدثني محمد بن مهاجر، عن يونس بن حلبس، عن أبي إدريس عائذ الله، عن أبي الدرداء فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في حقارة الدنيا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzār (4113).","chapter_en":"What Has Been Narrated Concerning the Insignificance of This World","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abū al-Dardāʾ narrated: The Prophet ﷺ passed by a refuse heap belonging to some people in which there was a dead young sheep. He asked: “Do its owners have any need for it?” They replied: “O Prophet of Allah, if they had any need for it, they would not have thrown it away.” He said: “By Allah, this world is more insignificant to Allah than this young sheep is to its owners. So let me not find that it has destroyed any one of you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار (4113)."},{"num":15099,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم مَرَّ بِسَخْلَةٍ مَيِّتَةٍ، فَقَالَ لَهُمْ: تَرَوْنَ هَذِهِ هَانَتْ عَلَى أَهْلِهَا؟ قَالُوا: نَعَمْ يَا رَسُولَ اللَّهِ، فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَلدُّنْيَا أَهْوَنُ عَلَى اللَّهِ مِنْ هَذِهِ عَلَى أَهْلِهَا."],"takhrij":"حسن: رواه ابن أبي عاصم في الزهد (134)، والبزار (7200) كلاهما عن أبي كامل الجحدري الفضيل بن الحسين، أخبرنا القناد (وهو أبو إسماعيل)، أخبرنا قتادة، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في حقارة الدنيا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī ʿĀṣim in al-Zuhd (134) and al-Bazzār (7200).","chapter_en":"What Has Been Narrated Concerning the Insignificance of This World","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Mālik narrated: The Messenger of Allah ﷺ passed by a dead young sheep and said: “Do you think this has become worthless to its owners?” They replied: “Yes, O Messenger of Allah.” The Messenger of Allah ﷺ said: “By the One in whose Hand is the soul of Muḥammad, this world is more insignificant to Allah than this is to its owners.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في الزهد (134)، والبزار (7200)."},{"num":15100,"demo":false,"sanad":"","matn":["عَنِ الْمُسْتَوْرِدِ بْنِ شَدَّادٍ، قَالَ: كُنْتُ فِي رَكْبٍ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ مَرَّ بِسَخْلَةٍ مَيْتَةٍ مَنْبُوذَةٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَتَرَوْنَ هَذِهِ هَانَتْ عَلَى أَهْلِهَا؟ فَقَالُوا: يَا رَسُولَ اللَّهِ مِنْ هَوَانِهَا أَلْقَوْهَا، قَالَ: فَوَالَّذِي نَفْسُ مُحَمِّدٍ بِيَدِهِ لَلدُّنْيَا أَهْوَنُ عَلَى اللَّهِ مِنْ هَذِهِ عَلَى أَهْلِهَا."],"takhrij":"حسن: رواه الترمذي (2321)، وابن ماجه (4111)، وأحمد (18013) كلهم من طريق (حماد بن زيد وابن المبارك)، عن مجالد بن سعيد الهمداني، عن قيس بن أبي حازم الهمداني، عن المستورد بن شداد فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في حقارة الدنيا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2321), Ibn Mājah (4111), and Aḥmad (18013).","chapter_en":"What Has Been Narrated Concerning the Insignificance of This World","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Al-Mustawrid ibn Shaddād narrated: I was traveling in a group with the Messenger of Allah ﷺ when he passed by a dead young sheep that had been thrown away. The Messenger of Allah ﷺ said: “Do you think this has become worthless to its owners?” They replied: “O Messenger of Allah, it was because of how worthless it was to them that they threw it away.” He said: “By the One in whose Hand is the soul of Muḥammad, this world is more insignificant to Allah than this is to its owners.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2321)، وابن ماجه (4111)، وأحمد (18013)."},{"num":15101,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ أَلاَ إِنَّ الدُّنْيَا مَلْعُونَةٌ مَلْعُونٌ مَا فِيهَا إِلاَّ ذِكْرَ اللَّهِ وَمَا وَالاَهُ وَعَالِمًا أَوْ مُتَعَلِّمًا."],"takhrij":"حسن: رواه الترمذي (2322)، وابن ماجه (4112) كلاهما من طريق عبدالرحمن بن ثابت بن ثوبان، قال: سمعت عطاء بن قرّة، قال: سمعت عبدالله بن ضمرة السّلولي، قال: حدثنا أبو هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في حقارة الدنيا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2322) and Ibn Mājah (4112).","chapter_en":"What Has Been Narrated Concerning the Insignificance of This World","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Messenger of Allah ﷺ say: “The world is accursed, and what is in it is accursed, except the remembrance of Allah and whatever is connected to it, or a scholar, or a student of knowledge.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2322)، وابن ماجه (4112)."},{"num":15102,"demo":false,"sanad":"","matn":["عن الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ الكندي قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مَلَأَ ابْنُ آدَمَ وِعَاءً شَرًّا مِنْ بَطْنٍ، حَسْبُ ابْنِ آدَمَ أُكُلَاتٌ يُقِمْنَ صُلْبَهُ، فَإِنْ كَانَ لَا مَحَالَةَ، فَثُلُثُ طَعَامٍ، وَثُلُثُ شَرَابٍ، وَثُلُثٌ لِنَفْسِهِ."],"takhrij":"صحيح: رواه الترمذي (2380)، وأحمد (17186)، وصحّحه ابن حبان (5236)، والحاكم (7945) كلهم من طرق عن يحيى بن جابر الطائي، قال: سمعت المقدام بن معدي كرب الكندي فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في حقارة الدنيا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2380), Aḥmad (17186), authenticated by Ibn Ḥibbān (5236), and al-Ḥākim (7945).","chapter_en":"What Has Been Narrated Concerning the Insignificance of This World","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Al-Miqdām ibn Maʿdīkarib al-Kindī narrated: I heard the Messenger of Allah ﷺ say: “The son of Ādam fills no vessel worse than his stomach. It is sufficient for the son of Ādam to eat a few mouthfuls that keep his back upright. But if he must do more than that, then one-third for his food, one-third for his drink, and one-third for his breathing.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2380)، وأحمد (17186)، وصححه ابن حبان (5236)، والحاكم (7945)."},{"num":15103,"demo":false,"sanad":"","matn":["عَنْ أُبَيِّ بْنِ كَعْبٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ مَطْعَمَ ابْنِ آدَمَ جُعِلَ مَثَلًا لِلدُّنْيَا، وَإِنْ قَزَّحَهُ، وَمَلَّحَهُ فَانْظُرُوا إِلَى مَا يَصِيرُ."],"takhrij":"حسن: رواه عبد الله بن أحمد في زوائد مسند أبيه (21239)، وابن أبي عاصم في الزهد (205)، وصحّحه ابن حبان (702) كلهم من طريق أبي حذيفة موسى بن مسعود، حدثنا سفيان، عن يونس بن عبيد، عن الحسن، عن عُتي –هو ابن ضمرة- عن أبي بن كعب فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في حقارة الدنيا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by ʿAbdullāh ibn Aḥmad in Zawāʾid Musnad Abīhi (21239) and Ibn Abī ʿĀṣim in al-Zuhd (205), and authenticated by Ibn Ḥibbān (702).","chapter_en":"What Has Been Narrated Concerning the Insignificance of This World","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Ubayy ibn Kaʿb narrated that the Messenger of Allah ﷺ said: “The food of the son of Ādam has been made an example of this world. Even if he seasons it and salts it, look at what it ultimately becomes.”"]},"buhuth":{"en":["The phrase “even if he seasons it” means that he improves it with spices.","The phrase “and salts it” means that he adds an appropriate amount of salt."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عبد الله بن أحمد في زوائد مسند أبيه (21239)، وابن أبي عاصم في الزهد (205)، وصححه ابن حبان (702)."},{"num":15104,"demo":false,"sanad":"","matn":["عن عَامِرِ بن سَعْدٍ قَالَ:  كَانَ سَعْدُ بْنُ أَبِي وَقَّاصٍ فِي إِبِلِهِ، فَجَاءَهُ ابْنُهُ عُمَرُ فَلَمَّا رَآهُ سَعْدٌ قَالَ: أَعُوذُ بِاللهِ مِنْ شَرِّ هَذَا الرَّاكِبِ، فَنَزَلَ فَقَالَ لَهُ: أَنَزَلْتَ فِي إِبِلِكَ وَغَنَمِكَ وَتَرَكْتَ النَّاسَ يَتَنَازَعُونَ الْمُلْكَ بَيْنَهُمْ؟ فَضَرَبَ سَعْدٌ فِي صَدْرِهِ فَقَالَ: اسْكُتْ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ يُحِبُّ الْعَبْدَ التَّقِيَّ الْغَنِيَّ الْخَفِيَّ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (2956) من طرق عن أبي بكر الحنفي قال: حدثنا بكير بن مسمار، حدثني عامر بن سعد فذكره.","grade":"صحيح","chapter_ar":"باب فضل العبد التقي الغني الخفي","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2965).","chapter_en":"The Virtue of the God-Fearing, Self-Sufficient, Unnoticed Servant","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["ʿĀmir ibn Saʿd narrated: Saʿd ibn Abī Waqqāṣ was staying among his camels when his son ʿUmar came to him. When Saʿd saw him, he said: “I seek refuge in Allah from the evil of this rider.” His son dismounted and said: “You have withdrawn among your camels and sheep while people are disputing over rule and authority?” Saʿd struck him on the chest and said: “Be quiet. I heard the Messenger of Allah ﷺ say: ‘Indeed, Allah loves the servant who is God-fearing, self-sufficient, and hidden from public attention.’”"]}},"tuhfa":{},"full":1,"rep":[9959],"tks":"صحيح: رواه مسلم (2956)."},{"num":15105,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ بَيْنَ أَيْدِيكُمْ عَقَبَةً كؤوداً لا يَنْجُو فِيهَا إِلا كُلَّ مخفّ."],"takhrij":"حسن: رواه البزار (4118)، وصحّحه الحاكم (4/618) كلاهما من طريق أسد بن موسى، حدثنا أبو معاوية، عن موسى الصغير، عن هلال بن يساف، عن أم الدرداء، عن أبي الدرداء قال: فذكره.","grade":"حسن","chapter_ar":"باب فضل العبد التقي الغني الخفي","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (4118) and authenticated by al-Ḥākim (4/618).","chapter_en":"The Virtue of the God-Fearing, Self-Sufficient, Unnoticed Servant","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Abū al-Dardāʾ narrated that the Messenger of Allah ﷺ said: “Ahead of you is an arduous ascent, and none will be saved upon it except those who travel lightly burdened.”"]},"buhuth":{"en":["The expression “an arduous ascent” means a difficult and demanding passage.","The expression “one who is lightly burdened” refers to a person who carries little weight. Here, it means one who is lightly burdened with sins and with the attachments and causes of worldly life."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (4118)، وصححه الحاكم (4/618)."},{"num":15106,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ قِيلَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَىُّ النَّاسِ أَفْضَلُ قَالَ كُلُّ مَخْمُومِ الْقَلْبِ صَدُوقِ اللِّسَانِ. قَالُوا صَدُوقُ اللِّسَانِ نَعْرِفُهُ فَمَا مَخْمُومُ الْقَلْبِ قَالَ هُوَ التَّقِيُّ النَّقِيُّ لاَ إِثْمَ فِيهِ وَلاَ بَغْىَ وَلاَ غِلَّ وَلاَ حَسَدَ."],"takhrij":"صحيح: رواه ابن ماجه (4216)، والخرائطي في مكارم الأخلاق (45)، والطبراني في مسند الشاميين (1218) كلهم من طريق زيد بن واقد، حدثنا مغيث بن سميّ، عن عبدالله بن عمرو قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب فضل العبد التقي الغني الخفي","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (4216), al-Kharāʾiṭī in Makārim al-Akhlāq (45), and al-Ṭabarānī in Musnad al-Shāmiyyīn (1218).","chapter_en":"The Virtue of the God-Fearing, Self-Sufficient, Unnoticed Servant","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated: The Messenger of Allah ﷺ was asked: “Which people are best?” He replied: “Everyone whose heart is makhmūm and whose tongue is truthful.” They said: “We know what a truthful tongue is, but what is a makhmūm heart?” He replied: “It is the God-fearing, pure heart in which there is no sin, transgression, rancor, or envy.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (4216)، والخرائطي في مكارم الأخلاق (45)، والطبراني في مسند الشاميين (1218)."},{"num":15107,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَلِجُ النَّارَ أَحَدٌ بَكَى مِنْ خَشْيَةِ اللَّهِ، حَتَّى يَعُودَ اللَّبَنُ فِي الضَّرْعِ، وَلَا يَجْتَمِعُ غُبَارٌ فِي سَبِيلِ اللَّهِ، وَدُخَانُ جَهَنَّمَ فِي مَنْخِرَيْ امْرِئٍ أَبَدًا."],"takhrij":"صحيح: رواه أحمد (10560) –واللفظ له- عن يزيد (هو ابن هارون) وأبي عبدالرحمن المقرئ- والترمذي (1633)، والنسائي (3108) من طريق ابن المبارك- والحاكم (7667) من طريق جعفر بن عون- كلهم عن عبد الرحمن بن عبد الله المسعودي، عن محمد بن عبد الرحمن مولى آل طلحة، عن عيسى بن طلحة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب فضل البكاء من خشية اللّٰه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (10560), and this is his wording, al-Tirmidhī (1633), al-Nasā’ī (3108), and al-Ḥākim (7667).","chapter_en":"The Virtue of Weeping from Fear of Allah","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “No one who weeps out of fear of Allah, Mighty and Majestic, will enter the Fire until milk returns to the udder. And the dust gathered in the path of Allah and the smoke of Hell will never come together in a person’s nostrils.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7761],"tks":"صحيح: رواه أحمد (10560) - واللفظ له -، والترمذي (1633)، والنسائي (3108)، والحاكم (7667)."},{"num":15108,"demo":false,"sanad":"","matn":["عَنْ عُتْبَةَ بْنِ عَبْدٍ، قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَوْ أَنَّ رَجُلًا يَخِرُّ عَلَى وَجْهِهِ، مِنْ يَوْمِ وُلِدَ إِلَى يَوْمِ يَمُوتُ، هَرَمًا فِي مَرْضَاةِ اللهِ، لَحَقَّرَهُ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه أحمد (17649)، وأبو نعيم في الحلية (307)، والبيهقي في الشعب (767) كلهم من طرق عن بقية بن الوليد، حدثني بحير بن سعد، عن خالد بن معدان، عن عُتبة بن عبد قال: فذكره.","grade":"حسن","chapter_ar":"باب احتقار العبد عمله يوم القيامة","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17649), Abū Nuʿaym in Ḥilyat al-Awliyāʾ (2/15), and al-Bayhaqī in Shuʿab al-Īmān (767).","chapter_en":"The Servant Regarding His Deeds as Insignificant on the Day of Resurrection","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["ʿUtbah ibn ʿAbd narrated that the Messenger of Allah ﷺ said: “If a man were to drag himself upon his face from the day he was born until the day he died of old age, seeking the pleasure of Allah, Mighty and Majestic, he would still regard that deed as insignificant on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13722],"tks":"حسن: رواه أحمد (17649)، وأبو نعيم في الحلية (307)، والبيهقي في الشعب (767)."},{"num":15109,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكْثِرُوا ذِكْرَ هَاذِمِ اللَّذَّاتِ. يَعْنِي الْمَوْتَ."],"takhrij":"حسن: رواه الترمذي (2307)، والنسائي (1824)، وابن ماجه (4258)، وأحمد (7925)، وابن حبان (2992)، والحاكم (7909)، كلهم من طرق عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ذكر الموت","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2307), al-Nasā’ī (1824), Ibn Mājah (4258), Aḥmad (7925), Ibn Ḥibbān (2992), and al-Ḥākim (7909).","chapter_en":"What Has Been Narrated Concerning Remembering Death","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Frequently remember the destroyer of pleasures.” Meaning: death."]},"buhuth":{"en":["The expression “destroyer of pleasures” means that which cuts pleasures off.","It has also been narrated with the letter dāl, from the verb meaning “to demolish,” as a building is demolished.","What is intended is death."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3522],"tks":"حسن: رواه الترمذي (2307)، والنسائي (1824)، وابن ماجه (4258)، وأحمد (7925)، وابن حبان (2992)، والحاكم (7909)."},{"num":15110,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: مَرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَوْمٍ مِنَ الْأَنْصَارِ يَضْحَكُونَ، فَقَالَ:  أَكْثِرُوا ذِكْرَ هادمِ اللَّذَّاتِ."],"takhrij":"حسن: رواه البزار كشف الأستار (3623)، والطبراني في الأوسط (695) كلاهما من طريق مؤمل بن إسماعيل قال: حدثنا حماد بن سلمة، عن ثابت البناني، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ذكر الموت","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār, as cited in Kashf al-Astār (3623), and al-Ṭabarānī in al-Muʿjam al-Awsaṭ (695).","chapter_en":"What Has Been Narrated Concerning Remembering Death","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Anas ibn Mālik narrated: The Prophet ﷺ passed by a group of the Anṣār who were laughing and said: “Frequently remember the destroyer of pleasures.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3523],"tks":"حسن: رواه البزار في كشف الأستار (3623)، والطبراني في الأوسط (695)."},{"num":15111,"demo":false,"sanad":"","matn":["عَنْ هَانِئٍ، - مَوْلَى عُثْمَانَ - قَالَ: كَانَ عُثْمَانُ بْنُ عَفَّانَ إِذَا وَقَفَ عَلَى قَبْرٍ يَبْكِي حَتَّى يَبُلَّ لِحْيَتَهُ فَقِيلَ لَهُ: تَذْكُرُ الْجَنَّةَ وَالنَّارَ وَلاَ تَبْكِي وَتَبْكِي مِنْ هَذَا قَالَ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْقَبْرَ أَوَّلُ مَنَازِلِ الآخِرَةِ فَإِنْ نَجَا مِنْهُ فَمَا بَعْدَهُ أَيْسَرُ مِنْهُ وَإِنْ لَمْ يَنْجُ مِنْهُ، فَمَا بَعْدَهُ أَشَدُّ مِنْهُ. قَالَ وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا رَأَيْتُ مَنْظَرًا قَطُّ إِلاَّ وَالْقَبْرُ أَفْظَعُ مِنْهُ."],"takhrij":"حسن: رواه الترمذي (2308)، وابن ماجه (4267) كلاهما من حديث يحيى بن معين، حدثنا هشام بن يوسف، عن عبدالله بن بَحير، عن هانئ مولى عثمان فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ذكر الموت","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2308) and Ibn Mājah (4267).","chapter_en":"What Has Been Narrated Concerning Remembering Death","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Hāniʾ, the freedman of ʿUthmān, narrated: Whenever ʿUthmān ibn ʿAffān stood by a grave, he would weep until his beard became wet. It was said to him: “You remember Paradise and Hell and do not weep, yet you weep because of this?” He replied: The Messenger of Allah ﷺ said: “The grave is the first stage of the Hereafter. If a person is saved from it, what comes after it will be easier. If he is not saved from it, what comes after it will be more severe.” He also said that the Messenger of Allah ﷺ said: “I have never seen any sight except that the grave is more terrifying than it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3824],"tks":"حسن: رواه الترمذي (2308)، وابن ماجه (4267)."},{"num":15112,"demo":false,"sanad":"","matn":["عَن الْبَرَاءِ بْنِ عَازِبٍ قَالَ: بَيْنَمَا نَحْنُ مَعَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذْ بَصُرَ بِجَمَاعَةٍ فَقَالَ: عَلَامَ اجْتَمَعَ عَلَيْهِ هَؤُلَاءِ؟ قِيلَ: عَلَى قَبْرٍ يَحْفِرُونَهُ. قَـــــالَ: فَفَزِعَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَدَرَ بَيْنَ يَدَيْ أَصْحَابِهِ مُسْرِعًا، حَتَّى انْتَهَى إِلَى الْقَبْرِ، فَجَثَا عَلَيْهِ، قَالَ: فَاسْتَقْبَلْتُهُ مِنْ بَيْنِ يَدَيْهِ لِأَنْظُرَ مَا يَصْنَعُ، فَبَكَى حَتَّى بَلَّ الثَّرَى مِنْ دُمُوعِهِ، ثُمَّ أَقْبَلَ عَلَيْنَا، قَالَ: أَيْ إِخْوَانِي لِمِثْلِ الْيَوْمِ فَأَعِدُّوا."],"takhrij":"حسن: رواه الإمام أحمد (18601) واللفظ له، وابن ماجه (4195)، وابنُ أبي شيبة (35472) كلهم من طرق عن أبي رجاء عبدالله بن واقد الهروي الخراساني، حدثنا محمد بن مالك، عن البراء بن عازب قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ذكر الموت","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (18601), and this is his wording, Ibn Mājah (4195), and Ibn Abī Shaybah (35472).","chapter_en":"What Has Been Narrated Concerning Remembering Death","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib narrated: While we were with the Messenger of Allah ﷺ, he noticed a group of people and asked: “Why have these people gathered?” It was said: “They are gathered around a grave they are digging.” The Messenger of Allah ﷺ became deeply alarmed and hurried ahead of his Companions until he reached the grave. He knelt beside it. I moved around in front of him so that I could see what he was doing. He wept until his tears wet the earth. Then he turned toward us and said: “O my brothers, prepare yourselves for a day like this.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (18601) واللفظ له، وابن ماجه (4195)، وابن أبي شيبة (35472)."},{"num":15113,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا أَبَا هُرَيْرَةَ كُنْ وَرِعًا تَكُنْ أَعْبَدَ النَّاسِ وَكُنْ قَنِعًا تَكُنْ أَشْكَرَ النَّاسِ وَأَحِبَّ لِلنَّاسِ مَا تُحِبُّ لِنَفْسِكَ تَكُنْ مُؤْمِنًا وَأَحَسِنْ جِوَارَ مَنْ جَاوَرَكَ تَكُنْ مُسْلِمًا وَأَقِلَّ الضَّحِكَ فَإِنَّ كَثْرَةَ الضَّحِكِ تُمِيتُ الْقَلْبَ."],"takhrij":"حسن: رواه ابن ماجه (4217) –واللفظ له- والبخاري في الأدب المفرد (252)، والبيهقي في الزهد (822) كلهم من طرق عن أبي رجاء، عن بُرد بن سنان، عن مكحول، عن واثلة بن الأسقع، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خصال الخير","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (4217), and this is his wording, al-Bukhārī in al-Adab al-Mufrad (252), and al-Bayhaqī in al-Zuhd (822).","chapter_en":"What Has Been Narrated Concerning Virtuous Qualities","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “O Abū Hurayrah, be scrupulous, and you will be the most devout of people. Be content, and you will be the most grateful of people. Love for people what you love for yourself, and you will be a believer. Treat your neighbor well, and you will be a Muslim. And laugh little, for excessive laughter deadens the heart.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (4217) - واللفظ له -، والبخاري في الأدب المفرد (252)، والبيهقي في الزهد (822)."},{"num":15114,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تُكْثِرُوا الضَّحِكَ فَإِنَّ كَثْرَةَ الضَّحِكِ تُمِيتُ الْقَلْبَ."],"takhrij":"حسن: رواه ابن ماجه (4193) - واللفظ له -، والبخاري في الأدب المفرد (253)كلاهما من طريق أبي بكر الحنفي (واسمه عبدالكبير بن عبدالمجيد البصري)، حدثنا عبدالحميد بن جعفر، عن إبراهيم بن عبدالله بن حُنين، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خصال الخير","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (4193), and this is his wording, and al-Bukhārī in al-Adab al-Mufrad (253).","chapter_en":"What Has Been Narrated Concerning Virtuous Qualities","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Do not laugh excessively, for excessive laughter deadens the heart.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15022],"tks":"حسن: رواه ابن ماجه (4193) - واللفظ له -، والبخاري في الأدب المفرد (253)."},{"num":15115,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، قَالَ: لَقِيتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِي: يَا عُقْبَةُ بْنَ عَامِرٍ، صِلْ مَنْ قَطَعَكَ، وَأَعْطِ مَنْ حَرَمَكَ، وَاعْفُ عَمَّنْ ظَلَمَكَ قَالَ: ثُمَّ أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِي: يَا عُقْبَةُ بْنَ عَامِرٍ، أَمْلِكْ لِسَانَكَ، وَابْكِ عَلَى خَطِيئَتِكَ، وَلْيَسَعْكَ بَيْتُكَ قَالَ: ثُمَّ لَقِيتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِي: يَا عُقْبَةُ بْنَ عَامِرٍ، أَلَا أُعَلِّمُكَ سُوَرًا مَا أُنْزِلَتْ فِي التَّوْرَاةِ وَلَا فِي الزَّبُورِ وَلَا فِي الْإِنْجِيلِ وَلَا فِي الْفُرْقَانِ مِثْلُهُنَّ، لَا يَأْتِيَنَّ عَلَيْكَ لَيْلَةٌ إِلَّا قَرَأْتَهُنَّ فِيهَا: قُلْ هُوَ اللَّهُ ﴿أَحَدٌ وَقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ﴾ وَقُلْ أَعُوذُ بِرَبِّ النَّاسِ قَالَ عُقْبَةُ: فَمَا أَتَتْ عَلَيَّ لَيْلَةٌ إِلَّا قَرَأْتُهُنَّ فِيهَا، وَحُقَّ لِي أَنْ لَا أَدَعَهُنَّ وَقَدْ أَمَرَنِي بِهِنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه أحمد (17452) عن حسين بن محمد، حدثنا ابن عياش (هو إسماعيل)، عن أسيد بن عبدالرحمن الخثعمي (الرملي)، عن فروة بن مجاهد اللخمي، عن عقبة بن عامر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خصال الخير","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17452).","chapter_en":"What Has Been Narrated Concerning Virtuous Qualities","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir narrated: I met the Messenger of Allah ﷺ and he said to me: “O ʿUqbah ibn ʿĀmir, maintain ties with the one who cuts you off, give to the one who deprives you, and pardon the one who wrongs you.” Then I came to the Messenger of Allah ﷺ again, and he said: “O ʿUqbah ibn ʿĀmir, control your tongue, weep over your sin, and let your home be sufficient for you.” Then I met the Messenger of Allah ﷺ again, and he said: “O ʿUqbah ibn ʿĀmir, shall I teach you sūrahs the like of which were not revealed in the Torah, the Psalms, the Gospel, or the Furqān? Let no night pass over you without reciting them: ‘Say: He is Allah, One,’ ‘Say: I seek refuge in the Lord of daybreak,’ and ‘Say: I seek refuge in the Lord of mankind.’” ʿUqbah said: “Thereafter, no night passed over me except that I recited them. It was only right that I should never abandon them after the Messenger of Allah ﷺ had instructed me to recite them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17452)."},{"num":15116,"demo":false,"sanad":"","matn":["عن أنس قال: قال لي رسول الله صلى الله عليه وسلم: اعمل لله رأي العين كأنك تراه، فإنك إن لم تكن تراه فإنه يراك، وأسبغ طهورك إذا دخلت المسجد، واذكر الموت في صلاتك، فإن الرجل يذكر الموت في صلاته لحريٌّ أن يحسن صلاته، وصلّ صلاة رجل لا يظن أن يصلي صلاة غيرها، وإياك وكلْ ما يعتذر منه."],"takhrij":"حسن: رواه البيهقي في الزهد الكبير (527)، والديلمي في مسند الفردوس كما ذكره السخاوي في مقاصد الحسنة (ص144 رقم275)، والضياء المقدسي في المختارة (2199) كلهم من طريق أبي عاصم الضحاك بن مخلد، حدثنا شبيب بن بشر، حدثنا أنس بن مالك فذكره إلا أن المقدسي اقتصر على الجزء الأخير منه.","grade":"حسن","chapter_ar":"باب ما جاء في خصال الخير","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqī in al-Zuhd al-Kabīr (527), al-Daylamī in Musnad al-Firdaws as cited by al-Sakhāwī in al-Maqāṣid al-Ḥasanah (p. 144, no. 275), and al-Ḍiyāʾ al-Maqdisī in al-Mukhtārah (2199).","chapter_en":"What Has Been Narrated Concerning Virtuous Qualities","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Anas narrated: The Messenger of Allah ﷺ said to me: “Act for Allah with the certainty of one who sees Him, as though you see Him; for even though you do not see Him, He sees you. Perfect your purification when you enter the mosque. Remember death during your prayer, for a man who remembers death in his prayer is more likely to perform his prayer well. Pray the prayer of a man who does not expect to pray another prayer after it, and beware of everything for which you would later need to apologize.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي في الزهد الكبير (527)، والديلمي في مسند الفردوس كما ذكره السخاوي في المقاصد الحسنة (ص 144، رقم 275)، والضياء المقدسي في المختارة (2199)."},{"num":15117,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ، وَأَبِي الدَّهْمَاءِ، قَالَا: أَتَيْنَا عَلَى رَجُلٍ مِنْ أَهْلِ الْبَادِيَةِ فَقُلْنَا: هَلْ سَمِعْتَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا؟ قَالَ: نَعَمْ، سَمِعْتُهُ يَقُولُ: إِنَّكَ لَنْ تَدَعَ شَيْئًا لِلَّهِ إِلَّا بَدَّلَكَ اللهُ بِهِ مَا هُوَ خَيْرٌ لَكَ مِنْهُ."],"takhrij":"صحيح: رواه وكيع بن الجراح في الزهد (356) – وعنه أحمد (23074)، وهنّاد بن السري في الزهد (938) – عن سليمان بن المغيرة، عن حميد بن هلال العدوي، عن أبي قتادة وأبي الدهماء قالا: فذكراه. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في خصال الخير","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Wakīʿ ibn al-Jarrāḥ in al-Zuhd (356), and through him by Aḥmad (23074), and by Hannād in al-Zuhd (938).","chapter_en":"What Has Been Narrated Concerning Virtuous Qualities","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Abū Qatādah and Abū al-Dahmāʾ narrated: We came across a man from the desert and asked him: “Did you hear anything from the Messenger of Allah ﷺ?” He replied: “Yes. I heard him say: ‘You will never leave something for the sake of Allah except that Allah will replace it for you with something better than it.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه وكيع بن الجراح في الزهد (356)، وعنه أحمد (23074)، وهناد في الزهد (938)."},{"num":15118,"demo":false,"sanad":"","matn":["عَنْ عباد بن الْوَلِيدِ بن عُبَادَةَ بْنِ الصَّامِتِ قَالَ: خَرَجْتُ أَنَا وَأَبِي نَطْلُبُ الْعِلْمَ فِي هَذَا الْحَيِّ مِنَ الْأَنْصَارِ، قَبْلَ أَنْ يَهْلِكُوا، فَكَانَ أَوَّلُ مَنْ لَقِينَا أَبَا الْيَسَرِ، صَاحِبَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَمَعَهُ غُلَامٌ لَهُ، مَعَهُ ضِمَامَةٌ مِنْ صُحُفٍ، وَعَلَى أَبِي الْيَسَرِ بُرْدَةٌ ومَعَافريّ، وَعَلَى غُلَامِهِ بُرْدَةٌ ومَعَافريّ، فَقَالَ لَهُ أَبِي: يَا عَمِّ! إِنِّي أَرَى فِي وَجْهِكَ سَفْعَةً مِنْ غَضَبٍ، قَالَ: أَجَلْ، كَانَ لِي عَلَى فُلَانِ بْنِ فُلَانٍ الْحَرَامِيِّ مَالٌ، فَأَتَيْتُ أَهْلَهُ فَسَلَّمْتُ، فَقُلْتُ: ثمّ هُوَ؟ قَالُوا: لَا، فَخَرَجَ عليّ ابْنٌ لَهُ جَفْر، فَقُلْتُ لَهُ: أَيْنَ أَبُوكَ؟ قَالَ: سَمِعَ صَوْتَكَ فَدَخَلَ أَرِيكَةَ أمّي، فَقُلْتُ: اخْرُجْ إليّ، فَقَدْ عَلِمْتُ أَيْنَ أَنْتَ، فَخَرَجَ فَقُلْتُ: مَا حَمَلَكَ عَلَى أَنِ اخْتَبَأْتَ مِنِّي؟ قَالَ: أَنَا وَاللهِ أُحَدِّثُكَ ثُمَّ لَا أكذِبُك، خَشِيتُ وَاللهِ أَنْ أُحَدِّثَكَ فَأَكْذِبَكَ، وَأَنْ أَعِدَكَ فَأُخْلِفَكَ، وَكُنْتَ صَاحِبَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَكُنْتُ وَاللهِ مُعْسِرًا، قَالَ: قُلْتُ: اللَّهُ! قَالَ: اللَّهُ. قُلْتُ: اللَّهُ! قَالَ: اللَّهُ. قُلْتُ: اللَّهُ! قَالَ: اللَّهُ. قَالَ: فَأَتَى بِصَحِيفَتِهِ فَمَحَاهَا بِيَدِهِ، فَقَالَ: إِنْ وَجَدْتَ قَضَاءً فَاقْضِنِي، وَإِلَّا أَنْتَ فِي حلٍّ، فَأَشْهَدُ بصرُ عينيَّ هَاتَيْنِ (وَوَضَعَ إِصْبَعَيْهِ عَلَى عَيْنَيْهِ)، وسمْعُ أذُنيَّ هَاتَيْنِ، وَوَعَاهُ قَلْبِي هَذَا (وَأَشَارَ إِلَى مَنَاطِ قَلْبِهِ) رَسُولَ اللـّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَقُولُ: مَنْ أَنْظَرَ مُعْسِرًا، أَوْ وضَعَ عَنْهُ، أظلَّه اللَّهُ فِي ظلِّه.","قَالَ: فَقُلْتُ لَهُ أَنَا: يَا عَمِّ! لَوْ أَنَّكَ أَخَذْتَ بُرْدَةَ غُلَامِكَ وَأَعْطَيْتَهُ مَعَافِرِيَّكَ، وَأَخَذْتَ مَعَافِرِيَّهُ وَأَعْطَيْتَهُ بُرْدَتَكَ، فَكَانَتْ عَلَيْكَ حُلَّةٌ وَعَلَيْهِ حُلَّةٌ، فَمَسَحَ رَأْسِي وَقَالَ: اللَّهُمَّ بَارِكْ فِيهِ. يَا ابْنَ أَخِي! بَصَرُ عَيْنَيَّ هَاتَيْنِ، وَسَمْعُ أُذُنَيَّ هَاتَيْنِ، وَوَعَاهُ قَلْبِي هَذَا (وَأَشَارَ إِلَى مَنَاطِ قَلْبِهِ)، رَسُولَ اللهِ صلى الله عليه وسلم وَهُوَ يَقُولُ: أَطْعِمُوهُمْ مِمَّا تَأْكُلُونَ، وَأَلْبِسُوهُمْ مِمَّا تَلْبَسُونَ وَكَانَ أَنْ أَعْطَيْتُهُ مِنْ مَتَاعِ الدُّنْيَا أَهْوَنَ عَلَيَّ مِنْ أَنْ يَأْخُذَ مِنْ حَسَنَاتِي يَوْمَ الْقِيَامَةِ. ثُمَّ مَضَيْنَا حَتَّى أَتَيْنَا جَابِرَ بْنَ عَبْدِ اللهِ فِي مَسْجِدِهِ، وَهُوَ يُصَلِّي فِي ثَوْبٍ وَاحِدٍ مُشْتَمِلًا بِهِ، فَتَخَطَّيْتُ الْقَوْمَ حَتَّى جَلَسْتُ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ، فَقُلْتُ: يَرْحَمُكَ اللهُ! أَتُصَلِّي فِي ثَوْبٍ وَاحِدٍ وَرِدَاؤُكَ إِلَى جَنْبِكَ؟ قَالَ: فَقَالَ بِيَدِهِ فِي صَدْرِي هَكَذَا، وَفَرَّقَ بَيْنَ أَصَابِعِهِ وَقَوَّسَهَا: أَرَدْتُ أَنْ يَدْخُلَ عَلَيَّ الْأَحْمَقُ مِثْلُكَ، فَيَرَانِي كَيْفَ أَصْنَعُ، فَيَصْنَعُ مِثْلَهُ.","أَتَانَا رَسُولُ اللهِ صلى الله عليه وسلم فِي مَسْجِدِنَا هَذَا، وَفِي يَدِهِ عُرْجُونُ ابْنِ طَابٍ، فَرَأَى فِي قِبْلَةِ الْمَسْجِدِ نُخَامَةً فَحَكَّهَا بِالْعُرْجُونِ، ثُمَّ أَقْبَلَ عَلَيْنَا فَقَالَ: أَيُّكُمْ يُحِبُّ أَنْ يُعْرِضَ اللهُ عَنْهُ؟ قَالَ: فَخَشَعْنَا، ثُمَّ قَالَ: أَيُّكُمْ يُحِبُّ أَنْ يُعْرِضَ اللهُ عَنْهُ؟ قَالَ: فَخَشَعْنَا، ثُمَّ قَالَ: أَيُّكُمْ يُحِبُّ أَنْ يُعْرِضَ اللهُ عَنْهُ؟ قُلْنَا: لَا أَيُّنَا يَا رَسُولَ اللهِ! قَالَ: فَإِنَّ أَحَدَكُمْ إِذَا قَامَ يُصَلِّي، فَإِنَّ اللهَ تبارك وتعالى قِبَلَ وَجْهِهِ، فَلَا يَبْصُقَنَّ قِبَلَ وَجْهِهِ، وَلَا عَنْ يَمِينِهِ، وَلْيَبْصُقْ عَنْ يَسَارِهِ تَحْتَ رِجْلِهِ الْيُسْرَى، فَإِنْ عَجِلَتْ بِهِ بَادِرَةٌ، فَلْيَقُلْ بِثَوْبِهِ هَكَذَا ثُمَّ طَوَى ثَوْبَهُ بَعْضَهُ عَلَى بَعْضٍ فَقَالَ: أَرُونِي عَبِيرًا فَقَامَ فَتًى مِنَ الْحَيِّ يَشْتَدُّ إِلَى أَهْلِهِ، فَجَاءَ بِخَلُوقٍ فِي رَاحَتِهِ، فَأَخَذَهُ رَسُولُ اللهصلى الله عليه وسلم فَجَعَلَهُ عَلَى رَأْسِ الْعُرْجُونِ، ثُمَّ لَطَخَ بِهِ عَلَى أَثَرِ النُّخَامَةِ. فَقَالَ جَابِرٌ: فَمِنْ هُنَاكَ جَعَلْتُمُ الْخَلُوقَ فِي مَسَاجِدِكُمْ.","سِرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ بَطْنِ بُوَاطٍ، وَهُوَ يَطْلُبُ الْمَجْدِيَّ بْنَ عَمْرٍو الْجُهَنِيَّ، وَكَانَ النَّاضِحُ يَعْقُبُهُ مِنَّا الْخَمْسَةُ وَالسِّتَّةُ وَالسَّبْعَةَ، فَدَارَتْ عُقْبَةُ رَجُلٍ مِنْ الأنصارعلى نَاضِحٍ لَهُ، فَأَنَاخَهُ فَرَكِبَهُ، ثُمَّ بَعَثَهُ فَتَلِدْنَ عَلَيْهِ بَعْضُ التَّلَدَنِ، فَقَالَ لَهُ: شَأْ، لَعَنَكَ اللَّهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ هَذَا اللاَعِنِ بَعِيرُهُ؟ قَالَ: أَنَا يَا رَسُولَ اللَّهِ، قَالَ: انْزِلْ عَنْهُ، فَلاَ تَصْحَبْنَا بِمَلْعُونٍ، لا تَدْعُوا عَلَى أَنْفُسِكُمْ، وَلا تَدْعُوا عَلَى أَوْلاَدِكُمْ، وَلا تَدْعُوا عَلَى أَمْوَالِكُمْ، لاَ تُوَافِقُوا مِنَ اللَّهِ سَاعَةً يَسْأَلُ فِيهَا عَطَاءً، فَيَسْتَجِيبُ لَكُمْ.","سِرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى إِذَا كَانَتْ عُشيْشِيَة وَدَنَوْنَا مَاءً مِنْ مِيَاهِ الْعَرَبِ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مِنْ رَجُلٍ يَتَقَدَّمُنَا فَيَمْدُرُ الْحَوْضَ فيشرب وَيَسْقِينَا؟ قَالَ جَابِرٌ: فَقُمْتُ فَقُلْتُ: هَذَا رَجُلٌ يَا رَسُولَ اللَّهِ! فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ رَجُلٍ مَعَ جَابِرٍ؟ فَقَامَ جَبَّارُ بْنُ صَخْرٍ، فَانْطَلَقْنَا إِلَى الْبِئْرِ، فَنَزَعْنَا فِي الْحَوْضِ سِجِلًّا أَوْ سِجِلِّينِ، ثُمَّ مَدَّرْنَاهُ، ثُمَّ نَزَعْنَا فِيهِ حَتَّى أَفْهَقْنَاهُ، فَكَانَ أَوَّلَ طَالِعٍ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أتأذنان؟ قلنا: نَعَمْ يَا رَسُولَ اللَّهِ! فَأَشْرَعَ نَاقَتَهُ فَشَرِبْتُ، شَنِقَ لَهَا فَشُجَّتْ فَبَالَتْ، ثُمَّ عَدَلَ بِهَا فَأَنَاخَهَا، ثُمَّ جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْحَوْضِ فَتَوَضَّأَ مِنْهُ، ثُمَّ قُمْتُ فَتَوَضَّأْتُ مِنْ مُتَوَضَّإِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَهَبَ جَبَّارُ بْنُ صَخْرٍ يَقْضِي حَاجَتَهُ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُصَلِّيَ، وَكَانَتْ عَلَيَّ بُرْدَةٌ ذَهَبَتْ أَنْ أُخَالِفَ بَيْنَ طَرَفَيْهَا فَلَمْ تَبْلُغْ لِي، وَكَانَتْ لَهَا ذَبَاذِبُ فَنَكَّسَتْهَا، ثُمَّ خَالَفَتْ بَيْنَ طَرَفَيْهَا، ثُمَّ تَوَاقَصَتْ عَلَيْهَا، ثُمَّ جِئْتُ حَتَّى قُمْتُ عَنْ يَسَارِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَخَذَ بِيَدِي فَأَدَارَنِي حَتَّى أَقَامَنِي عَنْ يَمِينِهِ، ثُمَّ جَاءَ جَبَّارُ بْنُ صَخْرٍ فَتَوَضَّأَ، ثُمَّ جَاءَ فَقَامَ عَنْ يَسَارِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بيدينا جَمِيعًا، فَدَفَعْنَا حَتَّى أَقَامَنَا خَلْفَهُ، فَجَعَلَ رَسُولُ اللهصلى اللَّهُ عَلَيْهِ وَسَلَّمَ يُرْمِقُنِي وَأَنَا لا أَشْعُرُ، ثُمَّ فَطِنْتُ بِهِ، فَقَالَ هَكَذَا بِيَدِهِ، يَعْنِي شَدَّ وَسَطِكَ، فَلَمَّا فَرَغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَا جَابِرُ قُلْتُ: لَبَّيْكَ يَا رَسُولَ اللَّهِ! قَالَ: إِذَا كَانَ وَاسِعًا فَخَالَفَ بَيْنَ طَرَفَيْهِ، وَإِذَا كَانَ ضَيِّقًا فَاشْدُدْهُ عَلَى حَقْوِكَ.","سِرْنَا مَعَ رَسُولِ اللهِ صلى الله عليه وسلم وَكَانَ قُوتُ كُلِّ رَجُلٍ مِنَّا فِي كُلِّ يَوْمٍ تَمْرَةً، فَكَانَ يَمَصُّهَا ثُمَّ يَصُرُّهَا فِي ثَوْبِهِ، وَكُنَّا نَخْتَبِطُ بِقِسِيِّنَا وَنَأْكُلُ، حَتَّى قَرِحَتْ أَشْدَاقُنَا، فَأُقْسِمُ أُخْطِئَهَا رَجُلٌ مِنَّا يَوْمًا، فَانْطَلَقْنَا بِهِ نَنْعَشُهُ، فَشَهِدْنَا أَنَّهُ لَمْ يُعْطَهَا، فَأُعْطِيَهَا فَقَامَ فَأَخَذَهَا.","سِرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى نَزَلْنَا وَادِيًا أُفِيحَ، فَذَهَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْضِي حَاجَتَهُ، فَاتَّبَعْتُهُ بِإِدَاوَةٍ مِنْ مَاءٍ، فَنَظَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَرَ شَيْئًا يَسْتَتِرُ بِهِ، فَإِذَا شَجَرَتَانِ بِشَاطِئِ الْوَادِي، فَانْطَلَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى إِحْدَاهُمَا فَأَخَذَ بِغُصْنٍ مِنْ أَغْصَانِهَا، فَقَالَ: انْقَادِي عَلَيَّ بِإِذْنِ اللَّهِ فَانْقَادَتْ مَعَهُ كَالْبَعِيرِ الْمَخْشُوشِ، الَّذِي يُصَانِعُ قَائِدَهُ، حَتَّى أَتَى الشَّجَرَةَ الأُخْرَى، فَأَخَذَ بِغُصْنٍ مِنْ أَغْصَانِهَا، فَقَالَ: انْقَادِي عَلَيَّ بِإِذْنِ اللَّهِ فَانْقَادَتْ مَعَهُ كَذَلِكَ، حَتَّى إِذَا كَانَ بِالْمُنَصَّفِ مِمَّا بَيْنَهُمَا، لأُمٍّ بَيْنَهُمَا (يَعْنِي جَمْعَهُمَا) فَقَالَ: الْتَئَمَا عَلَيَّ بِإِذْنِ اللَّهِ فَالْتَأَمَتَا، قَالَ جَابِرٌ: فَخَرَجْتُ أَحْضَرُ مَخَافَةَ أَنْ يَحِسَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقُرْبِي فَيَبْتَعِدَ، (وَقَالَ مُحَمَّدُ بْنُ عَبَّادٍ: فَيَتَبَعَّدُ) فَجَلَسْتُ أُحَدِّثُ نَفْسِي، فَحَانَتْ مِنِّي لُفْتَةً، فَإِذَا أَنَا بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُقْبِلًا، وَإِذَا الشَّجَرَتَانِ قَدِ افْتَرَقَتَا، فَقَامَتْ كُلُّ وَاحِدَةٍ مِنْهُمَا عَلَى سَاقٍ، فَرَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَفَ وَقْفَةً، فَقَالَ بِرَأْسِهِ هَكَذَا (وَأَشَارَ أَبُو إِسْمَعِيلَ بِرَأْسِهِ يَمِينًا وَشِمَالًا) ثُمَّ أَقْبَلَ، فَلَمَّا انْتَهَى إِلَيَّ قَالَ: يَا جَابِرُ! هَلْ رَأَيْتَ مَقَامِي؟ قُلْتُ: نَعَمْ يَا رَسُولَ اللَّهِ، قَالَ: فَانْطَلِقْ إِلَى الشَّجَرَتَيْنِ فَاقْطَعْ مِنْ كُلِّ وَاحِدَةٍ مِنْهُمَا غُصْنًا، فَأَقْبِلْ بِهِمَا، حَتَّى إِذَا قُمْتَ مَقَامِي فَأَرْسِلْ غُصْنًا عَنْ يَمِينِكَ وَغُصْنًا عَنْ يَسَارِكَ.","قَالَ جَابِرٌ: فَقُمْتُ فَأَخَذْتُ حَجَرًا فَكَسَرْتُهُ وَحَسَرْتُهُ، فَانْذَلَقَ لِي، فَأَتَيْتُ الشَّجَرَتَيْنِ فَقَطَعْتُ مِنْ كُلِّ وَاحِدَةٍ مِنْهُمَا غُصْنًا، ثُمَّ أَقْبَلْتُ أَجُرُّهُمَا حَتَّى قُمْتُ مَقَامَ رَسُولِ اللهِ صلى الله عليه وسلم، أَرْسَلْتُ غُصْنًا عَنْ يَمِينِي وَغُصْنًا عَنْ يَسَارِي، ثُمَّ لَحِقْتُهُ فَقُلْتُ: قَدْ فَعَلْتُ يَا رَسُولَ اللهِ! فَعَمَّ ذَاكَ؟ قَالَ: إِنِّي مَرَرْتُ بِقَبْرَيْنِ يُعَذَّبَانِ، فَأَحْبَبْتُ بِشَفَاعَتِي أَنْ يُرَفَّهَ عَنْهُمَا، مَا دَامَ الْغُصْنَانِ رَطْبَيْنِ.","قَالَ: فَأَتَيْنَا الْعَسْكَرَ، فَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم: يَا جَابِرُ! نَادِ بِوَضُوءٍ فَقُلْتُ: أَلَا وَضُوءَ؟ أَلَا وَضُوءَ؟ أَلَا وَضُوءَ؟ قَالَ قُلْتُ: يَا رَسُولَ اللهِ! مَا وَجَدْتُ فِي الرَّكْبِ مِنْ قَطْرَةٍ، وَكَانَ رَجُلٌ مِنَ الْأَنْصَارِ يُبَرِّدُ لِرَسُولِ اللهصلى الله عليه وسلم الْمَاءَ فِي أَشْجَابٍ لَهُ عَلَى حِمَارَةٍ مِنْ جَرِيدٍ، قَالَ: فَقَالَ لِيَ: انْطَلِقْ إِلَى فُلَانِ ابن فُلَانٍ الْأَنْصَارِيِّ، فَانْظُرْ هَلْ فِي أَشْجَابِهِ مِنْ شَيْءٍ؟ قَالَ: فَانْطَلَقْتُ إِلَيْهِ فَنَظَرْتُ فِيهَا فَلَمْ أَجِدْ فِيهَا إِلَّا قَطْرَةً فِي عَزْلَاءِ شَجْبٍ مِنْهَا، لَوْ أَنِّي أُفْرِغُهُ لَشَرِبَهُ يَابِسُهُ، فَأَتَيْتُ رَسُولَ اللهِ صلى الله عليه وسلم فَقُلْتُ: يَا رَسُولَ اللهِ! إِنِّي لَمْ أَجِدْ فِيهَا إِلَّا قَطْرَةً فِي عَزْلَاءِ شَجْبٍ مِنْهَا، لَوْ أَنِّي أُفْرِغُهُ لَشَرِبَهُ يَابِسُهُ، قَالَ: اذْهَبْ فَأْتِنِي بِهِ، فَأَتَيْتُهُ بِهِ، فَأَخَذَهُ بِيَدِهِ فَجَعَلَ يَتَكَلَّمُ بِشَيْءٍ لَا أَدْرِي مَا هُوَ، وَيَغْمِزُهُ بِيَدَيْهِ، ثُمَّ أَعْطَانِيهِ فَقَالَ: يَا جَابِرُ! نَادِ بِجَفْنَةٍ فَقُلْتُ: يَا جَفْنَةَ الرَّكْبِ! فَأُتِيتُ بِهَا تُحْمَلُ، فَوَضَعْتُهَا بَيْنَ يَدَيْهِ، فَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم بِيَدِهِ فِي الْجَفْنَةِ هَكَذَا، فَبَسَطَهَا وَفَرَّقَ بَيْنَ أَصَابِعِهِ، ثُمَّ وَضَعَهَا فِي قَعْرِ الْجَفْنَةِ، وَقَالَ: خُذْ يَا جَابِرُ، فَصُبَّ عَلَيَّ، وَقُلْ: بِاسْمِ اللهِ فَصَبَبْتُ عَلَيْهِ وَقُلْتُ: بِاسْمِ اللهِ، فَرَأَيْتُ الْمَاءَ يفور مِنْ بَيْنِ أَصَابِعِ رَسُولِ اللهِ صلى الله عليه وسلم، ثُمَّ فَارَتِ الْجَفْنَةُ وَدَارَتْ حَتَّى امْتَلَأَتْ، فَقَالَ: يَا جَابِرُ، نَادِ مَنْ كَانَ لَهُ حَاجَةٌ بِمَاءٍ قَالَ: فَأَتَى النَّاسُ فَاسْتَقَوْا حَتَّى رَوُوا، قَالَ فَقُلْتُ: هَلْ بَقِيَ أَحَدٌ لَهُ حَاجَةٌ؟ فَرَفَعَ رَسُولُ اللهِ صلى الله عليه وسلم يَدَهُ مِنَ الْجَفْنَةِ وَهِيَ مَلْأَى.","وَشَكَا النَّاسُ إِلَى رَسُولِ اللهِ صلى الله عليه وسلم الْجُوعَ، فَقَالَ: عَسَى اللهُ أَنْ يُطْعِمَكُمْ فَأَتَيْنَا سِيفَ الْبَحْرِ، فَزَخَرَ الْبَحْرُ زَخْرَةً، فَأَلْقَى دَابَّةً، فَأَوْرَيْنَا عَلَى شِقِّهَا النَّارَ، فَاطَّبَخْنَا وَاشْتَوَيْنَا وَأَكَلْنَا حَتَّى شَبِعْنَا، قَالَ جَابِرٌ: فَدَخَلْتُ أَنَا وَفُلَانٌ وَفُلَانٌ، حَتَّى عَدَّ خَمْسَةً فِي حِجَاجِ عَيْنِهَا، مَا يَرَانَا أَحَدٌ، حَتَّى خَرَجْنَا فَأَخَذْنَا ضِلَعًا مِنْ أَضْلَاعِهِ فَقَوَّسْنَاهُ، ثُمَّ دَعَوْنَا بِأَعْظَمِ رَجُلٍ فِي الرَّكْبِ، وَأَعْظَمِ جَمَلٍ فِي الرَّكْبِ، وَأَعْظَمِ كِفْلٍ فِي الرَّكْبِ، فَدَخَلَ تَحْتَهُ مَا يُطَأْطِئُ رَأْسَهُ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (3006-3014) من طرق عن حاتم بن إسماعيل، عن يعقوب بن مجاهد أبي حزرة، عن عبادة بن الوليد بن عبادة بن الصامت فذكره.","grade":"صحيح","chapter_ar":"باب حديث أبي اليسر وجابر بن عبد اللّٰه في الزهد والرقاق","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (3006–3014).","chapter_en":"The Hadith of Abū al-Yasar and Jābir ibn ʿAbdullāh Concerning Asceticism and Heart-Softening Matters","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["ʿAbbād ibn al-Walīd ibn ʿUbādah ibn al-Ṣāmit narrated: My father and I went out seeking knowledge among this clan of the Anṣār before they passed away. The first person we met was Abū al-Yasar, a Companion of the Messenger of Allah ﷺ. With him was a servant boy carrying a bundle of written sheets. Abū al-Yasar was wearing a cloak and a Maʿāfirī garment, and his servant was likewise wearing a cloak and a Maʿāfirī garment. My father said to him: “Uncle, I can see signs of anger on your face.” He replied: “Indeed. So-and-so, son of so-and-so from Banū Ḥarām, owed me some money. I went to his family, greeted them, and asked, ‘Is he here?’ They replied, ‘No.’ Then a young son of his who was nearing puberty came out to me. I asked him, ‘Where is your father?’ He replied, ‘He heard your voice and went into my mother’s enclosed room.’ So I called out, ‘Come out to me, for I know where you are.’ He came out, and I asked, ‘What made you hide from me?’ He said, ‘By Allah, I will tell you the truth and not lie to you. By Allah, I feared that I might speak to you and lie, or make you a promise and then break it. You were a Companion of the Messenger of Allah ﷺ, and by Allah, I am in financial hardship.’ I said, ‘By Allah?’ He said, ‘By Allah.’ I asked again, ‘By Allah?’ He replied, ‘By Allah.’ I asked a third time, ‘By Allah?’ He replied, ‘By Allah.’” Abū al-Yasar then brought the written document of the debt and erased it with his own hand. He said: “If you later become able to repay, then repay me. Otherwise, you are released from it. I testify by these two eyes of mine”—and he placed his fingers upon his eyes—“and these two ears of mine, and this heart of mine that retained it”—and he pointed to his heart—“that the Messenger of Allah ﷺ said: ‘Whoever gives respite to a debtor in hardship, or remits his debt, Allah will shade him in His shade.’” I said to him: “Uncle, why do you not take your servant’s cloak and give him your Maʿāfirī garment, then take his Maʿāfirī garment and give him your cloak, so that each of you would have a matching set of garments?”","He wiped my head and said: “O Allah, bless him.” Then he said: “My nephew, these two eyes of mine saw, these two ears of mine heard, and this heart of mine retained”—and he pointed to his heart—“the Messenger of Allah ﷺ saying: ‘Feed them from what you yourselves eat, and clothe them from what you yourselves wear.’” He continued: “Giving him some of the possessions of this world is easier for me than having him take from my good deeds on the Day of Resurrection.” Then we continued until we came to Jābir ibn ʿAbdullāh in his mosque. He was praying wrapped in a single garment. I stepped past the people and sat between him and the qiblah. I said: “May Allah have mercy on you. Are you praying in a single garment while your outer cloak is lying beside you?” He placed his hand upon my chest like this, spreading and bending his fingers, and said: “I wanted a foolish person like you to come in, see how I do it, and then do the same.”","Jābir continued: The Messenger of Allah ﷺ came to us in this very mosque carrying a date-palm stalk from Ibn Ṭāb. He saw some phlegm on the qiblah wall of the mosque and scraped it away with the stalk. Then he turned toward us and said: “Which of you would like Allah to turn away from him?” We became subdued and silent. He repeated: “Which of you would like Allah to turn away from him?” We remained subdued. He asked a third time: “Which of you would like Allah to turn away from him?” We said: “None of us, O Messenger of Allah.” He said: “When one of you stands to pray, Allah, Blessed and Exalted, is before his face. So let him not spit in front of himself or to his right. Let him spit to his left beneath his left foot. If something suddenly overcomes him, then let him do this with his garment.” He then folded part of his garment over another part. Then he said: “Bring me some perfume.” A young man from the neighborhood hurried to his family and returned with some khalūq perfume in his palm. The Messenger of Allah ﷺ took it, placed it on the tip of the palm stalk, and smeared it over the place where the phlegm had been. Jābir said: “From that incident came your practice of placing perfume in your mosques.” We traveled with the Messenger of Allah ﷺ on the expedition of Baṭn Buwāṭ, while he was seeking al-Majdī ibn ʿAmr al-Juhanī. Five, six, or seven of us would take turns riding a single camel used for carrying water. When the turn of a man from the Anṣār came to ride his camel, he made it kneel, mounted it, and urged it forward.","The camel hesitated somewhat, so the man said: “Move! May Allah curse you.” The Messenger of Allah ﷺ asked: “Who is this person cursing his camel?” The man replied: “It is me, O Messenger of Allah.” He said: “Get down from it. Do not accompany us with an animal that has been cursed. Do not supplicate against yourselves, do not supplicate against your children, and do not supplicate against your wealth, lest you happen to coincide with a time in which Allah is asked for something and He answers you.”","We continued traveling with the Messenger of Allah ﷺ until late afternoon, when we approached a watering place belonging to some Arabs. The Messenger of Allah ﷺ said: “Who will go ahead of us, plaster the watering trough, drink, and prepare water for us?” Jābir said: I stood and said: “Here is a man, O Messenger of Allah.” The Messenger of Allah ﷺ asked: “Who will go with Jābir?” Jabbār ibn Ṣakhr stood up. We went to the well, drew one or two buckets of water into the trough, then plastered and repaired it. We continued drawing water until we filled it completely. The first person to arrive was the Messenger of Allah ﷺ. He asked: “Do you give permission?” We replied: “Yes, O Messenger of Allah.” He lowered his she-camel’s head into the water and she drank. He then pulled up her reins; she spread her legs and urinated. He moved her aside and made her kneel. Then the Messenger of Allah ﷺ came to the trough and performed wuḍūʾ from it. I stood and performed wuḍūʾ from the remaining water from the ablution of the Messenger of Allah ﷺ. Jabbār ibn Ṣakhr went away to relieve himself. The Messenger of Allah ﷺ stood to pray. I was wearing a cloak and tried to cross its two ends over my shoulders, but it was too short. It had loose hanging ends, so I turned it around, crossed its two ends, and bent my neck down to hold it in place. Then I came and stood on the left side of the Messenger of Allah ﷺ. He took me by the hand, moved me around, and placed me on his right. Then Jabbār ibn Ṣakhr returned, performed wuḍūʾ, and stood on the left side of the Messenger of Allah ﷺ. The Messenger of Allah ﷺ took both of us by the hands and moved us backward until he placed us behind him. The Messenger of Allah ﷺ kept glancing toward me, though at first I did not notice. Then I became aware of him. He gestured with his hand, meaning: “Tighten it around your waist.” When the Messenger of Allah ﷺ finished the prayer, he said: “O Jābir.” I replied: “At your service, O Messenger of Allah.” He said: “If the garment is wide, cross its two ends over your shoulders. If it is narrow, fasten it around your waist.”","We continued traveling with the Messenger of Allah ﷺ. The daily provision of each one of us was a single date. A man would suck on it and then wrap it up in his garment. We would also strike the trees with our bows so that their leaves fell, and we would eat them, until the sides of our mouths became ulcerated. One day, by Allah, one of our men was mistakenly not given his date. We carried him along, supporting him because of his weakness, and testified that he had not received it.","So he was given his date, whereupon he stood up and took it. We continued traveling with the Messenger of Allah ﷺ until we reached a broad valley. The Messenger of Allah ﷺ went away to relieve himself, and I followed him carrying a small vessel of water. The Messenger of Allah ﷺ looked around but saw nothing behind which he could conceal himself. There were two trees on the edge of the valley. He went to one of them, took hold of one of its branches, and said: “Come with me by the permission of Allah.” It moved along with him like a camel with a nose-peg that submits to its handler. He then came to the other tree, took one of its branches, and said: “Come with me by the permission of Allah.” It moved along with him in the same way. When he reached the midpoint between the two trees, he brought them together and said: “Join together over me by the permission of Allah.” And the two trees joined together. Jābir said: I hurried away because I feared that the Messenger of Allah ﷺ might become aware of how close I was and move even farther away. Muḥammad ibn ʿAbbād’s wording has: “move farther away.” I sat speaking to myself. Then I happened to glance over and saw the Messenger of Allah ﷺ approaching. The two trees had separated again, each standing upon its own trunk. I saw the Messenger of Allah ﷺ stop briefly and move his head like this—Abū Ismāʿīl gestured with his head to the right and left—then he continued toward me. When he reached me, he said: “O Jābir, did you see where I was standing?” I replied: “Yes, O Messenger of Allah.” He said: “Go to the two trees and cut a branch from each one. Bring them back, and when you reach the place where I stood, place one branch on your right and one branch on your left.” Jābir said: I stood up, took a stone, broke it and sharpened it until it had a cutting edge. I went to the two trees, cut a branch from each, and dragged them back until I reached the place where the Messenger of Allah ﷺ had stood. I placed one branch on my right and the other on my left. Then I caught up with him and said: “I have done it, O Messenger of Allah. Why did you ask me to do that?” He replied: “I passed by two graves whose occupants are being punished, and I wished, through my intercession, that their punishment might be lightened for as long as the two branches remain fresh.”","We returned to the camp. The Messenger of Allah ﷺ said: “O Jābir, call out for water for ablution.” I called: “Is there any water for ablution? Any water for ablution? Any water for ablution?” Then I said: “O Messenger of Allah, I could not find a single drop among the travelers.” There was a man from the Anṣār who used to cool water for the Messenger of Allah ﷺ in worn waterskins hung upon a wooden frame. The Prophet ﷺ said to me: “Go to so-and-so, son of so-and-so, the Anṣārī, and see whether there is anything in his waterskins.”","I went and checked them. I found only a single drop remaining at the mouth of one worn waterskin—so little that if I poured it out, the dry skin itself would absorb it. I returned to the Messenger of Allah ﷺ and said: “O Messenger of Allah, I found only one drop at the mouth of one waterskin. If I poured it out, the dry waterskin itself would absorb it.” He said: “Go and bring it to me.” I brought it to him. He took it in his hand, began saying something that I could not understand, and squeezed it with his hands. Then he gave it back to me and said: “O Jābir, call for a large basin.” I called out: “Bring the travelers’ basin!” It was brought, carried by several people, and I placed it before him. The Messenger of Allah ﷺ spread his hand in the basin, separated his fingers, and placed his hand at the bottom of it. Then he said: “Take it, O Jābir. Pour over my hand and say: ‘In the name of Allah.’” I poured and said: “In the name of Allah.” Then I saw water bursting forth from between the fingers of the Messenger of Allah ﷺ. The basin began filling and swirling with water until it became full. He said: “O Jābir, call everyone who needs water.” The people came and drew water until they were completely satisfied. I asked: “Is there anyone left who still needs water?” Then the Messenger of Allah ﷺ lifted his hand from the basin while it was still full. The people complained of hunger to the Messenger of Allah ﷺ. He said: “Perhaps Allah will feed you.” We came to the seashore.","The sea surged strongly and cast out a huge sea creature. We lit a fire beside it, cooked and roasted from it, and ate until we were full. Jābir said: Five of us, including myself and several others whom he named, entered into the socket of its eye without anyone outside being able to see us. Then we came out and took one of its ribs and stood it upright like an arch. We called for the tallest man among the travelers, the largest camel among them, and the largest riding cushion among them. The rider passed beneath that rib without even needing to lower his head."]},"buhuth":{"en":["Explanation of Uncommon Words","The phrase “with him was a ḍamāmah of written sheets” means a bundle of sheets gathered together.","A burdah is a striped wrap or cloak.","A Maʿāfirī garment is a type of clothing manufactured in a place called Maʿāfir.","“Safʿah of anger” means a visible sign or change in the face caused by anger.","A jafr is a young boy approaching puberty.","“Manāṭ qalbihi” refers to the part or vessel attached to the heart.","A ḥullah consists of a lower garment and an upper cloak.","An ʿurjūn is a palm stalk or branch.","Ibn Ṭāb is a type of date.","Regarding “ʿabīr,” Abū ʿUbayd said that it means saffron alone, while al-Aṣmaʿī said it is a mixture of perfumes combined with saffron.","Khalūq is a perfume composed of several fragrances mixed with saffron; according to al-Aṣmaʿī, this is what is meant by ʿabīr.","Baṭn Buwāṭ is a mountain in the territory of Juhaynah.","A nāḍiḥ is a camel used for drawing water.","The phrase “shaʾ, may Allah curse you” contains shaʾ, a word used to drive or rebuke a camel.","“Yamdur al-ḥawḍ” means to plaster the trough with mud and repair it.","“Until we afhaqnāhu” means until we filled it completely.","“He caused his she-camel to drink” means that he lowered her head into the water.","“Shanaqa lahā” means that he restrained her with the reins while mounted.","“Fashajat” means that the camel spread its legs apart in order to urinate.","Dhadhābhib are loose hanging ends of a garment. The singular is dhubdhub. They are so called because they sway and move as the wearer walks.","“Fanakkastuhā” means “I turned it upside down.” From the same root comes the description of a breech birth, when the feet emerge before the head.","“Tawāqaṣtu ʿalayhā” means that he held the garment in place with his neck, bending over it so that it would not fall.","“Fasten it around your ḥaqw” refers to the place where the lower garment is tied, here meaning around the level of the waist or navel.","“We used to nakhtabiṭ with our bows” means that they struck trees with their bows so that the leaves would fall and they could eat them. Qisiyy is the plural of bow.","“Until our ashdaq became ulcerated” means that the sides of their mouths became wounded because of the roughness and harshness of the leaves.","“We supported him” means that they lifted and steadied him because of his severe weakness and exhaustion.","An afyaḥ valley means a broad and spacious valley.","A mukhshūsh camel is one with a small wooden peg placed through its nose when it is difficult to control, with a rope attached to it so that it becomes submissive and manageable.","“At the munṣaf” means at the halfway point.","“I went away quickly” means that he ran rapidly.","“A glance occurred from me” means that he looked to the side.","“Wa-ḥasartuhu” means that he sharpened it.","“Fa-indhalaqa” means that it became sharp.","“That relief be given to them” means that their punishment be lightened.","Ashjāb is the plural of shajb, meaning an old worn waterskin that has become thin and weathered.","A ḥimārah here means a wooden frame upon which waterskins are hung.","ʿAzlāʾ means the mouth or opening of a waterskin.","The phrase means that the amount of water was so tiny that the dry waterskin itself would absorb it.","“He squeezed it with his hands” means that he pressed and wrung it.","Sayf al-baḥr means the seashore.","“The sea surged” means that its waves rose.","“Fa-awraynā” means “we kindled a fire.”","The ḥijāj of its eye is the circular bone surrounding the eye socket.","The largest kifl here means the cloth or padding arranged by a camel rider over the hump to prevent himself from falling; it supports and secures the rider."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (3006-3014)."},{"num":15119,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  رُبَّ أَشْعَثَ، مَدْفُوعٍ بِالْأَبْوَابِ لَوْ أَقْسَمَ عَلَى اللَّهِ لَأَبَرَّهُ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2622) عن سويد بن سعيد، حدثني حفص بن ميسرة، عن العلاء بن عبد الرحمن، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب فضل الضعفاء والمساكين","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2622).","chapter_en":"The Virtue of the Weak and the Poor","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “How many a disheveled person, driven away from people’s doors, is such that if he were to swear by Allah, Allah would surely fulfill his oath.”"]}},"tuhfa":{},"full":1,"rep":[7059,13008,14974],"tks":"صحيح: رواه مسلم (2622)."},{"num":15120,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ أَنَّ النَّبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: رُبَّ أَشْعَثَ أَغْبَرَ ذِي طِمْرَيْنِ لَوْ أَقْسَمَ عَلَى اللَّهِ لَأَبَرَّهُ."],"takhrij":"حسن: رواه عبد بن حميد (1236- المنتخب)، والبزار (6459)، والطبراني في الأوسط (5054- مجمع البحرين) كلهم من طريق أسامة بن زيد، عن حفص بن عبيد الله بن أنس، عن جده أنس فذكره.","grade":"حسن","chapter_ar":"باب فضل الضعفاء والمساكين","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by ʿAbd ibn Ḥumayd (1236), al-Bazzār (6459), and al-Ṭabarānī in al-Muʿjam al-Awsaṭ (5054, as cited in Majmaʿ al-Baḥrayn).","chapter_en":"The Virtue of the Weak and the Poor","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “How many a disheveled, dusty person wearing two worn garments is such that if he were to swear by Allah, Allah would surely fulfill his oath.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عبد بن حميد (1236)، والبزار (6459)، والطبراني في الأوسط (5054 - مجمع البحرين)."},{"num":15121,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ، أَنَّهُ قَالَ مَرَّ رَجُلٌ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِرَجُلٍ عِنْدَهُ جَالِسٍ مَا رَأْيُكَ فِي هَذَا. فَقَالَ رَجُلٌ مِنْ أَشْرَافِ النَّاسِ، هَذَا وَاللَّهِ حَرِيٌّ إِنْ خَطَبَ أَنْ يُنْكَحَ، وَإِنْ شَفَعَ أَنْ يُشَفَّعَ. قَالَ فَسَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ مَرَّ رَجُلٌ فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا رَأْيُكَ فِي هَذَا. فَقَالَ يَا رَسُولَ اللَّهِ هَذَا رَجُلٌ مِنْ فُقَرَاءِ الْمُسْلِمِينَ، هَذَا حَرِيٌّ إِنْ خَطَبَ أَنْ لاَ يُنْكَحَ، وَإِنْ شَفَعَ أَنْ لاَ يُشَفَّعَ، وَإِنْ قَالَ أَنْ لاَ يُسْمَعَ لِقَوْلِهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذَا خَيْرٌ مِنْ مِلْءِ الأَرْضِ مِثْلَ هَذَا."],"takhrij":"صحيح: رواه البخاري في الرقاق (6447) عن إسماعيل، حدثني عبد العزيز بن أبي حازم، عن أبيه، عن سهل بن سعد الساعدي قال: فذكره.","grade":"صحيح","chapter_ar":"باب فضل الضعفاء والمساكين","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6447).","chapter_en":"The Virtue of the Weak and the Poor","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Sahl ibn Saʿd al-Sāʿidī narrated: A man passed by the Messenger of Allah ﷺ. The Prophet ﷺ asked a man sitting with him: “What is your opinion of this man?” He replied: “He is one of the noble people. By Allah, if he proposes marriage, he deserves to be accepted; and if he intercedes, his intercession deserves to be accepted.” The Messenger of Allah ﷺ remained silent. Then another man passed by. The Messenger of Allah ﷺ asked: “What is your opinion of this man?” He replied: “O Messenger of Allah, this is one of the poor Muslims. If he proposes marriage, he is likely not to be accepted; if he intercedes, his intercession is likely not to be accepted; and if he speaks, people are unlikely to listen to him.” The Messenger of Allah ﷺ said: “This man is better than an earthful of people like the first man.”"]}},"tuhfa":{},"full":1,"rep":[11990],"tks":"صحيح: رواه البخاري (6447)."},{"num":15122,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا أَبَا ذَرٍّ، ارْفَعْ بَصَرَكَ فَانْظُرْ أَرْفَعَ رَجُلٍ تَرَاهُ فِي الْمَسْجِدِ قَالَ: فَنَظَرْتُ، فَإِذَا رَجُلٌ جَالِسٌ عَلَيْهِ حُلَّةٌ، قَالَ: فَقُلْتُ: هَذَا. قَالَ: فَقَالَ: يَا أَبَا ذَرٍّ، ارْفَعْ بَصَرَكَ فَانْظُرْ أَوْضَعَ رَجُلٍ تَرَاهُ فِي الْمَسْجِدِ قَالَ: فَنَظَرْتُ، فَإِذَا رَجُلٌ ضَعِيفٌ عَلَيْهِ أَخْلَاقٌ، قَالَ: فَقُلْتُ: هَذَا. قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَالَّذِي نَفْسِي بِيَدِهِ، لَهَذَا أَفْضَلُ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ مِنْ قُرَابِ الْأَرْضِ مِثْلِ هَذَا."],"takhrij":"صحيح: رواه أحمد (21493) –واللفظ له– وابن أبي شيبة في المصنف (35457)، وهنّاد بن السري في الزهد (815) كلهم من طريق أبي معاوية، حدثنا الأعمش، عن زيد بن وهب، عن أبي ذرّ فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب فضل الضعفاء والمساكين","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (21493), and this is his wording, Ibn Abī Shaybah (35457), and Hannād in al-Zuhd (815).","chapter_en":"The Virtue of the Weak and the Poor","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Abū Dharr narrated: The Messenger of Allah ﷺ said: “O Abū Dharr, raise your gaze and look for the most prominent man you can see in the mosque.” I looked and saw a man seated wearing a fine set of garments. I said: “This man.” He then said: “O Abū Dharr, raise your gaze and look for the lowest-ranking man you can see in the mosque.” I looked and saw a weak man wearing worn-out clothes. I said: “This man.” The Messenger of Allah ﷺ said: “By the One in whose Hand is my soul, this man will be better before Allah on the Day of Resurrection than an earthful of men like that other one.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (21493) - واللفظ له -، وابن أبي شيبة (35457)، وهناد في الزهد (815)."},{"num":15123,"demo":false,"sanad":"","matn":["عن أبي ذرٍّ، أنَّ رسولَ الله صلى الله عليه وسلم قال له: كيفَ ترى جُعيلاً؟ قال: فقلتُ: مسكينًا كشكله من الناس. قال : فكيفَ ترَى فلانًا؟ قلتُ: سيّدًا من ساداتِ النّاس. قال: فجعيلٌ خيرٌ من مِلْءِ الأرضِ أو آلافِ أو نحو ذلك من فلان. قال: قلت: يا رسول الله، ففلان هكذا، و أنت تصنعُ به ما تصنعُ؟ فقال: إنه رأسُ قومِه، فأنا أتألّفُهم فيه."],"takhrij":"صحيح: رواه ابن وهب في الجامع (34) عن عمرو بن الحارث، أن أبابكر بن سوادة حدّثه، أن أبا سالم الجيشاني حدّثه، عن أبي ذرٍّ قال: فذكره.","grade":"صحيح","chapter_ar":"باب فضل الضعفاء والمساكين","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Wahb in al-Jāmiʿ (34).","chapter_en":"The Virtue of the Weak and the Poor","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Abū Dharr narrated that the Messenger of Allah ﷺ said to him: “What do you think of Juʿayl?” I replied: “He is a poor man, like others of his kind among the people.” He asked: “And what do you think of so-and-so?” I replied: “He is a leader among the leaders of the people.” The Prophet ﷺ said: “Juʿayl is better than an earthful—or thousands, or something similar—of men like so-and-so.” I said: “O Messenger of Allah, if so-and-so is like that, why do you treat him as you do?” He replied: “He is the leader of his people, so through him I seek to win their hearts.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن وهب في الجامع (34)."},{"num":15124,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلَا أُخْبِرُكُمْ بِخِيَارِكُمْ قَالُوا: بَلَى يَا رَسُولَ اللَّهِ قَالَ: الَّذِينَ إِذَا رُؤُوا، ذُكِرَ اللهُ تَعَالَى ثُمَّ قَالَ: أَلَا أُخْبِرُكُمْ بِشِرَارِكُمْ؟ الْمَشَّاءُونَ بِالنَّمِيمَةِ، الْمُفْسِدُونَ بَيْنَ الْأَحِبَّةِ، الْبَاغُونَ لِلْبُرَآءِ الْعَنَتَ."],"takhrij":"حسن: رواه أحمد (27599) – واللفظ له – وابن ماجه (4119)، والبخاري في الأدب المفرد (323) كلهم من طرق عن عبدالله بن عثمان بن خثيم، عن شهر بن حوشب، عن أسماء بنت يزيد فذكرته.","grade":"حسن","chapter_ar":"باب فضل الضعفاء والمساكين","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (27599), and this is his wording, Ibn Mājah (4119), and al-Bukhārī in al-Adab al-Mufrad (323).","chapter_en":"The Virtue of the Weak and the Poor","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Asmāʾ bint Yazīd narrated that the Prophet ﷺ said: “Shall I tell you who the best among you are?” They replied: “Yes, O Messenger of Allah.” He said: “Those who, when they are seen, Allah is remembered.” Then he said: “Shall I tell you who the worst among you are? Those who go about spreading malicious gossip, those who cause corruption between people who love one another, and those who seek hardship and ruin for the innocent.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (27599) - واللفظ له -، وابن ماجه (4119)، والبخاري في الأدب المفرد (323)."},{"num":15125,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، مَنْ أَوْلِيَاءُ اللَّهِ؟ قَالَ: الَّذِينَ إِذَا رُؤُوا ذُكِرَ اللَّهُ."],"takhrij":"حسن: رواه البزار –كشف الأستار (3626)، والطبراني في الكبير (12325)، وابن صاعد في زياداته على الزهد لابن المبارك (218) كلهم من طرق عن جعفر بن أبي المغيرة، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب فضل الضعفاء والمساكين","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār, as cited in Kashf al-Astār (3626), al-Ṭabarānī in al-Muʿjam al-Kabīr (12325), and Ibn Ṣāʿid in his additions to Ibn al-Mubārak’s al-Zuhd (218).","chapter_en":"The Virtue of the Weak and the Poor","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Ibn ʿAbbās narrated: A man asked: “O Messenger of Allah, who are the allies of Allah?” He replied: “Those who, when they are seen, Allah is remembered.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (3626)، والطبراني في الكبير (12325)، وابن صاعد في زياداته على الزهد لابن المبارك (218)."},{"num":15126,"demo":false,"sanad":"","matn":["عَنْ جَرِيرٍ بْنِ عَبْدِ اللَّهِ البجلي عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ يَتَزَوَّدْ فِي الدُّنْيَا ينفَعْه فِي الْآخِرَةِ."],"takhrij":"حسن: رواه الطبراني في المعجم الكبير (2271) عن عبدان بن أحمد (هو عبد الله بن أحمد بن موسى، وعبدان لقبه)، حدثنا هشام بن عمّار، حدثنا مروان بن معاويـة، عن إسماعيـل بن أبي خالد، عن قيس (هو ابن أبي حازم)، عن جرير قـال: فذكر الحديث.","grade":"حسن","chapter_ar":"باب التزود في الدنيا بالأعمال الصالحة لتنفع في الآخرة","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (2/345–346).","chapter_en":"Taking Provision in This World through Righteous Deeds That Will Benefit in the Hereafter","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Jarīr ibn ʿAbdullāh al-Bajalī narrated that the Prophet ﷺ said: “Whatever provision a person takes in this world will benefit him in the Hereafter.”"]},"buhuth":{"en":["The phrase “takes provision in this world” means provision in the form of righteous deeds."]},"intro":{"ar":["قال اللّٰه تعالى:","﴿وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى﴾ [البقرة: ١٩٧]."],"en":["Allah, the Exalted, says:","“Take provision, but indeed the best provision is piety.”","[Sūrat al-Baqarah 2:197]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (2/345-346)."},{"num":15127,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَوْ أَنَّكُمْ تَوَكَّلُونَ عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ، لَرَزَقَكُمُ اللهُ كَمَا يَرْزُقُ الطَّيْرَ، تَغْدُو خِمَاصًا، وَتَرُوحُ بِطَانًا."],"takhrij":"صحيح: رواه الترمذي (2344)، وابن ماجه (4164)، وأحمد (205)، وصحّحه ابن حبّان (730)، والحاكم (7894) كلهم من طرقٍ عن عبد الله بن هبيرة، عن أبي تميم الجيشاني (هو: عبدالله بن مالك بن أبي الأسحم)، عن عمر بن الخطاب فذكره.","grade":"صحيح","chapter_ar":"باب فضل التوكل على اللّٰه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2344), Ibn Mājah (4164), Aḥmad (205), Ibn Ḥibbān (730), and al-Ḥākim (7894).","chapter_en":"The Virtue of Reliance upon Allah","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb narrated that the Messenger of Allah ﷺ said: “If you were to rely upon Allah with true reliance, He would provide for you just as He provides for the birds: they leave in the morning with empty stomachs and return in the evening with full stomachs.”"]},"buhuth":{"en":["The word “khimāṣan” means with stomachs empty and drawn in from hunger.","The word “biṭānan” means with stomachs full."]},"intro":{"ar":["قال اللّٰه تعالى:","﴿وَمَنْ يَتَوَكَّلْ عَلَى اللّٰهِ فَهُوَ حَسْبُهُ﴾ [الطلاق: ٣]."],"en":["Allah, the Exalted, says:","“Whoever relies upon Allah, then He is sufficient for him.”","[Sūrat al-Ṭalāq 65:3]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13599],"tks":"صحيح: رواه الترمذي (2344)، وابن ماجه (4164)، وأحمد (205)، وابن حبان (730)، والحاكم (7894)."},{"num":15128,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ كَانَ أَخَوَانِ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكَانَ أَحَدُهُمَا يَأْتِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالآخَرُ يَحْتَرِفُ فَشَكَا الْمُحْتَرِفُ أَخَاهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَعَلَّكَ تُرْزَقُ بِهِ."],"takhrij":"صحيح: رواه الترمذي (2345)، والبزار (6988)، وصحّحه الحاكم (320) كلهم من طريق أبي داود سليمان بن داود الطيالسي، حدثنا حماد بن سلمة، عن ثابت، عن أنس بن مالك فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب فضل التوكل على اللّٰه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2345), al-Bazzār (6988), and authenticated by al-Ḥākim (320).","chapter_en":"The Virtue of Reliance upon Allah","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Anas ibn Mālik narrated: There were two brothers during the time of the Prophet ﷺ. One of them would regularly come to the Prophet ﷺ, while the other worked to earn a living. The one who worked complained to the Prophet ﷺ about his brother. The Prophet ﷺ said: “Perhaps you are being provided for because of him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1121],"tks":"صحيح: رواه الترمذي (2345)، والبزار (6988)، وصححه الحاكم (320)."},{"num":15129,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ عَنْ أَبِيهِ، قَالَ: قَالَ رَجُلٌ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُرْسِلُ نَاقَتِي وَأَتَوَكَّلُ؟ قَالَ: اعْقِلْهَا وَتَوَكَّلْ."],"takhrij":"حسن: رواه ابن أبي عاصم في الآحاد والمثاني (970)، وصحّحه ابن حبّان (731)، والحاكم (3/623) كلهم من طرق عن حاتم بن إسماعيل، حدثنا يعقوب بن عمرو بن عبد الله بن أمية الضمري، عن جعفر بن أمية، عن أبيه عمرو بن أمية الضمري قال: فذكره.","grade":"حسن","chapter_ar":"باب فضل التوكل على اللّٰه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī ʿĀṣim in al-Āḥād wa-al-Mathānī (970), and authenticated by Ibn Ḥibbān (731) and al-Ḥākim (3/623).","chapter_en":"The Virtue of Reliance upon Allah","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["ʿAmr ibn Umayyah al-Ḍamrī narrated: A man asked the Prophet ﷺ: “Should I leave my camel untied and rely upon Allah?” He replied: “Tie it, and rely upon Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في الآحاد والمثاني (970)، وصححه ابن حبان (731)، والحاكم (3/623)."},{"num":15130,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ مِنْ بَيْتِهِ قَالَ بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ أَنْ نَزِلَّ أَوْ نَضِلَّ أَوْ نَظْلِمَ أَوْ نُظْلَمَ أَوْ نَجْهَلَ أَوْ يُجْهَلَ عَلَيْنَا."],"takhrij":"صحيح: رواه أبو داود (5094)، والترمذي (3427)، والنسائي (5486)، وابن ماجه (3884)، وأحمد (26616، 26704)، وابن السني في عمل اليوم والليلة (177)، والحاكم (1/519) كلهم من طرق عن منصور، عن الشعبي، عن أمّ سلمة فذكرته. والسياق للترمذي.","grade":"صحيح","chapter_ar":"باب فضل التوكل على اللّٰه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (5094), al-Tirmidhī (3427), al-Nasā’ī (5486), Ibn Mājah (3884), Aḥmad (26616, 26704), Ibn al-Sunnī in ʿAmal al-Yawm wa-al-Laylah (177), and al-Ḥākim (1/519). The wording is that of al-Tirmidhī.","chapter_en":"The Virtue of Reliance upon Allah","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Umm Salamah narrated that when the Prophet ﷺ left his house, he would say: “In the name of Allah. I place my trust in Allah. O Allah, we seek refuge in You from slipping or going astray, from wronging or being wronged, and from acting ignorantly or having ignorance directed against us.”"]},"buhuth":{"en":["The Meaning of Reliance upon Allah","Reliance upon Allah does not mean abandoning work and sitting idle.","Rather, reliance means striving and exerting effort in seeking provision through lawful means, then entrusting to Allah whatever He has decreed for the person.","It is narrated that ʿUmar ibn al-Khaṭṭāb met some people from Yemen and asked:","“Who are you?”","They replied:","“We are those who rely upon Allah.”","He said:","“Rather, you are merely dependent upon others. The one who truly relies upon Allah is the one who casts his seed into the earth and then relies upon Allah, Mighty and Majestic.”","Narrated by Ibn Abī al-Dunyā in al-Tawakkul (10), through Muʿāwiyah ibn Qurrah, who narrated that ʿUmar ibn al-Khaṭṭāb met some people and then related the report.","Muʿāwiyah ibn Qurrah did not meet ʿUmar ibn al-Khaṭṭāb, because he was born in the year 37 AH.","ʿAbdullāh ibn Masʿūd said:","“The verse in the Qur’an containing the strongest meaning of entrusting one’s affairs to Allah is: ‘Whoever relies upon Allah, then He is sufficient for him.’”","[Sūrat al-Ṭalāq 65:3]","In another narration:","“Whoever fears Allah, He will make for him a way out.”","[Sūrat al-Ṭalāq 65:2]","This was mentioned by Ibn Abī al-Dunyā in al-Tawakkul (50), ʿAbd al-Razzāq (3/370–371), and others.","Some sages said that reliance upon Allah has three levels:","The first is abandoning complaint.","The second is contentment.","The third is love.","Abandoning complaint is the level of patience.","Contentment is the heart becoming tranquil with whatever Allah, Mighty and Majestic, has apportioned for it, and this is higher than the first level.","Love is that a person loves whatever Allah, Mighty and Majestic, does with him.","The first level is for the ascetics, the second for the truthful, and the third for the messengers.","Ibn Abī al-Dunyā mentioned this in al-Tawakkul (46)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11305],"tks":"صحيح: رواه أبو داود (5094)، والترمذي (3427)، والنسائي (5486)، وابن ماجه (3884)، وأحمد (26616، 26704)، وابن السني في عمل اليوم والليلة (177)، والحاكم (1/519)، والسياق للترمذي."},{"num":15131,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: صَلَاحُ أوّل هَذِهِ الْأُمَّةِ بِالزُّهْدِ وَالْيَقِينِ، وَيَهْلِكُ آخِرُهَا بِالْبُخْلِ وَالْأَمَلِ."],"takhrij":"حسن: رواه أحمد في الزهد (51)، وابن بشران في أماليه (908)، والبيهقي في الشعب (10046) كلهم من طرق عن محمد بن مسلم، عن إبراهيم بن ميسرة، عن عمرو بن شعيب، عن أبيه، عن جده قال: فذكره. وسقط من مطبوعة الزهد عن أبيه.","grade":"حسن","chapter_ar":"باب فضل التوكل على اللّٰه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad in al-Zuhd (51), Ibn Bishrān in his Amālī (908), and al-Bayhaqī in Shuʿab al-Īmān (10046).","chapter_en":"The Virtue of Reliance upon Allah","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Messenger of Allah ﷺ said: “The righteousness of the first generation of this Ummah was through asceticism and certainty, while its later generations will be ruined through miserliness and prolonged worldly hopes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد في الزهد (51)، وابن بشران في أماليه (908)، والبيهقي في الشعب (10046)."},{"num":15132,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ، قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْرَابِيَّانِ، فَقَالَ أَحَدُهُمَا: مَنْ خَيْرُ الرِّجَالِ يَا مُحَمَّدُ؟ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ طَالَ عُمْرُهُ، وَحَسُنَ عَمَلُهُ، وَقَالَ الْآخَرُ: إِنَّ شَرَائِعَ الْإِسْلَامِ قَدْ كَثُرَتْ عَلَيْنَا، فَبَابٌ نَتَمَسَّكُ بِهِ جَامِعٌ؟ قَالَ: لَا يَزَالُ لِسَانُكَ رَطْبًا مِنْ ذِكْرِ اللهِ."],"takhrij":"صحيح: رواه الترمذي (2329، 3375)، وأحمد (17680، 17698) –والسياق له – كلاهما من طرق عن عمرو بن قيس الكندي، عن عبد الله بن بسر فذكره.","grade":"صحيح","chapter_ar":"باب من طال عمره وحسن عمله","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2329, 3375) and Aḥmad (17680, 17698), and this is his wording.","chapter_en":"The One Whose Life Is Long and Whose Deeds Are Good","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["ʿAbdullāh ibn Busr narrated: Two Bedouins came to the Prophet ﷺ. One of them asked: “Who are the best of men, O Muḥammad?” The Prophet ﷺ replied: “The one whose life is long and whose deeds are good.” The other said: “The teachings of Islam have become numerous for us. Give us one comprehensive practice to which we can hold fast.” He replied: “Let your tongue remain moist with the remembrance of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2329، 3375)، وأحمد (17680، 17698) - والسياق له -."},{"num":15133,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَا أُنَبِّئُكُمْ بِخَيْرِكُمْ؟، قَالُوا: نَعَمْ يَا رَسُولَ اللَّهِ. قَالَ: خِيَارُكُمْ أَطْوَلُكُمْ أَعْمَارًا، وَأَحْسَنُكُمْ أَعْمَالًا."],"takhrij":"حسن: رواه أحمد (7212)، والبزار – كشف الأستار (1971)، وصحّحه ابن حبان (2981) كلهم من طريق محمد بن إسحاق، حدثني محمد بن إبراهيم التميمي، عن أبي سلمة بن عبد الرحمن، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب من طال عمره وحسن عمله","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (7212), al-Bazzār, as cited in Kashf al-Astār (1971), and authenticated by Ibn Ḥibbān (2981).","chapter_en":"The One Whose Life Is Long and Whose Deeds Are Good","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Shall I tell you who the best among you are?” They replied: “Yes, O Messenger of Allah.” He said: “The best among you are those whose lives are longest and whose deeds are best.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (7212)، والبزار في كشف الأستار (1971)، وصححه ابن حبان (2981)."},{"num":15134,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ: أَلَا أُخْبِرُكُمْ بِخِيَارِكُمْ: خِيَارُكُمْ أَطْولُكُمْ أَعْمَارًا وَأحْسَنُكُمْ أَعْمَالًا."],"takhrij":"صحيح: رواه عبد بن حميد (1086)، والبزار – كشف الأستار (3585)، وأبو بكر الشافعي في الغيلانيات (346)، وصحّحه الحاكم (1/3399 كلهم من طرق عن محمد بن المنكدر، عن جابر فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من طال عمره وحسن عمله","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by ʿAbd ibn Ḥumayd (1086), al-Bazzār, as cited in Kashf al-Astār (3585), Abū Bakr al-Shāfiʿī in al-Ghaylāniyyāt (346), and authenticated by al-Ḥākim (1255).","chapter_en":"The One Whose Life Is Long and Whose Deeds Are Good","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Messenger of Allah ﷺ said: “Shall I tell you who the best among you are? The best among you are those whose lives are longest and whose deeds are best.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه عبد بن حميد (1086)، والبزار في كشف الأستار (3585)، وأبو بكر الشافعي في الغيلانيات (346)، وصححه الحاكم (1255)."},{"num":15135,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكَرَةَ، أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللَّهِ، أَيُّ النَّاسِ خَيْرٌ؟ قَالَ: مَنْ طَالَ عُمْرُهُ، وَحَسُنَ عَمَلُهُ، قَالَ: فَأَيُّ النَّاسِ شَرٌّ؟ قَالَ: مَنْ طَالَ عُمْرُهُ، وَسَاءَ عَمَلُهُ."],"takhrij":"حسن: رواه أحمد (20444)، والحاكم (1256)، كلاهما من طريق حماد بن سلمة، عن حميد ويونس، عن الحسن، عن أبي بكرة فذكره.","grade":"حسن","chapter_ar":"باب من طال عمره وحسن عمله","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (20444) and al-Ḥākim (1256).","chapter_en":"The One Whose Life Is Long and Whose Deeds Are Good","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Abū Bakrah narrated: A man asked: “O Messenger of Allah, which people are best?” He replied: “The one whose life is long and whose deeds are good.” The man asked: “And which people are worst?” He replied: “The one whose life is long and whose deeds are evil.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20444)، والحاكم (1256)."},{"num":15136,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْمَارُ أُمَّتِي مَا بَيْنَ سِتِّينَ إِلَى سَبْعِينَ وَأَقَلُّهُمْ مَنْ يَجُوزُ ذَلِكَ."],"takhrij":"حسن: رواه الترمذي (3550)، وابن ماجه (4236)، وابن حبان (2980)، والحاكم (3598) كلهم من حديث الحسن بن عرفة، حدثني عبدالرحمن بن محمد المحاربي، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أعمار أمة محمد ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3550), Ibn Mājah (4236), Ibn Ḥibbān (2980), and al-Ḥākim (3598).","chapter_en":"What Has Been Narrated Concerning the Lifespans of the Ummah of Muḥammad ﷺ","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The lifespans of my Ummah are generally between sixty and seventy years, and few of them will exceed that.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13143],"tks":"حسن: رواه الترمذي (3550)، وابن ماجه (4236)، وابن حبان (2980)، والحاكم (3598)."},{"num":15137,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَعْذَرَ اللَّهُ إِلَى امْرِئٍ أَخَّرَ أَجَلَهُ حَتَّى بَلَّغَهُ سِتِّينَ سَنَةً."],"takhrij":"صحيح: رواه البخاري في الرقاق (6419) عن عبد السلام بن مطهر، حدثنا عمر بن علي، عن معن بن محمد الغفاري، عن سعيد بن أبي سعيد المقبري، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب انقطاع العذر بعد ستين سنة","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6419).","chapter_en":"Excuse Is Cut Off after Sixty Years","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Allah has left no excuse for a person whose life He prolongs until he reaches sixty years of age.”"]},"buhuth":{"en":["In another narration recorded by Aḥmad (7713), through a different route from Saʿīd al-Maqburī, from Abū Hurayrah:","“Allah has truly left no excuse for a servant whom He allows to live until sixty or seventy years of age. Allah has indeed left him no excuse; Allah has indeed left him no excuse.”","The meaning of the hadith is that if a servant reaches sixty years of age and still does not repent from sin, he has no excuse before Allah for persisting in disobedience."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13142],"tks":"صحيح: رواه البخاري (6419)."},{"num":15138,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  انْظُرُوا إِلَى مَنْ أَسْفَلَ مِنْكُمْ، وَلَا تَنْظُرُوا إِلَى مَنْ هُوَ فَوْقَكُمْ، فَهُوَ أَجْدَرُ أَنْ لَا تَزْدَرُوا نِعْمَةَ اللَّهِ قَالَ أَبُو مُعَاوِيَةَ: عَلَيْكُمْ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (9:2963) من طرق عن الأعمش، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب على المسلم أن ينظر في الدين إلى من فوقه، وفي الدنيا إلى من هو أسفل منه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2963:9).","chapter_en":"A Muslim Should Look in Religion to Those above Him, and in Worldly Matters to Those below Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Look at those who are below you, and do not look at those who are above you, for that is more likely to keep you from belittling Allah’s blessing upon you.”"]},"buhuth":{"en":["The words “look at those who are below you” refer to worldly matters. As for matters of religion, a person should look to those who are above him.","The word “tazdarū” means to regard as insignificant or belittle."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (9:2963)."},{"num":15139,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ إِذَا نَظَرَ أَحَدُكُمْ إِلَى مَنْ فُضِّلَ عَلَيْهِ فِي الْمَالِ وَالْخَلْقِ، فَلْيَنْظُرْ إِلَى مَنْ هُوَ أَسْفَلَ مِنْهُ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6490)، ومسلم في الزهد (8:2963) كلاهما من طريق أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب على المسلم أن ينظر في الدين إلى من فوقه، وفي الدنيا إلى من هو أسفل منه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6490) and Muslim (2963:8).","chapter_en":"A Muslim Should Look in Religion to Those above Him, and in Worldly Matters to Those below Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “If one of you looks at someone who has been given more than him in wealth or physical appearance, let him look at someone below him over whom he himself has been favored.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6490)، ومسلم (8:2963)."},{"num":15140,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذرّ قَالَ: أَمَرَنِي خَلِيلِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْعٍ: وَمِنْهَا: أَمَرَنِي أَنْ أَنْظُرَ إِلَى مَنْ هُوَ دُونِي، وَلَا أَنْظُرَ إِلَى مَنْ هُوَ فَوْقِي."],"takhrij":"صحيح: رواه أحمد (21415)، والنسائي في عمل اليوم والليلة (354)، وصحّحه ابن حبّان (449)، والطبراني في الدعاء (1648) كلهم من حديث محمد بن واسع، عن عبدالله بن الصامت، عن أبي ذرّ فذكره في حديث طويل وهو مخرج في تفسير سورة المائدة آية (54). وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب على المسلم أن ينظر في الدين إلى من فوقه، وفي الدنيا إلى من هو أسفل منه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (21415), al-Nasā’ī in ʿAmal al-Yawm wa-al-Laylah (354), authenticated by Ibn Ḥibbān (449), and al-Ṭabarānī in al-Duʿāʾ (1648).","chapter_en":"A Muslim Should Look in Religion to Those above Him, and in Worldly Matters to Those below Him","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Abū Dharr narrated: The Prophet ﷺ, my beloved friend, instructed me with seven things. Among them was: “He instructed me to look at those who are below me and not to look at those who are above me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (21415)، والنسائي في عمل اليوم والليلة (354)، وصححه ابن حبان (449)، والطبراني في الدعاء (1648)."},{"num":15141,"demo":false,"sanad":"","matn":["عن ابْنِ أبان أَخْبَرَهُ قَالَ أَتَيْتُ عُثْمَانَ بِطَهُورٍ وَهْوَ جَالِسٌ عَلَى الْمَقَاعِدِ، فَتَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ قَالَ رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ وَهْوَ فِي هَذَا الْمَجْلِسِ، فَأَحْسَنَ الْوُضُوءَ ثُمَّ قَالَ مَنْ تَوَضَّأَ مِثْلَ هَذَا الْوُضُوءِ، ثُمَّ أَتَى الْمَسْجِدَ فَرَكَعَ رَكْعَتَيْنِ، ثُمَّ جَلَسَ، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ. قَالَ وَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَغْتَرُّوا."],"takhrij":"صحيح: رواه البخاري في الرقاق (6433) عن سعد بن حفص، حدثنا شيبان، عن يحيى، عن محمد بن إبراهيم القرشي قال: أخبرني معاذ بن عبدالرحمن أن ابن أبان أخبره فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من الاغترار بالعمل الصالح","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6433).","chapter_en":"Warning against Being Deceived by One’s Righteous Deeds","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Ibn Abān narrated: I brought water for ʿUthmān ibn ʿAffān while he was sitting at al-Maqāʿid. He performed wuḍūʾ and perfected it. Then he said: “I saw the Prophet ﷺ perform wuḍūʾ while sitting in this very place, and he perfected his wuḍūʾ.” Then the Prophet ﷺ said: “Whoever performs wuḍūʾ like this, then comes to the mosque, prays two rakʿahs, and then sits, his previous sins will be forgiven.” Then the Prophet ﷺ said: “Do not become deceived by this.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6433)."},{"num":15142,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَنْ يُدْخِلَ أَحَدًا عَمَلُهُ الْجَنَّةَ قَالُوا: وَلاَ أَنْتَ يَا رَسُولَ اللَّهِ؟ قَالَ: لاَ، وَلاَ أَنَا، إِلاَّ أَنْ يَتَغَمَّدَنِي اللَّهُ بِفَضْلٍ وَرَحْمَةٍ، فَسَدِّدُوا وَقَارِبُوا، وَلاَ يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ، إِمَّا مُحْسِنًا فَلَعَلَّهُ أَنْ يَزْدَادَ خَيْرًا، وَإِمَّا مُسِيئًا فَلَعَلَّهُ أَنْ يَسْتَعْتِبَ."],"takhrij":"متفق عليه: رواه البخاري في المرضى (5673) عن أبي اليمان، أخبرنا شعيب، عن الزهري قال: أخبرني أبو عبيد مولى عبد الرحمن بن عوف، أن أبا هريرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب لن ينجو أحد بعمله ولا يدخل الجنة","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5673) and Muslim (2816).","chapter_en":"No One Will Be Saved by His Deeds Alone, Nor Enter Paradise by Them Alone","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Messenger of Allah ﷺ say: “No one’s deeds will cause him to enter Paradise.” They asked: “Not even you, O Messenger of Allah?” He replied: “Not even me, unless Allah envelops me in His favor and mercy. So remain upright and come as close as you can. Let none of you wish for death: if he is doing good, perhaps he will increase in goodness; and if he is doing evil, perhaps he will seek Allah’s pardon and correction.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3528,13140,13611,16338],"tks":"متفق عليه: رواه البخاري (5673)، ومسلم (2816)."},{"num":15143,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَنْ يُنَجِّيَ أَحَدًا مِنْكُمْ عَمَلُهُ. قَالُوا وَلاَ أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلاَ أَنَا، إِلاَّ أَنْ يَتَغَمَّدَنِي اللَّهُ بِرَحْمَةٍ، سَدِّدُوا وَقَارِبُوا، وَاغْدُوا وَرُوحُوا، وَشَىْءٌ مِنَ الدُّلْجَةِ. وَالْقَصْدَ الْقَصْدَ تَبْلُغُوا."],"takhrij":"صحيح: رواه البخاري في الرقاق (6463) عن آدم، عن ابن أبي ذئب، عن سعيد المقبري، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب لن ينجو أحد بعمله ولا يدخل الجنة","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6463).","chapter_en":"No One Will Be Saved by His Deeds Alone, Nor Enter Paradise by Them Alone","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “None of your deeds will save you.” They asked: “Not even you, O Messenger of Allah?” He replied: “Not even me, unless Allah envelops me in mercy. So remain upright and come as close as you can. Worship in the morning, in the evening, and during part of the night. Keep to moderation, keep to moderation, and you will reach your goal.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[103],"tks":"صحيح: رواه البخاري (6463)."},{"num":15144,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَدِّدُوا وَقَارِبُوا وَأَبْشِرُوا فَإِنَّهُ لَنْ يُدْخِلَ الْجَنَّةَ أَحَدًا عَمَلُهُ قَالُوا: وَلَا أَنْتَ يَا رَسُولَ اللَّهِ؟ قَالَ: وَلَا أَنَا، إِلَّا أَنْ يَتَغَمَّدَنِيَ اللَّهُ مِنْهُ بِرَحْمَةٍ، وَاعْلَمُوا أَنَّ أحبّ الْعَمَلِ إِلَى اللَّهِ أَدْوَمُهُ وَإِنْ قلَّ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6467، 6464)، ومسلم في صفة القيامة (2818) كلاهما من طريق موسى بن عقبة، عن أبي سلمة بن عبد الرحمن بن عوف، عن عائشة فذكرته. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب لن ينجو أحد بعمله ولا يدخل الجنة","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6464, 6467) and Muslim (2818). The context is that of Muslim.","chapter_en":"No One Will Be Saved by His Deeds Alone, Nor Enter Paradise by Them Alone","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ said: “Remain upright, come as close as you can, and rejoice, for no one’s deeds will cause him to enter Paradise.” They asked: “Not even you, O Messenger of Allah?” He replied: “Not even me, unless Allah envelops me in mercy from Him. And know that the deeds most beloved to Allah are those performed most consistently, even if they are few.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6464، 6467)، ومسلم (2818)، والسياق لمسلم."},{"num":15145,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ إِنَّكُمْ لَتَعْمَلُونَ أَعْمَالاً هِيَ أَدَقُّ فِي أَعْيُنِكُمْ مِنَ الشَّعَرِ، إِنْ كُنَّا نَعُدُّهَا عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُوبِقَاتِ.","قال أبو عبد الله (وهو البخاري): يعني بذلك المهلكات."],"takhrij":"صحيح: رواه البخاري في الرقاق (6492) عن أبي الوليد، حدثنا مهدي، عن غيلان، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من محقرات الذنوب","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6492).","chapter_en":"Warning against Sins That Are Regarded as Insignificant","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Anas said: “You commit deeds that appear in your eyes to be finer than a hair, yet during the time of the Prophet ﷺ we used to count them among the destructive sins.” Abū ʿAbdullāh—meaning al-Bukhārī—said: “By this he means sins that lead to destruction.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6492)."},{"num":15146,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِيَّاكُمْ وَمُحَقَّرَاتِ الذُّنُوبِ، كَقَوْمٍ نَزَلُوا فِي بَطْنِ وَادٍ، فَجَاءَ ذَا بِعُودٍ، وَجَاءَ ذَا بِعُودٍ، حَتَّى أَنْضَجُوا خُبْزَتَهُمْ، وَإِنَّ مُحَقَّرَاتِ الذُّنُوبِ مَتَى يُؤْخَذْ بِهَا صَاحِبُهَا تُهْلِكْهُ."],"takhrij":"صحيح: رواه أحمد (22808)، والرامهرمزي في الأمثال (67)، والبيهقي في الشعب (7267) كلهم من طريق أنس بن عياض، حدثني أبو حازم، عن سهل بن سعد قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب التحذير من محقرات الذنوب","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (22808), al-Rāmahurmuzī in al-Amthāl (67), and al-Bayhaqī in Shuʿab al-Īmān (7267).","chapter_en":"Warning against Sins That Are Regarded as Insignificant","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Sahl ibn Saʿd narrated that the Messenger of Allah ﷺ said: “Beware of sins that are regarded as insignificant. They are like a group of people who camp in the bottom of a valley: one man brings a stick, another brings a stick, until together they gather enough to cook their bread. Likewise, when a person is taken to account for seemingly insignificant sins, they can destroy him.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (22808)، والرامهرمزي في الأمثال (67)، والبيهقي في الشعب (7267)."},{"num":15147,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ، الصِّحَّةُ وَالْفَرَاغُ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6412) عن المكي بن إبراهيم، أخبرنا عبدالله بن سعيد (وهو ابن أبي هند)، عن أبيه، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب اغتنام الصحة والفراغ قبل فوات الأوان","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6412).","chapter_en":"Taking Advantage of Health and Free Time before the Opportunity Is Lost","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":26,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated that the Prophet ﷺ said: “There are two blessings in which many people suffer loss: health and free time.”"]}},"tuhfa":{},"full":1,"rep":[11535],"tks":"صحيح: رواه البخاري (6412)."},{"num":15148,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ الْعَاصِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَا عَلِمْتَ أَنَّ الإِسْلَامَ يَهْدِمُ ، مَا كَانَ قَبْلَهُ وَأَنَّ الْهِجْرَةَ تَهْدِمُ مَا كَانَ قَبْلِهَا ، وَأَنَّ الْحَجَّ يَهْدِمُ مَا كَانَ قَبْلَهُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (192:121) من طرق عن حيوة بن شريح، حدثني يزيد بن أبي حبيب، عن ابن شماسة المهري، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب إن الإسلام يهدم ما كان قبله إلا من أساء","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (121:192).","chapter_en":"Islam Erases What Came before It, Except in the Case of One Who Later Does Evil","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":27,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated: The Messenger of Allah ﷺ said to me: “Do you not know that Islam wipes away what came before it, that migration wipes away what came before it, and that Ḥajj wipes away what came before it?”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (192:121)."},{"num":15149,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ قَالَ:  قَالَ أُنَاسٌ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ اللَّهِ، أَنُؤَاخَذُ بِمَا عَمِلْنَا فِي الْجَاهِلِيَّةِ؟ قَالَ: أَمَّا مَنْ أَحْسَنَ مِنْكُمْ فِي الْإِسْلَامِ فَلَا يُؤَاخَذُ بِهَا، وَمَنْ أَسَاءَ أُخِذَ بِعَمَلِهِ فِي الْجَاهِلِيَّةِ وَالْإِسْلَامِ."],"takhrij":"متفق عليه: رواه البخاري في استتابة المرتدّين والمعاندين وقتالهم (6921)، ومسلم في الإيمان (189:120) كلاهما من طريق منصور عن أبي وائـل، عن عبد الله بن مسعود فذكره.","grade":"متفق عليه","chapter_ar":"باب إن الإسلام يهدم ما كان قبله إلا من أساء","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6921) and Muslim (120:189).","chapter_en":"Islam Erases What Came before It, Except in the Case of One Who Later Does Evil","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":27,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: Some people asked the Messenger of Allah ﷺ: “O Messenger of Allah, will we be held accountable for what we did during jāhiliyyah?” He replied: “Whoever among you does well after entering Islam will not be taken to account for those deeds. But whoever does evil will be taken to account for what he did both in jāhiliyyah and in Islam.”"]},"buhuth":{"en":["The reconciliation between the two hadiths is that the first refers to one who remains firm upon Islam.","The second contains an indication concerning apostasy or shirk: if a person apostatizes or commits shirk, he may be taken to account for the evil deeds he committed both during jāhiliyyah and after entering Islam.","Al-Bukhārī included this narration in his chapter concerning seeking repentance from apostates."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6921)، ومسلم (189:120)."},{"num":15150,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ ثَلَاثَةً فِي بَنِي إِسْرَائِيلَ، أَبْرَصَ وَأَقْرَعَ وَأَعْمَى، فَأَرَادَ اللهُ أَنْ يَبْتَلِيَهُمْ، فَبَعَثَ إِلَيْهِمْ مَلَكًا، فَأَتَى الْأَبْرَصَ فَقَالَ: أيّ شَيْءٍ أَحَبُّ إِلَيْكَ؟ قَالَ: لونٌ حَسَنٌ وَجِلْدٌ حَسَنٌ وَيَذْهَبُ عَنِّي الَّذِي قَدْ قَذِرَنِي النَّاسُ، قَالَ: فَمَسَحَهُ فَذَهَبَ عَنْهُ قذَرُه، وَأُعْطِيَ لَوْنًا حَسَنًا وَجِلْدًا حَسَنًا، قَالَ: فأيّ الْمَالِ أَحَبُّ إِلَيْكَ؟ قَالَ: الْإِبِلُ -أَوْ قَالَ: الْبَقَرُ-، شَكَّ إِسْحَاقُ، إِلَّا أَنَّ الْأَبْرَصَ أوالأقرع قَالَ أَحَدُهُمَا: الْإِبِلُ، وَقَالَ الْآخَرُ: الْبَقَرُ – قَالَ: فأُعطيَ نَاقَةً عُشَراء، فَقَالَ: بَارَكَ اللَّهُ لَكَ فِيهَا، قَالَ: فَأَتَى الْأَقْرَعَ فَقَالَ: أيّ شَيْءٍ أَحَبُّ إِلَيْكَ؟ قَالَ: شعرٌ حسنٌ وَيَذْهَبُ عنّي هَذَا الَّذِي قَذِرَنِي النَّاسُ، قَالَ: فَمَسَحَهُ فَذَهَبَ عَنْهُ، وأُعطيَ شَعَرًا حَسَنًا، قَالَ: فأيّ الْمَالِ أَحَبُّ إِلَيْكَ؟ قَالَ: الْبَقَرُ، فَأُعْطِيَ بَقَرَةً حَامِلًا، فَقَالَ: بَارَكَ اللَّهُ لَكَ فِيهَا، قَالَ: فَأَتَى الْأَعْمَى فَقَالَ: أيّ شَيْءٍ أَحَبُّ إِلَيْكَ؟ قَالَ: أَنْ يردّ اللَّهُ إِلَيَّ بَصَرِي فَأُبْصِرَ بِهِ النَّاسَ، قَالَ: فَمَسَحَهُ فردّ اللَّهُ إِلَيْهِ بَصَرَهُ، قَالَ: فأيّ الْمَالِ أَحَبُّ إِلَيْكَ؟ قَالَ: الْغَنَمُ، فَأُعْطِيَ شاةً وَالِدًا، فَأُنْتِجَ هَذَانِ وَوَلَّدَ هَذَا، قَالَ: فَكَانَ لِهَذَا وادٍ مِنَ الْإِبِلِ، وَلِهَذَا وادٍ مِنَ الْبَقَرِ، وَلِهَذَا وادٍ مِنَ الْغَنَمِ.","قَالَ: ثُمَّ إِنَّهُ أَتَى الْأَبْرَصَ فِي صُورَتِهِ وَهَيْئَتِهِ، فَقَالَ: رَجُلٌ مِسْكِينٌ، قَدِ انْقَطَعَتْ بِيَ الْحِبَالُ فِي سَفَرِي، فَلَا بَلَاغَ لِيَ الْيَوْمَ إِلَّا بِاللهِ ثُمَّ بِكَ، أَسْأَلُكَ بِالَّذِي أَعْطَاكَ اللَّوْنَ الْحَسَنَ وَالْجِلْدَ الْحَسَنَ وَالْمَالَ، بَعِيرًا أَتَبَلَّغُ عَلَيْهِ فِي سَفَرِي، فَقَالَ: الْحُقُوقُ كَثِيرَةٌ، فَقَالَ لَهُ: كَأَنِّي أَعْرِفُكَ، أَلَمْ تَكُنْ أَبْرَصَ يَقْذَرُكَ النَّاسُ؟ فَقِيرًا فَأَعْطَاكَ اللهُ؟ فَقَالَ: إِنَّمَا وَرِثْتُ كَابِرًا عَنْ كَابِرٍ، فَقَالَ: إِنْ كُنْتَ كَاذِبًا، فَصَيَّرَكَ اللهُ إِلَى مَا كُنْتَ.","قَالَ: وَأَتَى الْأَقْرَعَ فِي صُورَتِهِ، فَقَالَ لَهُ مِثْلَ مَا قَالَ لِهَذَا، وَرَدَّ عَلَيْهِ مِثْلَ مَا رَدَّ عَلَى هَذَا، فَقَالَ: إِنْ كُنْتَ كَاذِبًا فَصَيَّرَكَ اللهُ إِلَى مَا كُنْتَ.","قَالَ: وَأَتَى الْأَعْمَى فِي صُورَتِهِ وَهَيْئَتِهِ، فَقَالَ: رَجُلٌ مِسْكِينٌ وَابْنُ سَبِيلٍ، انْقَطَعَتْ بِيَ الْحِبَالُ فِي سَفَرِي، فَلَا بَلَاغَ لِيَ الْيَوْمَ إِلَّا بِاللهِ ثُمَّ بِكَ، أَسْأَلُكَ بِالَّذِي رَدَّ عَلَيْكَ بَصَرَكَ، شَاةً أَتَبَلَّغُ بِهَا فِي سَفَرِي، فَقَالَ: قَدْ كُنْتُ أَعْمَى فَرَدَّ اللهُ إِلَيَّ بَصَرِي، فَخُذْ مَا شِئْتَ، وَدَعْ ماشئت، فَوَاللهِ لَا أَجْهَدُكَ الْيَوْمَ شَيْئًا أَخَذْتَهُ لِلهِ، فَقَالَ: أَمْسِكْ مَالَكَ، فَإِنَّمَا ابْتُلِيتُمْ، فَقَدْ رُضِيَ عَنْكَ وَسُخِطَ عَلَى صَاحِبَيْكَ."],"takhrij":"متفق عليه: رواه البخاري في الأنبياء (3464)، ومسلم في الزهد والرقائق (2964) كلاهما من طريق همّام، عن إسحاق بن عبد الله بن أبي طلحة، عن عبدالرحمن بن أبي عمرة، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب الشكر على نعمة اللّٰه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3464) and Muslim (2964).","chapter_en":"Gratitude for the Blessing of Allah","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":28,"content":{"translation":{"en":["Abū Hurayrah narrated that he heard the Prophet ﷺ say: “There were three men among the Children of Israel: a leper, a bald man, and a blind man. Allah wished to test them, so He sent an angel to them. The angel came to the leper and asked: ‘What would you love most?’ He replied: ‘A beautiful complexion, healthy skin, and that this condition because of which people find me repulsive be removed from me.’ The angel touched him, his affliction disappeared, and he was given beautiful skin and a fine complexion. The angel asked: ‘What kind of wealth do you love most?’ He replied: ‘Camels’—or he said: ‘Cattle.’” Isḥāq, one of the narrators, was uncertain, except that one of the leper and the bald man said camels and the other said cattle. “He was given a pregnant she-camel and the angel said: ‘May Allah bless it for you.’ Then he came to the bald man and asked: ‘What would you love most?’ He replied: ‘Beautiful hair and that this condition because of which people find me repulsive be removed from me.’ The angel touched him, his affliction disappeared, and he was given beautiful hair. He asked: ‘What kind of wealth do you love most?’ He replied: ‘Cattle.’ So he was given a pregnant cow, and the angel said: ‘May Allah bless it for you.’ Then he came to the blind man and asked: ‘What would you love most?’ He replied: ‘That Allah restore my sight so that I may see people.’ The angel touched him, and Allah restored his sight. He asked: ‘What kind of wealth do you love most?’ He replied: ‘Sheep.’ So he was given a sheep that was giving birth.” The animals multiplied until the first had a valley full of camels, the second a valley full of cattle, and the third a valley full of sheep. “Then the angel came to the former leper in the same appearance and condition that the man had once had. He said: ‘I am a poor traveler whose means have been cut off during my journey. Today I have no means of reaching my destination except through Allah and then through you. I ask you by the One who gave you beautiful skin, a fine complexion, and wealth to give me a camel upon which I may continue my journey.’","The man replied: ‘There are many obligations upon my wealth.’ The angel said: ‘I think I recognize you. Were you not once a leper whom people found repulsive, poor, and then Allah gave you wealth?’ He replied: ‘I merely inherited this wealth from my forefathers.’ The angel said: ‘If you are lying, may Allah return you to what you were.’ Then he came to the former bald man in his previous appearance and said the same thing to him. The man responded in the same way, so the angel said: ‘If you are lying, may Allah return you to what you were.’","Then he came to the former blind man in the same appearance and condition that he had once had. He said: ‘I am a poor traveler whose means have been cut off during my journey. Today I have no means of reaching my destination except through Allah and then through you. I ask you by the One who restored your sight to give me one sheep by which I may continue my journey.’ The man replied: ‘I was indeed blind, and Allah restored my sight. Take whatever you wish and leave whatever you wish. By Allah, today I will not make things difficult for you concerning anything you take for the sake of Allah.’","The angel said: ‘Keep your wealth. You were only being tested. Allah is pleased with you and angry with your two companions.’”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿لَئِنْ شَكَرْتُمْ لَأَزِيدَنَّكُمْ وَلَئِنْ كَفَرْتُمْ إِنَّ عَذَابِي لَشَدِيدٌ﴾ [إبراهيم: ٧]."],"en":["Allah, the Exalted, says:","“If you are grateful, I will surely increase you; but if you are ungrateful, indeed My punishment is severe.”","[Sūrat Ibrāhīm 14:7]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3464)، ومسلم (2964)."},{"num":15151,"demo":false,"sanad":"","matn":["عَنْ عَبْدَ الرَّحْمَنِ بْنَ أبي ليلى يقول: حَدَّثَنَا فُلَانٌ رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم أَنَّهُ سمع النبي صلى الله عليه وسلم يقول: فَذَكَرَ حَدِيثًا، قَالَ: وقال رَسُولُ اللَّهِ صلى الله عليه وسلم: تجتمع مَلَائِكَةُ اللَّيْلِ وَمَلَائِكَةُ النَّهَارِ فِي صَلَاةِ الْعَصْرِ وَصَلَاةِ الصُّبْحِ، فَتَصْعَدُ مَلَائِكَةُ النَّهَارِ فِي صَلَاةِ الْعَصْرِ، وتبقى فِيكُمْ مَلَائِكَةُ اللَّيْلِ، وَتَصْعَدُ مَلَائِكَةُ اللَّيْلِ فِي صَلَاةِ الصُّبْحِ، وَتَبْقَى فِيكُمْ مَلَائِكَةُ النَّهَارِ، وَيَقُولُونَ: أَتَيْنَاهُمْ وَهُمْ يُصَلُّونَ، وَتَرَكْنَاهُمْ وَهُمْ يُصَلُّونَ، وَتَرَكْنَا فِيهِمْ رَجُلًا لَمْ يُصِبْهُ خَيْرٌ قَطُّ، وَلَا بَلَاءٌ قَطُّ، إِلَّا عَلِمَ أَنَّهُ مِنْكَ، فَيَقُولُ: ابتلوا عبدي، أو زيدوا عَبْدِي قَالَ سفيان: لا أدري بأيتهما بدأ، قال: فَيَبْتَلُونَهُ، ثُمَّ يَقُولُ: ابْتَلُوهُ فَيُبْتَلَى، ثُمَّ يَقُولُ: ابْتَلُوهُ وَهُوَ أَعْلَمُ، فَيَقُولُونَ: انْتَهَى الْبَلَاءُ أَيْ رَبِّ، فَيَقُولُ: زِيدُوهُ، فَيُزَادُ، ثُمَّ يَقُولُ: زِيدُوهُ، فَيُزَادُ، ثُمَّ يقول: زيدوه، فيزاد، ثم يَقُولُ: زِيدُوهُ وَهُوَ أَعْلَمُ، فَيَقُولُونَ: انْتَهَى الْمَزِيدُ أَيْ رَبِّ، فَيَقُولُ: كَيْفَ تَرَكْتُمْ عَبْدِي فِي الْبَلَاءِ، وَكَيْفَ رأيتموه فِي الرَّخَاءِ؟ فَيَقُولُونَ: أَيْ رَبِّ، أَصْبَرَ عَبْدٍ وأشكره، فَيَقُولُ: اكْتُبُوا عَبْدِي مِمَّنْ لَا يُبَدَّلُ وَلَا يُغَيَّرُ، حَتَّى يَلْقَانِي."],"takhrij":"صحيح: رواه ابن أبي عمر العدني في مسنده كما في المطالب العالية (3140) عن سفيان (هو ابن عيينة)، عن عطاء بن السائب قال: سمعت عبد الرحمن بن أبي ليلى يقول: فذكره.","grade":"صحيح","chapter_ar":"باب الشكر على نعمة اللّٰه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Abī ʿUmar al-ʿAdanī in his Musnad, as cited in al-Maṭālib al-ʿĀliyah (3140).","chapter_en":"Gratitude for the Blessing of Allah","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":28,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Abī Laylā said: A man from among the Companions of the Prophet ﷺ narrated to us that he heard the Prophet ﷺ mention a hadith. The Messenger of Allah ﷺ said: “The angels of the night and the angels of the day gather at the ʿAṣr prayer and the Fajr prayer. The angels of the day ascend at ʿAṣr, while the angels of the night remain with you. The angels of the night ascend at Fajr, while the angels of the day remain with you. They say: ‘We came to them while they were praying, and we left them while they were praying.’ And they leave among them a man who has never experienced any good or any affliction except that he knows it is from You. Allah says: ‘Test My servant,’ or, ‘Increase the trial of My servant.’” Sufyān said: “I do not know which expression he began with.” The hadith continues: “So they test him, then He says: ‘Test him further.’ He is tested, then He says: ‘Test him further.’ Though He knows best, they finally say: ‘The trial has reached its limit, O Lord.’ He says: ‘Increase it.’ So it is increased. Then He says: ‘Increase it.’ So it is increased. Then He says: ‘Increase it.’ So it is increased. Then He says: ‘Increase it.’” Though He knows best, they say: “The increase has reached its limit, O Lord.” Then He says: “How did you leave My servant during affliction, and how did you find him during ease?” They reply: “O Lord, he was among the most patient of servants and among the most grateful.” Allah says: “Write My servant among those who neither change nor alter until he meets Me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن أبي عمر العدني في مسنده كما في المطالب العالية (3140)."},{"num":15152,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: بَيْنَمَا رَجُلٌ وَامْرَأَةٌ لَهُ فِي السَّلَفِ الْخَالِي، لَا يَقْدِرَانِ عَلَى شَيْءٍ، فَجَاءَ الرَّجُلُ مِنْ سَفَرِهِ، فَدَخَلَ عَلَى امْرَأَتِهِ جَائِعًا، قَدْ أَصَابَتْهُ مَسْغَبَةٌ شَدِيدَةٌ، فَقَالَ لِامْرَأَتِهِ: أَعِنْدَكِ شَيْءٌ؟ قَالَتْ: نَعَمْ، أَبْشِرْ أَتَاكَ رِزْقُ اللهِ، فَاسْتَحَثَّهَا، فَقَالَ: وَيْحَكِ، ابْتَغِي إِنْ كَانَ عِنْدَكِ شَيْءٌ، قَالَتْ: نَعَمْ، هُنَيَّةً، نَرْجُو رَحْمَةَ اللَّهِ، حَتَّى إِذَا طَالَ عَلَيْهِ الطَّوَل، قَالَ: وَيْحَكِ، قُومِي، فَابْتَغِي إِنْ كَانَ عِنْدَكِ خُبْزٌ، فَأْتِينِي بِهِ، فَإِنِّي قَدْ بَلَغْتُ وَجَهِدْتُ، فَقَالَتْ: نَعَمْ، الْآنَ يَنْضَجُ التَّنُّورُ فَلَا تَعْجَلْ، فَلَمَّا أَنْ سَكَتَ عَنْهَا سَاعَةً، وَتَحَيَّنَتْ أَيْضًا أَنْ يَقُولَ لَهَا، قَالَتْ هِيَ مِنْ عِنْدِ نَفْسِهَا: لَوْ قُمْتُ فَنَظَرْتُ إِلَى تَنُّورِي، فَقَامَتْ فَوَجَدَتْ تَنُّورَهَا مَلْآنَ جُنُوبَ الْغَنَمِ، وَرَحْيَيْهَا تَطْحَنَانِ، فَقَامَتْ إِلَى الرَّحَى فَنَفَضَتْهَا وَإستَخْرَجَتْ مَا فِي تَنُّورِهَا مِنْ جُنُوبِ الْغَنَمِ.","قَالَ أَبُو هُرَيْرَةَ: فَوَالَّذِى نَفْسُ أَبِى الْقَاسِمِ بِيَدِهِ عَنْ قَوْلِ مُحَمَّدٍ صلى الله عليه وسلم: لَوْ أَخَذَتْ مَا فِى رَحْيَيْهَا وَلَمْ تَنْفُضْهَا لَطَحَنَتْهَا إِلَى يَوْمِ الْقِيَامَة."],"takhrij":"حسن: رواه أحمد (9464) عن هاشم بن القاسم قال: حدثنا عبد الحميد يعني ابن بهرام، قال: حدثنا شهر بن حوشب قال: فذكره.","grade":"حسن","chapter_ar":"باب فيمن صبر على العيش الشديد","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (9464).","chapter_en":"Concerning One Who Patiently Endures Severe Hardship in Living","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Abū Hurayrah narrated: There was once, in a former time, a man and his wife who possessed nothing. The man returned from a journey and entered upon his wife while extremely hungry, having been struck by severe hunger. He asked her: “Do you have anything?” She replied: “Yes. Rejoice, for Allah’s provision has come to you.” He urged her to hurry and said: “What is the matter with you? Bring whatever you have.” She replied: “Yes, just a little while. We hope for Allah’s mercy.” When the wait became long for him, he said: “Come now. If you have any bread, bring it to me, for I have reached the limit of hunger and exhaustion.” She replied: “Yes. The oven is just now finishing. Do not rush.” After he remained silent for a while and she expected him to ask again, she herself said: “Why do you not get up and look at my oven?” She went to the oven and found it filled with sides of meat, while her two millstones were grinding by themselves. She went to the millstones and emptied out what they had ground, then took from her oven the sides of meat that were there. Abū Hurayrah said: By the One in whose Hand is the soul of Abū al-Qāsim, Muḥammad ﷺ said: “Had she taken what was in the two millstones without emptying them out, they would have continued grinding for her until the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (9464)."},{"num":15153,"demo":false,"sanad":"","matn":["عَنْ صُهَيْبٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  عَجَبًا لِأَمْرِ الْمُؤْمِنِ، إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ، وَلَيْسَ ذَاكَ لِأَحَدٍ إِلَّا لِلْمُؤْمِنِ، إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ، وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْرًا لَهُ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (2999) من طرق عن سليمان بن المغيرة، عن ثابت، عن عبد الرحمن بن أبي ليلى، عن صهيب فذكره.","grade":"صحيح","chapter_ar":"باب أن أمر المؤمن كله خير","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2999).","chapter_en":"All of the Believer’s Affair Is Good","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في فضل الزهد والرقاق","group_en":"Collection of What Has Been Narrated Concerning the Virtue of Asceticism and Heart-Softening Matters","part_no":62,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Ṣuhayb narrated that the Messenger of Allah ﷺ said: “How remarkable is the affair of the believer! All of his affair is good, and that is true for no one except the believer. If prosperity comes to him, he is grateful, and that is good for him. If hardship comes to him, he is patient, and that is good for him.”"]}},"tuhfa":{},"full":1,"rep":[3436,12528,12547,12999,13114],"tks":"صحيح: رواه مسلم (2999)."},{"num":15154,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اللَّهُمَّ لاَ عَيْشَ إِلاَّ عَيْشُ الآخِرَة، فَأَصْلِحِ الأَنْصَارَ وَالْمُهَاجِرَة."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6413)، ومسلم في الجهاد والسير (1805) كلاهما من طريق محمد بن جعفر غندر، عن شعبة، عن معاوية بن قرة، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب أن لا عيش إلا عيش الآخرة","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6413) and Muslim (1805).","chapter_en":"There Is No True Life Except the Life of the Hereafter","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “O Allah, there is no true life except the life of the Hereafter, so set right the Anṣār and the Muhājirūn.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6413)، ومسلم (1805)."},{"num":15155,"demo":false,"sanad":"","matn":["عن سهل بْنِ سَعْدٍ السَّاعِدِيِّ كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِي الْخَنْدَقِ وَهْوَ يَحْفِرُ، وَنَحْنُ نَنْقُلُ التُّرَابَ، وَيَمُرُّ بِنَا، فَقَالَ: اللَّهُمَّ لاَ عَيْشَ إِلاَّ عَيْشُ الآخِرَهْ، فَاغْفِرْ لِلأَنْصَارِ وَالْمُهَاجِرَهْ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6414)، ومسلم في الجهاد والسير (1804) كلاهما من طريق أبي حازم، عن سهل بن سعد فذكره.","grade":"متفق عليه","chapter_ar":"باب أن لا عيش إلا عيش الآخرة","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6414) and Muslim (1804).","chapter_en":"There Is No True Life Except the Life of the Hereafter","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Sahl ibn Saʿd al-Sāʿidī said: “We were with the Messenger of Allah ﷺ while he was digging, and we were carrying away the earth. As he passed by us, he said: ʿO Allah, there is no true life except the life of the Hereafter, so forgive the Anṣār and the Muhājirūn.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6414)، ومسلم (1804)."},{"num":15156,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  اللَّهُمَّ اجْعَلْ رِزْقَ آلِ مُحَمَّدٍ قُوتًا. وَفِي رِوَايَةِ: عَمْرٍو:"],"takhrij":"متفق عليه: رواه البخاري في الرقاق (4836)، ومسلم في الزهد والرقائق (1055: 18-20) كلاهما من طرق عن عمارة بن القعقعاع، عن أبي زرعة، عن أبي هريرة فذكره. والرواية الثانية لمسلم.","grade":"متفق عليه","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6460) and Muslim (1055:18–20); the second wording is narrated by Muslim.","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “O Allah, make the provision of the family of Muḥammad just enough to sustain them.” In another narration: “Sufficient for their needs.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4836)، ومسلم (1055: 18-20)، والرواية الثانية لمسلم."},{"num":15157,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ بِيَدِهِ، مَا شَبِعَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَهْلُهُ ثَلَاثَةَ أَيَّامٍ تِبَاعًا مِنْ خُبْزِ حِنْطَةٍ حَتَّى فَارَقَ الدُّنْيَا."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5374)، ومسلم في الزهد والرقائق (2976) كلاهما من طريق أبي حازم، عن أبي هريرة فذكره، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5374) and Muslim (2976). The wording is that of Muslim.","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah said: “By the One in whose Hand is my soul, the Prophet of Allah ﷺ and his family never ate their fill of wheat bread for three consecutive days until he departed from this world.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5374)، ومسلم (2976)، واللفظ لمسلم."},{"num":15158,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: مَا شَبِعَ آلُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُنْذُ قَدِمَ الْمَدِينَةَ مِنْ طَعَامِ بُرٍّ ثَلاَثَ لَيَالٍ تِبَاعًا حَتَّى قُبِضَ.","وفي رواية عنها قَالَتْ: مَا شَبِعَ آلُ مُحَمَّدٍ صلى الله عليه وسلم مِنْ خُبْزِ شَعِيرٍ يَوْمَيْنِ مُتَتَابِعَيْنِ حَتَّى قُبِضَ رَسُولُ اللهِ صلى الله عليه وسلم."],"takhrij":"متفق عليه: رواه البخاريّ في الرقاق (6454)، ومسلم في الزهد والرقائق (20:2970) كلاهما من طريق جرير، عن منصور، عن إبراهيم، عن الأسود، عن عائشة فذكرته. ورواه مسلم (22:2970) من طريق عبد الرحمن بن يزيد، عن الأسود، عن عائشة باللفظ الثاني.","grade":"متفق عليه","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6454) and Muslim (2970:20). Muslim also narrated the second wording (2970:22).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated: “From the time Muḥammad ﷺ came to Madinah until he died, the family of Muḥammad ﷺ never ate their fill of wheat food for three consecutive nights.”","In another narration, she said: “The family of Muḥammad ﷺ never ate their fill of barley bread for two consecutive days until the Messenger of Allah ﷺ died.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6454)، ومسلم (20:2970)، ورواه مسلم (22:2970) باللفظ الثاني."},{"num":15159,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  مَا شَبِعَ آلُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ خُبْزِ بُرٍّ فَوْقَ ثَلَاثٍ."],"takhrij":"صحيح: رواه مسلم في الزهد (23:2970) عن أبي بكر بن أبي شيبة، حدثنا وكيع، عن سفيان، عن عبد الرحمن بن عابس، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2970:23).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The family of Muḥammad ﷺ never ate their fill of wheat bread for more than three days.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (23:2970)."},{"num":15160,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا أَكَلَ آلُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكْلَتَيْنِ فِي يَوْمٍ، إِلاَّ إِحْدَاهُمَا تَمْرٌ.","وفي رواية عنها قالت: ما شبع آل محمد صلى الله عليه وسلم يومين من خبز برّ إلا وأحدهما تمر."],"takhrij":"متفق عليه: رواه البخاريّ في الرقاق (6455)، من طريق إسحاق الأزرق، عن مسعر بن كدام، عن هلال (هو ابن حميد)، عن عروة، عن عائشة فذكرته. باللفظ الأول.","grade":"متفق عليه","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6455) with the first wording, and Muslim (2971) with the second.","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The family of Muḥammad ﷺ never ate two meals in one day except that one of them consisted of dates.” In another narration, she said: “The family of Muḥammad ﷺ never ate their fill of wheat bread for two days except that one of those days they ate dates.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6455) باللفظ الأول، ورواه مسلم (2971) باللفظ الثاني."},{"num":15161,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ:  لَقَدْ مَاتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَا شَبِعَ مِنْ خُبْزٍ وَزَيْتٍ فِي يَوْمٍ وَاحِدٍ مَرَّتَيْنِ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (2974) من طرق عن عبد الله بن وهب، أخبرني أبو صخر، عن يزيد بن عبد الله بن قسيط، عن عروة بن الزبير، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2974).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah, the wife of the Prophet ﷺ, narrated: “The Messenger of Allah ﷺ died without ever having eaten his fill twice in a single day from bread and olive oil.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2974)."},{"num":15162,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ شَبِعْنَا مِنَ الأَسْوَدَيْنِ: التَّمْرِ وَالْمَاءِ. وَفِي رِوَايَةِ: وَمَا شَبِعْنَا مِنَ الأَسْوَدَيْنِ."],"takhrij":"متفق عليه: رواه البخاريّ في الأطعمة (5442)، فقال: قال محمد بن يوسف، عن سفيان، عن منصور بن صفية، حدثتني أمي، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5442) and Muslim (2975:31).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The Messenger of Allah ﷺ died after we had come to have our fill from the two black things: dates and water.” In another narration: “We had not eaten our fill from the two black things.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5442)، ومسلم (2975: 31)."},{"num":15163,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ شَبِعَ النَّاسُ مِنَ الْأَسْوَدَيْنِ: التَّمْرِ وَالْمَاءِ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (30:2975) من طرق عن داود بن عبد الرحمن العطار، حدثني منصور بن عبد الرحمن الحجبي، عن أمه صفية، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2975:30).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The Messenger of Allah ﷺ died at a time when people had begun to eat their fill from the two black things: dates and water.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (30:2975)."},{"num":15164,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ يَأْتِي عَلَيْنَا الشَّهْرُ مَا نُوقِدُ فِيهِ نَارًا، إِنَّمَا هُوَ التَّمْرُ وَالْمَاءُ، إِلاَّ أَنْ نُؤْتَى بِاللُّحَيْمِ."],"takhrij":"متفق عليه: رواه البخاريّ في الرقاق (6458) واللفظ له، ومسلم في الزهد (2927) كلاهما من طريق هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6458), and this is his wording, and Muslim (2972).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated: “A whole month would pass over us without our lighting a fire. Our food was only dates and water, unless some meat was brought to us.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6458) - واللفظ له -، ومسلم (2927)."},{"num":15165,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا كَانَتْ تَقُولُ:  وَاللهِ يَا ابْنَ أُخْتِي إِنْ كُنَّا لَنَنْظُرُ إِلَى الْهِلَالِ، ثُمَّ الْهِلَالِ، ثُمَّ الْهِلَالِ، ثَلَاثَةَ أَهِلَّةٍ فِي شَهْرَيْنِ، وَمَا أُوقِدَ فِي أَبْيَاتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَارٌ. قَالَ: قُلْتُ: يَا خَالَةُ، فَمَا كَانَ يُعَيِّشُكُمُْ؟ قَالَتِ: الْأَسْوَدَانِ: التَّمْرُ وَالْمَاءُ، إِلَّا أَنَّهُ قَدْ كَانَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جِيرَانٌ مِنَ الْأَنْصَارِ، وَكَانَتْ لَهُمْ مَنَائِحُ، فَكَانُوا يُرْسِلُونَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ أَلْبَانِهَا، فَيَسْقِينَاهُ."],"takhrij":"متفق عليه: رواه البخاريّ في الرقاق (6459)، ومسلم في الزهد والرقائق (28:2972) كلاهما من طريق عبد العزيز بن أبي حازم، عن يزيد بن رومان، عن عروة، عن عائشة فذكرته. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6459) and Muslim (2972:28). The wording is that of Muslim.","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah used to say: “By Allah, my nephew, we would see one new moon, then another new moon, then another new moon—three new moons over the course of two months—without any fire being lit in the houses of the Messenger of Allah ﷺ.” I asked: “Aunt, then what sustained you?” She replied: “The two black things: dates and water. However, the Messenger of Allah ﷺ had neighbors from the Anṣār who owned milch animals that they lent out for their milk. They would send some of that milk to the Messenger of Allah ﷺ, and he would give it to us to drink.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6459)، ومسلم (28:2972)، واللفظ لمسلم."},{"num":15166,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَا فِي بَيْتِي مِنْ شَىْءٍ يَأْكُلُهُ ذُو كَبِدٍ، إِلاَّ شَطْرُ شَعِيرٍ، فِي رَفٍّ لِي، فَأَكَلْتُ مِنْهُ حَتَّى طَالَ عَلَىَّ، فَكِلْتُهُ فَفَنِيَ."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3097)، ومسلم في الزهد (2973) كلاهما من طريق أبي أسامة، عن هشام، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3097) and Muslim (2973).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The Messenger of Allah ﷺ died while there was nothing on my shelf that any living creature could eat except a small quantity of barley. I continued eating from it for a long time, until I measured it, and then it ran out.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3097)، ومسلم (2973)."},{"num":15167,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  إِنَّمَا كَانَ فِرَاشُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّذِي يَنَامُ عَلَيْهِ أَدَمًا، حَشْوُهُ لِيفٌ."],"takhrij":"متفق عليه: رواه البخاريّ في الرقاق (6456)، ومسلم في اللباس (38:2082) كلاهما من طريق هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6456) and Muslim (2082:38).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The mattress upon which the Messenger of Allah ﷺ slept was made of leather and stuffed with palm fiber.”"]}},"tuhfa":{},"full":1,"rep":[9624,15400],"tks":"متفق عليه: رواه البخاري (6456)، ومسلم (38:2082)."},{"num":15168,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  كَانَ وِسَادَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّتِي يَتَّكِئُ عَلَيْهَا مِنْ أَدَمٍ حَشْوُهَا لِيفٌ."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (37:2082) عن أبي بكر بن أبي شيبة، حدثنا عبدة بن سليمان، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2082:37).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The cushion upon which the Messenger of Allah ﷺ would recline was made of leather and stuffed with palm fiber.”"]}},"tuhfa":{},"full":1,"rep":[9625,15399],"tks":"صحيح: رواه مسلم (37:2082)."},{"num":15169,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّهَا قَالَتْ: يَا ابْنَ أُخْتِي، كَانَ شَعْرُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوْقَ الْوَفْرَةِ، وَدُونَ الْجُمَّةِ، وَايْمُ اللَّهِ يَا ابْنَ أُخْتِي، إِنْ كَانَ لَيَمُرُّ عَلَى آلِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الشَّهْرُ، مَا يُوقَدُ فِي بَيْتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ نَارٍ، إِلَّا أَنْ يَكُونَ اللُّحَيْمُ، وَمَا هُوَ إِلَّا الْأَسْوَدَانِ: الْمَاءُ وَالتَّمْرُ، إِلَّا أَنَّ حَوْلَنَا أَهْلَ دُورٍ مِنَ الْأَنْصَارِ جَزَاهُمُ اللهُ خَيْرًا فِي الْحَدِيثِ وَالْقَدِيمِ، فَكُلُّ يَوْمٍ يَبْعَثُونَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِغَزِيرَةِ شَاتِهِمْ، يَعْنِي: فَيَنَالُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ ذَلِكَ اللَّبَنِ، وَلَقَدْ تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَا فِي رَفِّي مِنْ طَعَامٍ يَأْكُلُهُ ذُو كَبِدٍ إِلَّا قَرِيبٌ مِنْ شَطْرِ شَعِيرٍ، فَأَكَلْتُ مِنْهُ حَتَّى طَالَ عَلَيَّ لَا يَفْنَى، فَكِلْتُهُ فَفَنِيَ، فَلَيْتَنِي لَمْ أَكُنْ كِلْتُهُ، وَايْمُ اللَّهِ لَأَنْ كَانَ ضِجَاعُهُ مِنْ أَدَمٍ حَشْوُهُ لِيفٌ."],"takhrij":"حسن: رواه أحمد (24768) عن سُريج، حدثنا ابن أبي الزناد، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (24768). Most of the individual portions of this hadith are found in the two Ṣaḥīḥ collections, though not in this same lengthy combined wording.","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah said: “O son of my sister, the hair of the Messenger of Allah ﷺ was longer than the wafrah and shorter than the jummah. By Allah, O son of my sister, an entire month would pass over the family of Muḥammad ﷺ without a fire being lit in the house of the Messenger of Allah ﷺ, unless some small amount of meat was brought. Otherwise, there were only the two black things: water and dates. Around us were households of the Anṣār—may Allah reward them with good, in recent times and in earlier times—and every day they would send to the Messenger of Allah ﷺ from the abundant milk of their sheep, meaning that the Messenger of Allah ﷺ would receive some of that milk. The Messenger of Allah ﷺ died while there was nothing on my shelf that any living creature could eat except nearly half a measure of barley. I kept eating from it for so long that it seemed it would never run out. Then I measured it, and it came to an end. If only I had never measured it. And by Allah, his bedding was made of leather stuffed with palm fiber.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (24768). وأكثر فقرات الحديث في الصحيحين لكن لا يوجد بهذا السياق الطويل."},{"num":15170,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: لَقَدْ كَانَ يَأْتِي عَلَى آلِ مُحَمَّدٍ الشَّهْرُ، مَا يُرَى فِي بيتٍ مِنْ بُيُوتِهِ الدُّخَانُ، قُلْتُ: يَا أمّهْ، وَمَا كَانَ طَعَامُهُمْ؟ قَالَتِ: الأَسْوَدَانِ: التَّمْرُ وَالْمَاءُ، غَيْرَ أَنَّهُ كَانَ لَهُ جِيرَانُ صدْق من الأَنْصَارِ، وَكَانَ لَهُمْ رَبَائِبُ، فَكَانُوا يَبْعَثُونَ إِلَيْهِ من أَلْبَانَهَا."],"takhrij":"حسن: رواه ابن ماجه (4145)، وأحمد (25491) كلاهما من طريق يزيد بن هارون، حدثنا محمد بن عمرو، عن أبي سلمة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (4145) and Aḥmad (25491).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated: “A whole month would pass over the family of Muḥammad ﷺ without smoke being seen in any of his houses.” It was asked: “Mother, what then was their food?” She replied: “The two black things: dates and water. However, he had trustworthy neighbors from the Anṣār who owned sheep kept at home, and they would send him some of their milk.”"]},"buhuth":{"en":["The word “rabāʾib”, singular rabībah, refers to sheep kept at the house rather than left to graze freely."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (4145)، وأحمد (25491)."},{"num":15171,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ رَبَاحٍ، قَالَ: سَمِعْتُ عَمْرَو بْنَ الْعَاصِ، يَقُولُ: لَقَدْ أَصْبَحْتُمْ، وَأَمْسَيْتُمْ، تَرْغَبُونَ فِيمَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَزْهَدُ فِيهِ: أَصْبَحْتُمْ تَرْغَبُونَ فِي الدُّنْيَا، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَزْهَدُ فِيهَا، وَاللهِ مَا أَتَتْ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةٌ مِنْ دَهْرِهِ إِلَّا كَانَ الَّذِي عَلَيْهِ أَكْثَرَ مِمَّا لَهُ، قَالَ: فَقَالَ لَهُ بَعْضُ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَدْ رَأَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَسْلِفُ."],"takhrij":"صحيح: رواه أحمد (17817) عن يحيى بن إسحاق – هو السيلحيني -، عن يزيد بن أبي حبيب، عن عُليّ بن رباح قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (17817).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿAlī ibn Rabāḥ narrated: I heard ʿAmr ibn al-ʿĀṣ say: “You have reached morning and evening desiring what the Messenger of Allah ﷺ used to renounce. You now desire this world, while the Messenger of Allah ﷺ was detached from it. By Allah, no night passed over the Messenger of Allah ﷺ except that what he owed was greater than what he possessed.” One of the Companions of the Messenger of Allah ﷺ said to him: “We did see the Messenger of Allah ﷺ borrow.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17817)."},{"num":15172,"demo":false,"sanad":"","matn":["عَنْ عُليّ بن رَبَاحٍ قَالَ: كُنْتُ عِنْدَ عَمْرِو بْنِ الْعَاصِ بِالْإِسْكَنْدَرِيَّةِ، فَذَكَرُوا مَا هُمْ فِيهِ مِنَ الْعَيْشِ، فَقَالَ رَجُلٌ مِنَ الصَّحَابَةِ: لَقَدْ تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَا شَبِعَ أَهْلُهُ مِنَ الْخُبْزِ الْغَلِيثِ.","قَالَ مُوسَى: يَعْنِي الشَّعِيرَ وَالسُّلْتَ إِذَا خُلِطَا."],"takhrij":"صحيح: رواه أحمد (17772) عن عبد الله بن يزيد قال: حدثنا موسى – هو ابن عُليّ بن رباح – قال: سمعت أبي يقول: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (17772).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿAlī ibn Rabāḥ narrated: I was with ʿAmr ibn al-ʿĀṣ in Alexandria when they began discussing the comfortable life they were enjoying. A man from among the Companions said: “The Messenger of Allah ﷺ died while his family had never eaten their fill of coarse bread.” Mūsā explained: “Meaning barley mixed with sult.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (17772)."},{"num":15173,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، قَالَتْ: أَكْثَرُ مَا عَلِمْتُ أُتِيَ بِهِ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْمَالِ لِخَرِيطَةٍ، فِيهَا ثَمَانِ مِائَةِ دِرْهَمٍ."],"takhrij":"حسن: رواه أحمد (26573)، والطبراني في الكبير (23/299) كلاهما من طريق بكر بن مضر، حدثنا موسى بن جبير، عن عبد الله بن رافع مولى أم سلمة، عن أم سلمة فذكرته.","grade":"حسن","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (26573) and al-Ṭabarānī in al-Muʿjam al-Kabīr (23/299).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["The Mother of the Believers, Umm Salamah, narrated: “The largest amount of money that I knew to have been brought to the Prophet of Allah ﷺ at one time was a small purse containing eight hundred dirhams.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26573)، والطبراني في الكبير (23/299)."},{"num":15174,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، قَالَ: أَلَسْتُمْ فِي طَعَامٍ وَشَرَابٍ مَا شِئْتُمْ؟ لَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ   وَمَا يَجِدُ مِنَ الدَّقَلِ مَا يَمْلأُ بِهِ بَطْنَهُ.","زاد في رواية: وَمَا تَرْضَوْنَ دُونَ أَلْوَانِ التَّمْرِ وَالزُّبْدِ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (2977) من طرق عن أبي الأحوص، عن سماك، عن النعمان بن بشير فذكره.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2977).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said: “Are you not now enjoying whatever food and drink you desire? I saw your Prophet ﷺ when he could not even find enough inferior dates to fill his stomach.” Another narration adds: “Yet you are not satisfied today unless you have different varieties of dates and butter.”"]},"buhuth":{"ar":["وقوله: “الدقل” التمر الرديء."],"en":["The word “al-daql” means low-quality dates."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2977)."},{"num":15175,"demo":false,"sanad":"","matn":["عَنْ سِمَاكِ بْنِ حَرْبٍ قَالَ: سَمِعْتُ النُّعْمَانَ يَخْطُبُ قَالَ:  ذَكَرَ عُمَرُ مَا أَصَابَ النَّاسُ مِنَ الدُّنْيَا، فَقَالَ: لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَظَلُّ الْيَوْمَ يَلْتَوِي مَا يَجِدُ دَقَلًا يَمْلَأُ بِهِ بَطْنَهُ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (2978) من طرق عن محمد بن جعفر، عن شعبة، عن سماك بن حرب فذكره.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2978).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Simāk ibn Ḥarb narrated: I heard al-Nuʿmān delivering a sermon. He mentioned that ʿUmar spoke about the worldly abundance people had attained and said: “I saw the Messenger of Allah ﷺ spend an entire day twisting from hunger, unable to find even poor-quality dates with which to fill his stomach.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2978)."},{"num":15176,"demo":false,"sanad":"","matn":["عن قَتَادَةَ قَالَ: كُنَّا نَأْتِي أَنَسَ بْنَ مَالِكٍ، وَخَبَّازُهُ قَائِمٌ وَقَالَ: كُلُوا فَمَا أَعْلَمُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَغِيفًا مُرَقَّقًا، حَتَّى لَحِقَ بِاللَّهِ، وَلاَ رَأَى شَاةً سَمِيطًا بِعَيْنِهِ قَطُّ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6457) عن هدبة بن خالد، حدثنا همام بن يحيى، حدثنا قتادة فذكره.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6457).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Qatādah narrated: We used to visit Anas ibn Mālik while his baker was standing nearby. Anas would say: “Eat. As far as I know, the Prophet ﷺ never saw a thin, refined loaf of bread until he met Allah, nor did he ever see an entire roasted sheep with his own eyes.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6457)."},{"num":15177,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمْ يَأْكُلِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى خِوَانٍ حَتَّى مَاتَ، وَمَا أَكَلَ خُبْزًا مُرَقَّقًا حَتَّى مَاتَ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6450) عن أبي معمر، حدثنا عبد الوارث، حدثنا سعيد بن أبي عروبة، عن قتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6450).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik narrated: “The Prophet ﷺ never ate from a raised dining table until he died, and he never ate refined thin bread until he died.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6450)."},{"num":15178,"demo":false,"sanad":"","matn":["عن أَنَسَ، أَنَّ فَاطِمَةَ جَاءَتْ بِكِسْرَةِ خُبْزٍ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ: مَا هَذِهِ الكسرة يَا فَاطِمَةُ؟ قَالَتْ: قُرْصٌ خبزتهن فَلَمْ تَطِبْ نَفْسِي حَتَّى أَتَيْتُكَ بِهَذِهِ الْكِسْرَةِ، فَقَالَ: أَمَا إِنَّهُ أَوَّلُ طَعَامٍ دَخَلَ فم أَبِيكِ مُنْذُ ثَلَاثَةِ أَيَّامٍ."],"takhrij":"حسن: رواه ابن سعد في الطبقات (343)، والطبراني في الكبير (1/232) كلاهما من طريق هشام بن عبد الملك أبي الوليد الطيالسي، أخبرنا أبو هاشم صاحب الزعفران، أخبرنا محمد بن عبد الله أن أنس بن مالك حدثه فذكره.","grade":"حسن","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Saʿd in al-Ṭabaqāt (1/400) and al-Ṭabarānī in al-Muʿjam al-Kabīr (1/232).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas narrated: Fāṭimah came to the Prophet ﷺ carrying a piece of bread. He asked: “What is this piece of bread, O Fāṭimah?” She replied: “It is a loaf that I baked, and I could not feel at ease until I brought you this piece.” He said: “Indeed, this is the first food to enter your father’s mouth in three days.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن سعد في الطبقات (343)، والطبراني في الكبير (1/232)."},{"num":15179,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَازِمٍ، قَالَ: سَأَلْتُ سَهْلَ بْنَ سَعْدٍ فَقُلْتُ: هَلْ أَكَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّقِيَّ؟ فَقَالَ سَهْلٌ: مَا رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّقِيَّ مِنْ حِينَ ابْتَعَثَهُ اللَّهُ حَتَّى قَبَضَهُ اللَّهُ. قَالَ: فَقُلْتُ: هَلْ كَانَتْ لَكُمْ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنَاخِلُ؟ قَالَ: مَا رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُنْخُلاً مِنْ حِينَ ابْتَعَثَهُ اللَّهُ حَتَّى قَبَضَهُ. قَالَ: قُلْتُ: كَيْفَ كُنْتُمْ تَأْكُلُونَ الشَّعِيرَ غَيْرَ مَنْخُولٍ؟ قَالَ: كُنَّا نَطْحَنُهُ وَنَنْفُخُهُ، فَيَطِيرُ مَا طَارَ، وَمَا بَقِيَ ثَرَّيْنَاهُ فَأَكَلْنَاهُ."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5413) عن قتيبة بن سعيد، حدثنا يعقوب، عن أبي حازم قال: فذكره.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5413).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abū Ḥāzim narrated: I asked Sahl ibn Saʿd: “Did the Messenger of Allah ﷺ ever eat naqī?” Sahl replied: “The Messenger of Allah ﷺ never even saw refined white flour from the time Allah sent him as a Prophet until Allah took his soul.” I asked: “Did you have sieves during the time of the Messenger of Allah ﷺ?” He replied: “The Messenger of Allah ﷺ never saw a sieve from the time Allah sent him until Allah took his soul.” I asked: “Then how did you eat barley without sifting it?” He replied: “We would grind it and blow upon it. Whatever bran flew away would fly away, and whatever remained we would moisten, then eat it.”"]},"buhuth":{"en":["The word “al-naqī” means bread made from clean, refined white flour.","“Manākhil” is the plural of minkhal, a sieve used to sift and refine wheat, barley, and similar grains. What remains after the grain is refined and sifted is bran."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7359],"tks":"صحيح: رواه البخاري (5413)."},{"num":15180,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ قَالَ: مَا كَانَ يَفْضُلُ عَنْ أَهْلِ بَيْتِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُبْزُ الشَّعِيرِ."],"takhrij":"صحيح: رواه الترمذي في جامعه (2359)، وفي الشمائل (144)، وأحمد (22244) كلاهما من طريق حريز بن عثمان (هو الرحبي)، عن سليم بن عامر قال: سمعت أبا أمامة يقول: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2359), in al-Shamā’il (144), and by Aḥmad (22244).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abū Umāmah said: “There was never any barley bread left over in the household of the Prophet ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2359)، وفي الشمائل (144)، وأحمد (22244)."},{"num":15181,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَدَّخِرُ شَيْئًا لغدٍ."],"takhrij":"حسن: رواه الترمذي (2362)، وابن حبان (6356)، والبيهقي في شعب الإيمان (1391) كلهم من طريق قتيبة بن سعيد، حدثنا جعفر بن سليمان، عن ثابت، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2362), Ibn Ḥibbān (6356), and al-Bayhaqī in Shuʿab al-Īmān (1391).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas narrated: “The Messenger of Allah ﷺ would not store anything for the following day.”"]},"buhuth":{"en":["There is no contradiction between this hadith and the hadith narrated by al-Bukhārī (2904) and Muslim (1757:48), which states:","“The property of Banū al-Naḍīr belonged specifically to the Messenger of Allah ﷺ. He would spend from it on his family for a year, then use whatever remained for weapons and mounts as preparation in the path of Allah.”","The statement of Anas ibn Mālik refers to the period before the conquests, when the Muslims were in need of food and drink. The Prophet ﷺ would spend whatever was in his possession upon them and would not retain anything from it.","After the conquests, however, the Muslims became more self-sufficient and Allah expanded their worldly provision. The Prophet ﷺ would then store sufficient provision for his wives for one year."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2362)، وابن حبان (6356)، والبيهقي في شعب الإيمان (1391)."},{"num":15182,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ، عَنْ عُمَرَ بن الْخَطَّابِ قَالَ: فِي حَدِيثَ اعتزال النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نِسَاءَهُ الطويل: وَإِنَّهُ لَعَلَى حَصِيرٍ مَا بَيْنَهُ وَبَيْنَهُ شَيْءٌ، وَتَحْتَ رَأْسِهِ وِسَادَةٌ مِنْ أَدَمٍ حَشْوُهَا لِيفٌ، وَإِنَّ عِنْدَ رِجْلَيْهِ قَرَظًا مَضْبُورًا، وَعِنْدَ رَأْسِهِ أُهُبًا مُعَلَّقَةً، فَرَأَيْتُ أَثَرَ الْحَصِيرِ فِي جَنْبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَبَكَيْتُ فَقَالَ: مَا يُبْكِيكَ؟. فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ كِسْرَى وَقَيْصَرَ فِيمَا هُمَا فِيهِ، وَأَنْتَ رَسُولُ اللَّهِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَمَا تَرْضَى أَنْ تَكُونَ لَهُمَا الدُّنْيَا وَلَكَ الْآخِرَةُ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4913) ومسلم في الطلاق (1479: 31) كلاهما من طريق سليمان بن بلال، عن يحيى، أخبرني عبيد بن حنين، أنه سمع عبد الله بن عباس، يحدِّث، قال: فذكره، والسياق لمسلم. والحديث بطوله مذكور في تفسير سورة التحريم.","grade":"متفق عليه","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4913) and Muslim (1479:31).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbās narrated from ʿUmar ibn al-Khaṭṭāb, as part of the lengthy hadith concerning the Prophet ﷺ separating himself from his wives: The Prophet ﷺ was lying on a woven mat with nothing between him and it. Beneath his head was a leather cushion stuffed with palm fiber. Near his feet was a gathered quantity of qaraẓ, and near his head were hanging hides. ʿUmar said: I saw the marks of the mat on the side of the Messenger of Allah ﷺ and began to weep. He asked: “What makes you weep?” I replied: “O Messenger of Allah, Kisrā and Caesar live amid what they possess, while you are the Messenger of Allah?” The Messenger of Allah ﷺ replied: “Are you not satisfied that they should have this world while you have the Hereafter?”"]},"buhuth":{"en":["The phrase “min adam” means made of tanned leather; adam is the plural of adīm.","The word “maḍbūran” means gathered together.","“Ahuban muʿallaqah” means hanging hides. Ahab is the plural of ihāb, which can mean skin before tanning, though it is also said to mean skin generally."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4913)، ومسلم (1479: 31)."},{"num":15183,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: دَخَلْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ مُضْطَجِعٌ عَلَى سَرِيرٍ مُرْمَلٌ بِشَرِيطٍ، وَتَحْتَ رَأْسِهِ وَسَادَةٌ مِنْ أَدَمٍ، حَشْوُهَا لِيفٌ، فَدَخَلَ عَلَيْهِ نَفَرٌ مِنْ أَصْحَابِهِ، وَدَخَلَ عُمَرُ فَانْحَرَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، انْحِرَافَةً، فَلَمْ يَرَ عُمَرُ بَيْنَ جَنْبِهِ وَبَيْنَ الشَّرِيطِ ثَوْبًا، وَقَدْ أَثَّرَ الشَّرِيطُ بِجَنْبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَبَكَى عُمَرُ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا يُبْكِيكَ يَا عُمَرُ؟ قَالَ: وَاللهِ مَا أَبْكِي إِلَّا أَنْ أَكُونَ أَعْلَمُ أَنَّكَ أَكْرَمُ عَلَى اللَّهِ مِنْ كِسْرَى، وَقَيْصَرَ، وَهُمَا يَعِيثَانِ فِي الدُّنْيَا فِيمَا يَعِيثَانِ فِيهِ، وَأَنْتَ يَا رَسُولَ اللَّهِ، بِالْمَكَانِ الَّذِي أَرَى. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَا تَرْضَى أَنْ تَكُونَ لَهُمُ الدُّنْيَا وَلَنَا الْآخِرَةُ؟ قَالَ عُمَرُ: بَلَى، قَالَ: فَإِنَّهُ كَذَاكَ."],"takhrij":"حسن: رواه أحمد (12417)، وابن حبان (6362)، والبخاري في الأدب المفرد (1163) كلهم من طريق مبارك بن فضالة، حدثنا الحسن (هو البصري)، حدثنا أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (12417), Ibn Ḥibbān (6362), and al-Bukhārī in al-Adab al-Mufrad (1163).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik narrated: I entered upon the Messenger of Allah ﷺ while he was reclining on a bed woven with straps. Beneath his head was a leather cushion stuffed with palm fiber. A group of his Companions entered, and ʿUmar also entered. The Messenger of Allah ﷺ shifted slightly, and ʿUmar saw that there was no cloth between the side of the Prophet ﷺ and the woven straps of the bed. The straps had left marks on his side. ʿUmar began to weep. The Prophet ﷺ asked him: “What makes you weep, O ʿUmar?” He replied: “By Allah, I only weep because I know that you are more honored before Allah than Kisrā and Caesar, while they freely enjoy this world as they do, and you, O Messenger of Allah, are in the condition that I see.” The Prophet ﷺ said: “Are you not satisfied that they should have this world and we should have the Hereafter?” ʿUmar replied: “Yes.” He said: “Then that is indeed how it is.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (12417)، وابن حبان (6362)، والبخاري في الأدب المفرد (1163)."},{"num":15184,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَجْتَمِعْ لَهُ غَدَاءٌ، وَلَا عَشَاءٌ مِنْ خُبْزٍ وَلَحْمٍ، إِلَّا عَلَى ضَفَفٍ."],"takhrij":"صحيح: رواه الترمذي في الشمائل (139)، وأحمد (13859)، وأبو يعلى (3108)، وصحّحه ابن حبان (6359) كلهم من طريق عفان بن مسلم، حدثنا أبان بن يزيد، حدثنا قتادة، عن أنس قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī in al-Shamā’il (139), Aḥmad (13859), Abū Yaʿlā (3108), and authenticated by Ibn Ḥibbān (6359).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik narrated: “The Messenger of Allah ﷺ never had a lunch or dinner of bread and meat except in a state of ḍafaf.”"]},"buhuth":{"en":["The word “ḍafaf”, with fatḥah on both the ḍād and fāʾ, can mean constriction and hardship.","It has also been interpreted as people gathering together, meaning that such a meal occurred when guests were present."]}},"tuhfa":{},"full":1,"dr":1,"rep":[14319],"tks":"صحيح: رواه الترمذي في الشمائل (139)، وأحمد (13859)، وأبو يعلى (3108)، وصححه ابن حبان (6359)."},{"num":15185,"demo":false,"sanad":"","matn":["عَنْ أَبِي طَلْحَةَ، قَالَ: شَكَوْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْجُوعَ، وَرَفَعْنَا عَنْ بُطُونِنَا عَنْ حَجَرٍ حَجَرٍ، فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ حَجَرَيْنِ."],"takhrij":"حسن: رواه الترمذي في الجامع (2371)، وفي الشمائل (134)، وأبو الشيخ في أخلاق النبي صلى الله عليه وسلم (223) كلاهما من طريق عبد الله بن أبي زياد، قال: حدثنا سيار بن حاتم، عن سهل بن أسلم، عن يزيد بن أبي منصور، عن أنس بن مالك، عن أبي طلحة قال: فذكره.","grade":"حسن","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī in al-Jāmiʿ (2371), in al-Shamā’il (134), and Abū al-Shaykh in Akhlāq al-Nabī ﷺ (223).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abū Ṭalḥah narrated: “We complained to the Messenger of Allah ﷺ about hunger and lifted our garments from our stomachs, each of us revealing one stone tied to his stomach. The Messenger of Allah ﷺ then lifted his garment from his stomach and revealed two stones.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي في الجامع (2371)، وفي الشمائل (134)، وأبو الشيخ في أخلاق النبي ﷺ (223)."},{"num":15186,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَصْبَحَ فِي آلِ مُحَمَّدٍ إِلاَّ مُدٌّ مِنْ طَعَامٍ. أَوْ مَا أَصْبَحَ فِي آلِ مُحَمَّدٍ مُدٌّ مِنْ طَعَامٍ."],"takhrij":"حسن: رواه ابن ماجه (4148) عن محمد بن يحيى، حدثنا أبو المغيرة (هو عبدالقدوس بن الحجاج الخولاني)، حدثنا عبد الرحمن بن عبد الله المسعودي، عن علي بن بذيمة، عن أبي عبيدة، عن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (4148).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “The family of Muḥammad entered the morning with only one mudd of food.” Or he said: “The family of Muḥammad did not enter the morning possessing even one mudd of food.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (4148)."},{"num":15187,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: لَقَدْ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا أَمْسَى عِنْدَ آلِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  صَاعُ بُرٍّ، وَلاَ صَاعُ حَبٍّ، وَإِنَّ عِنْدَهُ لَتِسْعَ نِسْوَةٍ.","وفي لفظ: مَا أَصْبَحَ لآلِ مُحَمَّدٍ صلى الله عليه وسلم إِلاَّ صَاعٌ وَلاَ أَمْسَى، وَإِنَّهُمْ لَتِسْعَةُ أَبْيَاتٍ."],"takhrij":"صحيح: رواه البخاري في البيوع (2069) من طرق عن هشام الدستوائي، عن قتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2069). The second wording is in al-Bukhārī (2508).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas narrated: I heard the Messenger of Allah ﷺ say: “The family of Muḥammad ﷺ did not reach evening with even one ṣāʿ of wheat or one ṣāʿ of grain.” Yet he had nine wives. In another wording: “The family of Muḥammad ﷺ did not enter either morning or evening possessing even one ṣāʿ.” Yet they comprised nine households."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2069). واللفظ الثاني: (2508)."},{"num":15188,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَقَاضَاهُ دَيْنًا كَانَ عَلَيْهِ، فَاشْتَدَّ عَلَيْهِ، حَتَّى قَالَ لَهُ: أُحَرِّجُ عَلَيْكَ إِلاَّ قَضَيْتَنِي. فَانْتَهَرَهُ أَصْحَابُهُ، وَقَالُوا: وَيْحَكَ تَدْرِي مَنْ تُكَلِّمُ؟ قَالَ: إِنِّي أَطْلُبُ حَقِّي. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلاَّ مَعَ صَاحِبِ الْحَقِّ كُنْتُمْ. ثُمَّ أَرْسَلَ إِلَى خَوْلَةَ بِنْتِ قَيْسٍ فَقَالَ لَهَا: إِنْ كَانَ عِنْدَكِ تَمْرٌ فَأَقْرِضِينَا حَتَّى يَأْتِيَنَا تَمْرٌ فَنَقْضِيَكِ. فَقَالَتْ: نَعَمْ، بِأَبِي أَنْتَ يَا رَسُولَ اللَّهِ. قَالَ: فَأَقْرَضَتْهُ، فَقَضَى الأَعْرَابِيَّ وَأَطْعَمَهُ، فَقَالَ: أَوْفَيْتَ، أَوْفَى اللَّهُ لَكَ. فَقَالَ: أُولَئِكَ خِيَارُ النَّاسِ، إِنَّهُ لاَ قُدِّسَتْ أُمَّةٌ لاَ يَأْخُذُ الضَّعِيفُ فِيهَا حَقَّهُ غَيْرَ مُتَعْتَعٍ."],"takhrij":"صحيح: رواه ابن ماجه (2426) واللفظ له، وابن أبي شيبة (22543) وعنه أبو يعلى (1091) من طريق محمد بن أبي عبيدة قال: حدثني أبي، عن الأعمش، عن أبي صالح، عن أبي سعيد الخدري قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (2426), and this is his wording, Ibn Abī Shaybah (22543), and through him by Abū Yaʿlā (1091).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: A Bedouin came to the Prophet ﷺ demanding repayment of a debt owed to him. He spoke harshly to the Prophet ﷺ until he said: “I adjure you to repay me.” The Companions rebuked him and said: “Woe to you! Do you know to whom you are speaking?” He replied: “I am only demanding my right.” The Prophet ﷺ said: “Why were you not standing with the one who has the right?” He then sent to Khawlah bint Qays and said to her: “If you have dates, lend some to us until dates come to us and we can repay you.” She replied: “Yes, may my father be sacrificed for you, O Messenger of Allah.” She lent him the dates. The Prophet ﷺ repaid the Bedouin and fed him. The Bedouin said: “You have repaid me in full. May Allah repay you in full.” The Prophet ﷺ said: “Such people are among the best of mankind. A nation is not sanctified in which the weak cannot obtain their rights without being troubled or harassed.”"]},"buhuth":{"en":["The word “ghayra mutaʿtaʿ” means without suffering harm, intimidation, disturbance, or harassment while claiming one’s right."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (2426) واللفظ له، وابن أبي شيبة (22543)، وعنه أبو يعلى (1091)."},{"num":15189,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ أُمَّ سُلَيْمٍ بَعَثَتْهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقِنَاعٍ عَلَيْهِ رُطَبٌ، فَجَعَلَ يَقْبِضُ قَبْضَةً فَيَبْعَثُ بِهَا إِلَى بَعْضِ أَزْوَاجِهِ، ثُمَّ يَقْبِضُ الْقَبْضَةَ فَيَبْعَثُ بِهَا إِلَى بَعْضِ أَزْوَاجِهِ، ثُمَّ جَلَسَ فَأَكَلَ بَقِيَّتَهُ أَكْلَ رَجُلٍ يُعْلَمُ أَنَّهُ يَشْتَهِيهِ."],"takhrij":"صحيح: رواه أحمد (12267)، وأبو يعلى (2896)، وابن حبان (695) كلهم من طرق عن همام (هو ابن يحيى العوذي)، حدثنا قتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب كيف كان عيش النبي ﷺ","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (12267), Abū Yaʿlā (2896), and Ibn Ḥibbān (695).","chapter_en":"How the Prophet ﷺ Lived","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik narrated: Umm Sulaym sent him to the Messenger of Allah ﷺ with a tray containing fresh dates. The Prophet ﷺ took a handful and sent it to one of his wives, then took another handful and sent it to another of his wives. Then he sat down and ate what remained, eating like a man who clearly desired and enjoyed the food."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (12267)، وأبو يعلى (2896)، وابن حبان (695)."},{"num":15190,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: كُنْتُ أَمْشِي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَرَّةِ الْمَدِينَةِ فَاسْتَقْبَلَنَا أُحُدٌ فَقَالَ: يَا أَبَا ذَرٍّ، قُلْتُ: لَبَّيْكَ يَا رَسُولَ اللَّهِ، قَالَ: مَا يَسُرُّنِي أَنَّ عِنْدِي مِثْلَ أُحُدٍ هَذَا ذَهَبًا تَمْضِي علي ثَالِثَةٌ، وَعِنْدِي مِنْهُ دِينَارٌ، إِلاَّ شَيْئًا أُرْصِدُهُ لِدَيْنٍ، إِلاَّ أَنْ أَقُولَ بِهِ فِي عِبَادِ اللَّهِ هَكَذَا وَهَكَذَا وَهَكَذَا -عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ وَمِنْ خَلْفِهِ- ثُمَّ مَشَى ثُمَّ قَالَ: إِنَّ الأَكْثَرِينَ هُمُ الأَقَلُّونَ يَوْمَ الْقِيَامَةِ إِلاَّ مَنْ قَالَ هَكَذَا وَهَكَذَا وَهَكَذَا -عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ وَمِنْ خَلْفِهِ- وَقَلِيلٌ مَا هُمْ، ثُمَّ قَالَ لِي: مَكَانَكَ، لاَ تَبْرَحْ حَتَّى آتِيَكَ. ثُمَّ انْطَلَقَ فِي سَوَادِ اللَّيْلِ حَتَّى تَوَارَى، فَسَمِعْتُ صَوْتًا قَدِ ارْتَفَعَ، فَتَخَوَّفْتُ أَنْ يَكُونَ أحدٌ عَرَضَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَرَدْتُ أَنْ آتِيَهُ، فَذَكَرْتُ قَوْلَهُ لِي: لاَ تَبْرَحْ حَتَّى آتِيَكَ، فَلَمْ أَبْرَحْ حَتَّى أَتَانِي، قُلْتُ: يَا رَسُولَ اللَّهِ، لَقَدْ سَمِعْتُ صَوْتًا تَخَوَّفْتُ، فَذَكَرْتُ لَهُ، فَقَالَ: وَهَلْ سَمِعْتَهُ؟ قُلْتُ: نَعَمْ، قَالَ: ذَاكَ جِبْرِيلُ أَتَانِي، فَقَالَ: مَنْ مَاتَ مِنْ أُمَّتِكَ لاَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ. قُلْتُ: وَإِنْ زَنَى وَإِنْ سَرَقَ؟ قَالَ: وَإِنْ زَنَى وَإِنْ سَرَقَ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6444)، ومسلم في الزكاة (94: 32) كلاهما من طريق الأعمش، عن زيد بن وهب، عن أبي ذر فذكره.","grade":"متفق عليه","chapter_ar":"باب حرص النبي ﷺ على قسمة ما عنده من مال إلا شيئًا يرصده لدينه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6444) and Muslim (94:32).","chapter_en":"The Prophet’s ﷺ Eagerness to Distribute Whatever Wealth He Possessed, Except What He Reserved for a Debt","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abū Dharr narrated: I was walking with the Prophet ﷺ through the rocky plain of Madinah when Mount Uḥud came into view. He said: “O Abū Dharr.” I replied: “At your service, O Messenger of Allah.” He said: “It would not please me to possess an amount of gold equal to this Mount Uḥud and have three days pass while even one dinar remained with me, except something I had reserved for a debt. Rather, I would distribute it among the servants of Allah like this, and like this, and like this.” He gestured to his right, his left, and behind him. Then he walked on and said: “Those who possess the most will be those who possess the least on the Day of Resurrection, except those who distribute their wealth like this, and like this, and like this”— to their right, left, and behind them— “and how few they are.” Then he said to me: “Stay where you are and do not leave until I return.” He went into the darkness of the night until he disappeared from sight. I then heard a raised voice and feared that someone might have confronted the Prophet ﷺ. I wanted to go to him, but I remembered his words: “Do not leave until I return.” So I remained until he came back. I said: “O Messenger of Allah, I heard a voice and became afraid.” I told him what had happened. He asked: “Did you hear it?” I replied: “Yes.” He said: “That was Jibrīl. He came to me and said: ‘Whoever from your Ummah dies without associating anything with Allah will enter Paradise.’” I asked: “Even if he commits adultery and steals?” He replied: “Even if he commits adultery and steals.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6444)، ومسلم (94: 32)."},{"num":15191,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَوْ كَانَ لِي مِثْلُ أُحُدٍ ذَهَبًا لَسَرَّنِي أَنْ لاَ تَمُرَّ عليّ ثَلاَثُ لَيَالٍ، وَعِنْدِي مِنْهُ شيء إِلاَّ شَيْئًا أُرْصِدُهُ لِدَيْنٍ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6445)، ومسلم في الزكاة (991) كلاهما من طرق عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب حرص النبي ﷺ على قسمة ما عنده من مال إلا شيئًا يرصده لدينه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6445) and Muslim (991).","chapter_en":"The Prophet’s ﷺ Eagerness to Distribute Whatever Wealth He Possessed, Except What He Reserved for a Debt","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “If I possessed an amount of gold equal to Mount Uḥud, it would please me that three nights should not pass while any of it remained with me, except something I reserved to repay a debt.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6445)، ومسلم (991)."},{"num":15192,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: مَا يَسُرُّنِي أَنَّ أُحُدًا لِي ذَهَبٌ أُنْفِقُهُ فِي سَبِيلِ اللَّهِ، أَمُوتُ يَوْمَ أَمُوتُ أَتْرُكُ مِنْهُ دِينَارًا إِلَّا دِينَارًا أُعِدُّهُ لِغَرِيمٍ إِنْ كَانَ. فَمَاتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَا تَرَكَ دِينَارًا، وَلَا دِرْهَمًا، وَلَا عَبْدًا، وَلَا وَلِيدَةً، وَتَرَكَ دِرْعَهُ رَهْنًا بِثَلَاثِينَ صَاعًا مِنْ شَعِيرٍ."],"takhrij":"حسن: رواه البزار –كشف الأستار (3682) عن بشر بن معاذ العقدي، حدثنا عباد بن العوام، عن هلال بن خباب، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب حرص النبي ﷺ على قسمة ما عنده من مال إلا شيئًا يرصده لدينه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār, as cited in Kashf al-Astār (3682).","chapter_en":"The Prophet’s ﷺ Eagerness to Distribute Whatever Wealth He Possessed, Except What He Reserved for a Debt","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Prophet ﷺ said: “It would not please me to possess gold equal to Mount Uḥud to spend in the path of Allah and then die while leaving behind even one dinar from it, except a dinar I had set aside for a creditor, if there were one.” The Messenger of Allah ﷺ died leaving behind neither a dinar nor a dirham, neither a male slave nor a female slave. He left his armor pledged as collateral for thirty ṣāʿs of barley."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (3682)."},{"num":15193,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ سَاهِمُ الْوَجْهِ. قَالَتْ: فَحَسِبْتُ أَنَّ ذَلِكَ مِنْ وَجَعٍ، فَقُلْتُ: يَا نَبِيَّ اللَّهِ، مَا لَكَ سَاهِمُ الْوَجْهِ؟ قَالَ: مِنْ أَجْلِ الدَّنَانِيرِ السَّبْعَةِ الَّتِي أَتَتْنَا أَمْسِ، أَمْسَيْنَا وَهِيَ فِي خُصْمِ الْفِرَاشِ."],"takhrij":"صحيح: رواه أحمد (26514)، وأبو يعلى (7017)، وابن حبان (5160)، والطبراني في الكبير (23/327) كلهم من طريق عبد الملك بن عمير، عن ربعي بن حراش، عن أم سلمة فذكرته. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب حرص النبي ﷺ على قسمة ما عنده من مال إلا شيئًا يرصده لدينه","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (26514), Abū Yaʿlā (7017), Ibn Ḥibbān (5160), and al-Ṭabarānī in al-Muʿjam al-Kabīr (23/327).","chapter_en":"The Prophet’s ﷺ Eagerness to Distribute Whatever Wealth He Possessed, Except What He Reserved for a Debt","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Umm Salamah narrated: The Messenger of Allah ﷺ entered upon me with a changed expression on his face. I thought he was in pain, so I asked: “O Prophet of Allah, why does your face look troubled?” He replied: “Because of the seven dinars that came to us yesterday. We passed the night while they were still lying at the edge of the bedding.”"]},"buhuth":{"en":["The expression “sāhim al-wajh” means that his facial expression had changed.","The phrase “fī khuṣm al-firāsh” means at the edge or side of the bedding.","The author states that this hadith is understood as relating to a particular characteristic of the Prophet ﷺ: he was not pleased for anything to remain in his house until the following day, due to the perfection of his reliance upon Allah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (26514)، وأبو يعلى (7017)، وابن حبان (5160)، والطبراني في الكبير (23/327)."},{"num":15194,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلاً وَلَبَكَيْتُمْ كَثِيرًا."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6486) عن سليمان بن حرب، حدثنا شعبة، عن موسى بن أنس، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب قول النبي ﷺ: لو تعلمون ما أعلم لضحكتم قليلًا ولبكيتم كثيرًا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6486) and Muslim in The Book of Virtues (2359).","chapter_en":"The Prophet’s ﷺ Statement: “If You Knew What I Know, You Would Laugh Little and Weep Much”","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ said: “If you knew what I know, you would laugh little and weep much.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6486)، ومسلم (2359)."},{"num":15195,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ أَبُو الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَبَكَيْتُمْ كَثِيرًا، وَلَضَحِكْتُمْ قَلِيلاً."],"takhrij":"صحيح: رواه البخاري في الأيمان والنذور (6637) عن إبراهيم بن موسى، أخبرنا هشام-هو ابن يوسف- عن معمر، عن همام، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب قول النبي ﷺ: لو تعلمون ما أعلم لضحكتم قليلًا ولبكيتم كثيرًا","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6637).","chapter_en":"The Prophet’s ﷺ Statement: “If You Knew What I Know, You Would Laugh Little and Weep Much”","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that Abū al-Qāsim ﷺ said: “By the One in whose Hand is the soul of Muḥammad, if you knew what I know, you would laugh little and weep much.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6637)."},{"num":15196,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وَقَّاصٍ قَالَ: إِنِّي لأَوَّلُ الْعَرَبِ رَمَى بِسَهْمٍ فِي سَبِيلِ اللَّهِ، وَكُنَّا نَغْزُو مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَا لَنَا طَعَامٌ إِلاَّ وَرَقُ الشَّجَرِ حَتَّى إِنَّ أَحَدَنَا لَيَضَعُ كَمَا يَضَعُ الْبَعِيرُ أَوِ الشَّاةُ مَا لَهُ خِلْطٌ، ثُمَّ أَصْبَحَتْ بَنُو أَسَدٍ تُعَزِّرُنِي عَلَى الإِسْلاَمِ، لَقَدْ خِبْتُ إذًا، وَضَلَّ عَمَلِي، وَكَانُوا وَشَوْا بِهِ إِلَى عُمَرَ قَالُوا: لاَ يُحْسِنُ يُصَلِّي."],"takhrij":"متفق عليه: رواه البخاري في فضائل الصحابة (3728)، ومسلم في الزهد والرقائق (2966)كلاهما من طرق عن إسماعيل بن أبي خالد، عن قيس قال: سمعت سعد بن أبي وقاص فذكره.","grade":"متفق عليه","chapter_ar":"باب عيش الصحابة","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3728) and Muslim (2966).","chapter_en":"The Living Conditions of the Companions","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ said: “I was the first Arab to shoot an arrow in the path of Allah. We used to go on military expeditions with the Prophet ﷺ while having no food except tree leaves, until one of us would relieve himself like a camel or a sheep, with no mixture in his stool. And now Banū Asad are trying to teach and correct me regarding Islam! If that were so, then I would indeed have failed and my deeds would have gone to waste.” They had complained about him to ʿUmar, saying: “He does not know how to pray properly.”"]},"buhuth":{"en":["The expression “tuʿazzirunī” here means “to correct and instruct me.” From the same root comes the ruler’s disciplinary punishment, intended to correct a person through discipline."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3728)، ومسلم (2966)."},{"num":15197,"demo":false,"sanad":"","matn":["عَنْ خَالِدِ بْنِ عُمَيْرٍ الْعَدَوِيِّ، قَالَ:  خَطَبَنَا عُتْبَةُ بْنُ غَزْوَانَ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: أَمَّا بَعْدُ، فَإِنَّ الدُّنْيَا قَدْ آذَنَتْ بِصُرْمٍ، وَوَلَّتْ حَذَّاءَ، وَلَمْ يَبْقَ مِنْهَا إِلَّا صُبَابَةٌ كَصُبَابَةِ الْإِنَاءِ، يَتَصَابُّهَا صَاحِبُهَا، وَإِنَّكُمْ مُنْتَقِلُونَ مِنْهَا إِلَى دَارٍ لَا زَوَالَ لَهَا، فَانْتَقِلُوا بِخَيْرِ مَا بِحَضْرَتِكُمْ، فَإِنَّهُ قَدْ ذُكِرَ لَنَا: أَنَّ الْحَجَرَ يُلْقَى مِنْ شَفَةِ جَهَنَّمَ، فَيَهْوِي فِيهَا سَبْعِينَ عَامًا، لَا يُدْرِكُ لَهَا قَعْرًا، وَوَاللهِ لَتُمْلَأَنَّ، أَفَعَجِبْتُمْ؟ وَلَقَدْ ذُكِرَ لَنَا أَنَّ مَا بَيْنَ مِصْرَاعَيْنِ مِنْ مَصَارِيعِ الْجَنَّةِ، مَسِيرَةُ أَرْبَعِينَ سَنَةً، وَلَيَأْتِيَنَّ عَلَيْهَا يَوْمٌ وَهُوَ كَظِيظٌ مِنَ الزِّحَامِ، وَلَقَدْ رَأَيْتُنِي سَابِعَ سَبْعَةٍ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَا لَنَا طَعَامٌ إِلَّا وَرَقُ الشَّجَرِ، حَتَّى قَرِحَتْ أَشْدَاقُنَا، فَالْتَقَطْتُ بُرْدَةً فَشَقَقْتُهَا بَيْنِي وَبَيْنَ سَعْدِ بْنِ مَالِكٍ، فَاتَّزَرْتُ بِنِصْفِهَا وَاتَّزَرَ سَعْدٌ بِنِصْفِهَا، فَمَا أَصْبَحَ الْيَوْمَ مِنَّا أَحَدٌ إِلَّا أَصْبَحَ أَمِيرًا عَلَى مِصْرٍ مِنَ الْأَمْصَارِ، وَإِنِّي أَعُوذُ بِاللهِ أَنْ أَكُونَ فِي نَفْسِي عَظِيمًا، وَعِنْدَ اللهِ صَغِيرًا، وَإِنَّهَا لَمْ تَكُنْ نُبُوَّةٌ قَطُّ إِلَّا تَنَاسَخَتْ، حَتَّى يَكُونَ آخِرُ عَاقِبَتِهَا مُلْكًا، فَسَتَخْبُرُونَ وَتُجَرِّبُونَ الْأُمَرَاءَ بَعْدَنَا."],"takhrij":"صحيح: رواه مسلم في الزهد (2967) من طرق عن سليمان بن المغيرة، حدثنا حميد بن هلال، عن خالد بن عمير العدوي –وقد أدرك الجاهلية- فذكره.","grade":"صحيح","chapter_ar":"باب عيش الصحابة","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2967).","chapter_en":"The Living Conditions of the Companions","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Khālid ibn ʿUmayr al-ʿAdawī narrated: ʿUtbah ibn Ghazwān delivered a sermon to us. He praised Allah and extolled Him, then said: “To proceed: this world has announced its departure and turned away swiftly. Nothing remains of it except a small remnant, like the little water left at the bottom of a vessel which its owner tries to drain. You are moving from it to an abode that will never pass away, so move there carrying the best deeds you presently possess. We have been informed that a stone will be thrown from the edge of Hell and will fall through it for seventy years without reaching its bottom. By Allah, it will certainly be filled. Are you surprised? And we have been informed that the distance between two leaves of one of the gates of Paradise is a journey of forty years, yet a day will come when it will be crowded with people. I remember myself as one of seven men with the Messenger of Allah ﷺ. We had no food except tree leaves until the corners of our mouths became ulcerated. I found a cloak and split it between myself and Saʿd ibn Mālik. I wore half of it as a lower garment and Saʿd wore the other half. Today, not one of us remains except that he has become governor over one of the regions. I seek refuge in Allah from being great in my own estimation while being insignificant before Allah. No prophethood has ever remained except that it was eventually succeeded until its final outcome became kingship. You will come to know and experience the rulers who come after us.”"]},"buhuth":{"en":["ʿUtbah ibn Ghazwān was the governor of Baṣrah at that time."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13447],"tks":"صحيح: رواه مسلم (2967)."},{"num":15198,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عبدالله، أَنَّهُ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْثًا قِبَلَ السَّاحِلِ، فَأَمَّرَ عَلَيْهِمْ أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ وَهُمْ ثَلاَثُمِائَةٍ، قَالَ: وَأَنَا فِيهِمْ، قَالَ: فَخَرَجْنَا حَتَّى إِذَا كُنَّا بِبَعْضِ الطَّرِيقِ فَنِيَ الزَّادُ، فَأَمَرَ أَبُو عُبَيْدَةَ بِأَزْوَادِ ذَلِكَ الْجَيْشِ، فَجُمِعَ ذَلِكَ كُلُّهُ، فَكَانَ مزودي تَمْرٍ، قَالَ: فَكَانَ يقوتناه كُلَّ يَوْمٍ قَلِيلاً قَلِيلاً، حَتَّى فَنِيَ، وَلَمْ تصبنا إِلاَّ تَمْرَةٌ تَمْرَةٌ. فَقُلْتُ: وَمَا تُغْنِي تَمْرَةٌ؟، فَقَالَ: لَقَدْ وَجَدْنَا فَقْدَهَا حِينَ فَنِيَتْ... الحديث."],"takhrij":"متفق عليه: رواه مالك في صفة النبي صلى الله عليه وسلم (24) عن وهب بن كيسان، عن جابر بن عبد الله فذكره. ورواه البخاري في الشركة (2483)، ومسلم في الصيد والذبائح (1935:21) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب عيش الصحابة","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in Ṣifat al-Nabī (24), al-Bukhārī (2483), and Muslim (1935:21).","chapter_en":"The Living Conditions of the Companions","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The Messenger of Allah ﷺ sent an expedition toward the coast and appointed Abū ʿUbaydah ibn al-Jarrāḥ as its commander. They numbered three hundred men, and I was among them. We set out, and while we were on the road our provisions ran out. Abū ʿUbaydah ordered that all the provisions remaining with the army be gathered together. The two provision bags contained dates. He began giving us a small portion from them each day until they too ran out, and eventually each man received only a single date. I asked: “What benefit could one date provide?” Jābir replied: “We realized how valuable it had been once even that single date was gone.” The hadith continues."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (24)، والبخاري (2483)، ومسلم (1935: 21)."},{"num":15199,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَسَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا بَيْنَ أَصْحَابِهِ تَمْرًا، فَأَعْطَى كُلَّ إِنْسَانٍ سَبْعَ تَمَرَاتٍ، فَأَعْطَانِي سَبْعَ تَمَرَاتٍ إِحْدَاهُنَّ حَشَفَةٌ، فَلَمْ يَكُنْ فِيهِنَّ تَمْرَةٌ أَعْجَبَ إِلَىَّ مِنْهَا، شَدَّتْ فِي مَضَاغِي."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5411) عن أبي النعمان، حدثنا حماد بن زيد، عن عباس الجريري، عن أبي عثمان النهدي، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب عيش الصحابة","chapter_ur":"","part_ar":"كتاب الزهد والرقاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5411).","chapter_en":"The Living Conditions of the Companions","part_en":"Asceticism and Heart-Softening Narrations","group_ar":"جموع ما جاء في عيش النبي ﷺ وأصحابه","group_en":"Collection of What Has Been Narrated Concerning the Life of the Prophet ﷺ and His Companions","part_no":62,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated: One day the Prophet ﷺ distributed dates among his Companions, giving each person seven dates. He gave me seven dates, one of which was dry and shriveled. Yet there was no date among them that I liked more than that one because it took longer to chew."]},"buhuth":{"en":["The report comes in greater detail in the following hadith."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7389],"tks":"صحيح: رواه البخاري (5411)."}]);